var e=JSON.parse(`{"wrist-circles":{"name":"Bilek Çevirmeleri","description":"Dirsekleriniz yumuşak ve ön kollarınız önünüzde olacak şekilde dik durun. Her iki bileğinle de yavaşça dört sayım bir yönde ve dört sayım diğer yönde daireler çizerek parmaklarınızı gevşek tutun.","goodFor":"Her aletle çalışırken en çok çalışan bilekler ve ön kolları ısıtır.","alignmentCues":["Dirsekler hareket etmez; sadece bilekler hareket eder.","Daireleri büyük ve düzgün tutun."],"commonMistakes":["Daireleri aceleyle yaparak çabuk hareketlere dönüştürmek."]},"arm-circles":{"name":"Kol Çevirmeleri","description":"Ayaklar bel genişliğinde, kollar uzun. Her iki kolu da büyük ileri dairesi dört sayım boyunca, ardından geri dört sayım boyunca sallayarak omuz bıçaklarını kaydırın.","goodFor":"Çubuk dönüşleri ve kafes üzerindeki çalışmalar için omuzları açar.","alignmentCues":["Kollar başın üzerinden geçerken kaburgalar aşağıda kalsın.","Aşağıya inerken nefes verin."]},"shoulder-rolls":{"name":"Omuz Yuvarlamaları","description":"Kollarınız yanlarda gevşek. Omuzlarınızı kulaklara kaldırın, geriye ve aşağıya doğru yuvarlayın ve yavaş bir döngüde tekrarlayın.","goodFor":"Atışların sert ve kısa olmasını sağlayan gerilimi serbest bırakır."},"neck-rolls":{"name":"Boyun Yarım Çevirmeleri","description":"Çeneyi göğse doğru indirin ve başı geriye doğru eğmeden yarım daire şeklinde omuzdan omuza yavaşça süpürün.","goodFor":"Uzun süre yukarı bakarak atış yapmadan önce boyunu rahatlatır.","avoidIf":["Boyun yaralanması veya başı hareket ettirirken baş dönmesi."]},"hip-circles":{"name":"Bel Çevirmeleri","description":"Eller kalçalarda, dizler yumuşak. Kalçaları bir yöne iki çubuk boyunca ve diğer yöne iki çubuk boyunca yavaşça döndürün, başı düz tutarak.","goodFor":"Bel kafesleri ve akış için vücuda hazırlık yapar."},"torso-twists":{"name":"Gövde Bükülmeleri","description":"Ayaklar geniş, kollar gevşek. Kaburgaları sola ve sağa çevirin ve kolları boş kollardaki gibi etrafınızda sallanarak sarmalayın.","goodFor":"Çubuk dokumaları ve kafes geçişleri için rotasyonu uyandırır."},"knee-bounce":{"name":"Diz Sallama","description":"Ayaklarınızı kalçanızın altında tutun ve her vuruşta dizlerinizle hafifçe sıçrayın, kollarınız gevşekçe sallansın. Bacaklarınızda müziği bulun.","goodFor":"Bir nesne almadan önce ritmi vücudunuza kazandırır."},"one-ball-toss":{"name":"Bir Top Atma","description":"Bir topu sağ elinizde bel yüksekliğinde tutun. Topu içeriye doğru kavrayın, ardından göz hizasının biraz üzerindeki bir yay şeklinde fırlatın ve sol elinize düşsün. Aynı şekilde geri fırlatın. Gözünüzü elinizin değil, yayın tepesinde tutun.","goodFor":"Her bir yuvarlak atışın yapıldığı yay şeklindeki hareketi geliştirir.","alignmentCues":["Kollarınızın yanında kollar, ön kollar düz.","Her atışta tepe aynı yükseklikte olur.","Bel yüksekliğinde yakalayın ve elin biraz esnemesine izin verin."],"commonMistakes":["Topun ardından adım atmak zorunda kalacak şekilde ileriye fırlatmak.","Tepenin yerine elleri izlemek."]},"two-ball-exchange":{"name":"İki Top Değişimi","description":"Her elde bir top. Sağ topu yay şeklinde fırlatın; tepesine geldiğinde, sol topu içeriye doğru onun altından fırlatın. Her ikisini de yakalayın ve durun. Ardından sol el ile başlayın.","goodFor":"Değişimi öğretir: ilk atışın tepesinde ikinci atış yapılır.","alignmentCues":["İkinci atış, tepede, asla erken olmaz.","İkinci topu birinci topun içine fırlatın."],"commonMistakes":["İkinci topu geçerek değil, fırlatarak geçirmek.","Her ikisini birden fırlatmak."]},"cascade":{"name":"Üç Top Kaskadı","description":"Sağ elde iki top, sol elde bir top. Sağdan fırlatın; tepesine geldiğinde sol elden fırlatın; bu da tepesine geldiğinde tekrar sağ elden fırlatın. Her atış ritimde olur ve figür-8 yay şeklinde diğer elin içine geçer.","goodFor":"Yükselme hareketinin temel modelidir.","modifications":["Flash'i uygulayın: üç atış, üç yakalama, durun."],"deepen":["Daha hızlı tempoda, daha düşük tepelerle yuvarlak atış yapın.","Düşürmeden 20 yakalama sayın."],"alignmentCues":["İçten fırlatın, dıştan yakalayın.","Tepeler aynı yükseklikte, göz hizasında.","İleri doğru yürümeye devam ediyorsanız duvara yaslanın."],"commonMistakes":["Öne doğru atma ve modeli takip etme.","Bir atış yanlış gider hemen acele etmek."]},"reverse-cascade":{"name":"Ters Kasırga","description":"Kaskadın içe dönük hali: her top dışarıdan atılır, modelin tepesinden geçer ve ortadan diğer elin içine düşer.","goodFor":"Dışarıdan atışları geliştirir ve Mills Mess gibi trickleri açar.","alignmentCues":["Atışlar gelen topun üzerinden döner.","Ortada yakalama."]},"siteswap-423":{"name":"423","description":"Üç top modeli: yüksek bir kendi elinden atma (4), tutulan bir top (2), ardından bir kaskad atışı (3). 4 aynı taraftan yukarı çıkar; 2 sadece bir vuruş için tutulur.","goodFor":"İlk siteswap trickiniz: yüksek atışlar ve tutma öğrenir."},"siteswap-441":{"name":"441","description":"İki yüksek atış, kendi tarafında kalır (4, 4), ardından elden ele hızlı bir geçiş (1).","goodFor":"Yüksek atışlar ve hızlı geçişler arasındaki zamanlamayı geliştirir."},"two-in-one":{"name":"İki Bir Elde","description":"İki topu yan yana sütunlar halinde veya küçük dış çemberler halinde bir elde, her iki vuruşta bir atış yaparak jugglaj yapın. Her eli pratik yapın.","goodFor":"Dört top jugglajının temel bloğu."},"siteswap-531":{"name":"531","description":"Çok yüksek bir çapraz atış (5), bir kaskad atışı (3) ve hızlı bir geçiş (1). 5 yukarı atılırken diğer iki top altta çalışmaya devam eder.","goodFor":"Yükseklik kontrolü ve gösteri amaçlı üç top tricki."},"shower":{"name":"Üç Top Şöleni","description":"Toplar bir daire içinde hareket eder: sağ el her topu yüksekten sola atar ve sol el her birini doğrudan sağa geri geçirir.","goodFor":"Klasik dairesel model; hızlı elden ele geçişleri eğitir."},"mills-mess":{"name":"Mills Mess","description":"Kolların sürekli kesişip kesişmediği üç top kaskadı, bu yüzden her atış bedenin karşı tarafından gelir. Top yolları dokuma deseni oluşturur.","goodFor":"Koordinasyonu geliştirirken kalabalığı memnun eden ünlü bir gösteri."},"four-ball-fountain":{"name":"Dört Top Şelale","description":"Her el kendi sütununda iki topu juggler, el hareketleri değişiklik göstererek desenin asla kesişmemesini sağlar.","goodFor":"Dört top jugglerya için ilk deseniniz."},"sync-fountain":{"name":"Sincron Şelale","description":"Her iki el aynı anda atarak dört topu kendi tarafına doğru atar.","goodFor":"Simetriyi geliştirir ve senkronizasyonlu tricklere yol açar."},"five-ball-cascade":{"name":"Beş Top Kaskadı","description":"Beş top ile cascadenin devamı: yüksek, hızlı atışlarla uzun bir kesişen desen. Aylarca pratik bekleyin.","goodFor":"Çalışkan jugglere bir dönüm noktası."},"tennis":{"name":"Tenis","description":"Bir top, \\"tenis topu\\", her zaman desenin ortasından değil, üstünden geçer. Topu tutan el, topu dışarıdan atar ve top, bir tenis raketinin üzerinden geçer gibi üstten atılır.","goodFor":"Zamanlama cascadeda aynı kalırken dış atışlara ilk adım.","alignmentCues":["Tenis topu olarak bir topu görebilmek için.","Diğerlerinin aynı yükseklikte olacak şekilde dışarıdan atın."],"commonMistakes":["Hangi topun üzerinden geçtiğini kaybetmek.","Üstteki topu diğerlerinden daha yüksek atmak."]},"half-shower":{"name":"Yarım Duş","description":"Bir el her topu üstten atarken diğer el her topu alttan atar. İki yay, yüksek dış yoldan ve düşük iç yoldan ayrılır ve toplar bir döngü içinde birbirlerini takip eder.","goodFor":"Ritim eşit kalırken elleri iki rolde ayırma.","alignmentCues":["Üst el dışarıdan ve biraz daha yüksek atar.","Alt el atışlarını sıkı ve içte tutar."],"commonMistakes":["Her iki elin düz cascadede atışlara geri dönmesi.","Yaylar aynı yükseklikteyken ortada çarpışmalar."]},"claw-cascade":{"name":"Kazık Kaskadı","description":"Kaskad, avuç içi aşağıda kaptı. Her el yukarıya doğru uzanır ve havadan topu yakalar, sonra aşağıya çeker ve çevirerek atar. Eller, toplara pençeler gibi çarpmış gibi görünür.","goodFor":"Aktif kavrama yakalamaları ve güçlü bilek dönüşü geliştirir.","alignmentCues":["Topla buluşmak için yukarı uzanın, parmakları açın.","Bir hareketle aşağıya çekin ve bileği çevirin."],"commonMistakes":["Topun elin arkasına çarpması için geç kavramak.","Dönmeyi çok uzun sürmesi nedeniyle düşük atış yapmak."]},"chops":{"name":"Kısa kesim","description":"Her kavramadan sonra el, topu gövde boyunca yüksek bir şekilde taşıyarak aşağıya doğru keser ve karşı taraftan atar. Kollar, keser gibi birbirinin üzerinden geçer ve toplar, altta sıkı bir kaskadın içine düşer.","goodFor":"Kaskad zamanlamasını korurken büyük kollarla taşıma.","alignmentCues":["Yüksek kavrama, geçiş, aşağı kesme ve atış.","Vücudunuzun karşı tarafından atın."],"commonMistakes":["Bir sonraki kavramayı geç kalmak için çok uzakta taşıma.","Ortada kolların çarpışması."]},"penguin-cascade":{"name":" penguen kaskadı","description":"Kollar, avuç içi aşağı olacak şekilde yanlarda düz asılı kalır. Her kavrama düşük ve yana doğru olur ve atışlar kalçadan yukarıya doğru fırlatılır. Bir penguen gibi ritme göre kanat çırpmış gibi görünürsünüz.","goodFor":"Bilek ile yapılan atışlar ve elin normal konumundan uzak kavramalar.","alignmentCues":["Dirsekler düz, eller kalçalarda.","Bilekten fırlatın, avuç içi arkaya bakacak şekilde."],"commonMistakes":["Normal bir kaskad için dirsekleri geriye doğru bükmek.","Bilek gerildiğinden dolayı atışların ileri doğru kayması."]},"under-the-leg":{"name":"Bacak Altı","description":"Her altıncı atışın sağ bacağın altından geçtiği bir kaskad. Top geldiğinde dizini kaldır, uyluğun altına uzan ve dışarıdan yukarıya at, sonra bir sonraki kavramak için ayakını indir.","goodFor":"İlk vücut atışı: bacak kaldırma ve kolların tek bir ritimle uzatılması.","alignmentCues":["Atış sırasında değil, atıştan önce dizini kaldır.","Ekstra uzatmayı kaplamak için biraz daha yükseğe atın."],"commonMistakes":["Diz yerine ileri eğilme.","Bacak aşağı indikten sonra bir sonraki atışı aceleyle yapma."]},"behind-the-back":{"name":"Arka Ters","description":"Her altıncı atışta, sağ el belin arkasından geçer ve topu karşı omzun üzerinden yukarı atar, ardından öndeki desene geri düşer. Diğer atışlar normal bir kaskad olarak kalır.","goodFor":"Göremediğin bir desene kör atış yapmak.","alignmentCues":["Top düştüğünde eli erken arkaya sallama.","Normalden biraz daha yüksek, uzak omzun üzerinden hedefle."],"commonMistakes":["Topun önünüze düşmesi için çok ileri atış yapma.","Bütün gövdeyi bükme."]},"over-the-shoulder":{"name":"Omuz Üstü","description":"Her altıncı atışta, sağ el topu önünden yüksekçe, sol omzun üzerinden yukarı ve arkaya gönderir. Sol el, belinin arkasından geçer ve kör bir şekilde yakalar, ardından bir sonraki topu belinin yanında yukarı fırlatır. Geri kalan her şey düz bir kaskadır.","goodFor":"Görsel yerine hisse göre zamanlanan, sırt arkasından kör bir yakalama.","alignmentCues":["Başınızın arkasında, sol omzunun hemen arkasında, başınızı geçecek kadar yüksek atın.","Yakalama elini erken belin arkasına getirin, avuç içi yukarı dönük."],"commonMistakes":["Topu aramak için kafanı çevirme.","Topun başa veya omuza çarpması için çok alçaktan atış yapma."]},"knee-bounce-cascade":{"name":"Diz Sallama","description":"Her altıncı atışta, sağ el topunu diz yükseldiğinde sağ dizine düşürür. Top dizin üstünden sıçrayarak sol elin üzerine ve yukarıya doğru gider, ardından ayak bir sonraki yakalama için aşağı iner.","goodFor":"Bir bacağın üzerinde dengede kalırken, dizin ritimle desene katılması.","alignmentCues":["Topu karşılamak için dizini kaldır, uyluk seviyesine.","Topu fırlatma, düşür."],"commonMistakes":["Topun ileriye uçması için topa tekme atma.","Diz yerine eğilerek dizin yerine eğilme."]},"head-bounce-cascade":{"name":"Baş Sallama","description":"Her altıncı atış başınızın üzerinden yukarı gider. Topun alnınıza düşmesi için kafanızı geriye doğru eğin, ardından başınızı aşağı ve öne doğru sallayarak sol elinize geçirin. Diğer atışlar altta düz bir kaskad olarak kalır.","goodFor":"Eller cascade'ı devam ettirirken topa doğrudan yukarıdan odaklanarak.","alignmentCues":["Başınızı erken geriye doğru eğin ve gözlerinizi topa tutun.","Yumuşak bir sıçrama için dizleri biraz bükün."],"commonMistakes":["Topa başla vurmak yerine onun düşmesine izin vermek.","Yukarı bakarken cascade'ı kaybetmek."]},"crossed-arm-cascade":{"name":"Kesişik Kollu Kaskad","description":"Sağ el sol tarafta olacak şekilde ön kolları kavuşturun ve kavuşturulmuş halde tutun. Bu pozisyondan cascade jugglesini yapın. Atışlar aynalı gibi hissedilse de desen normal görünüyor.","goodFor":"Her elin nerede olduğunu alışkanlığı kırma.","alignmentCues":["Kavramayı dirseklerde değil, bileklerde tutun.","Atışlar her zamanki gibi göz yüksekliğinde zirveye ulaşır."],"commonMistakes":["Atışlar arasında kavramayı açmak.","El birbirlerini geçerken çarpışmak."]},"burkes-barrage":{"name":"Burke'nin Saldırısı","description":"423'e dayanarak oluşturulmuş. 4 olarak atılan top kavranır ve geçilir, 2 aynı elde kısa bir yükseltmedir ve 3 desene doğrultularak kesilir. Kollar birbirinin üzerinden geçerek yoğun bir hareket oluşturur.","goodFor":"Zaten bildiğiniz bir siteswap üzerinde taşıma ve kavrama kombinasyonu.","alignmentCues":["Önce 423 zamanlamasını öğrenin, sonra taşımayı ekleyin.","2, elden çok az uzaklaşır."],"commonMistakes":["2'yi çok yüksek atarak ritmi bozmak.","3'teki kesmeyi unutmak."]},"rubensteins-revenge":{"name":"Rubenstein'in İntikamı","description":"52233 üzerinden bir dizi taşıma. Yüksek atış, eller kavrama, kesme ve birbirlerini geçerken zaman kazandırır, ardından desen cascade'e geri döner. Yavaş yavaş, bir elde birer öğrenin.","goodFor":"Taşıma, kavrama ve kolların geçişini birlikte eğiten bir gösteri.","alignmentCues":["5, tek yüksek atıştır.","Yüksek top hariç el yoluyla yolu öğrenin."],"commonMistakes":["Taşımalarda panik yaparak erken atmak.","Yüksek atışın ileriye doğru kayması."]},"siteswap-42":{"name":"İki-Bal 42","description":"İki top: her el, bir topu kendine doğru yüksek atar ve diğerini bir ritim için tutar. Yüksek toplar her iki tarafta sütunlar halinde yükselirken, eller sırayla atar. Kendi kendine atışları öğrenmenin sessiz bir yolu.","goodFor":"Dört yükseklikte kendine atışlar, bir elde iki topun temel bileşeni.","alignmentCues":["Atışlar kendi tarafında kalır.","2'yi avuç içinde hâlâ tut."],"commonMistakes":["Atışların ortadan geçmesi.","Tutulan topu yanlışlıkla atmak."]},"snake":{"name":"Yılan","description":"Her biri ardından boş bir ritimle yüksek çapraz beşler halinde atılan üç top. Toplar aynı yüksek yörünge boyunca birbirinin ardından, başınızın üzerinden bir yılan gibi kayar.","goodFor":"Tam beş top ritmi baskısız, tutarlı yüksek atışlar.","alignmentCues":["Tüm beşler aynı yükseklikte.","Boş ritmi eli sıfırlamak için kullan."],"commonMistakes":["Beşlerin ileriye doğru kayması.","Alışılmışlıkla boş ritimde atmak."]},"grace":{"name":"Grace","description":"Yumuşak bir çoklu atış: bir el, iki topu aynı anda atar, normal bir çapraz atış ve diğer elin doğrudan içine küçük bir geçiş. Sonra bir tutulmuş ritim ve cascade'e geri dönüş.","goodFor":"Bir elde iki top atma konusunda yumuşak bir giriş.","alignmentCues":["İki topu birlikte bırak.","Küçük olan azca yükselir."],"commonMistakes":["İki topu farklı zamanlarda bırakmak.","Küçük topu çok yüksek atmak."]},"orinoco-flow":{"name":"Orinoco Akışı","description":"Her seferinde kendine atışlar birbirlerine geçerek iki tur 42 ile başlar, ardından bir cascade atışı ile bitirilir. Sütunlar ve cascade arasında dalgalanır.","goodFor":"Kendine atışlar ile çapraz atışlar arasında akıcı geçiş.","alignmentCues":["Dört'ler tamamen sana yanında yukarı doğru.","3, normal bir kaskad atışıdır."],"commonMistakes":["Dörtlülerin içeriye doğru eğilmesi.","Beş atış döngüsünün sayısını kaybetmek."]},"relfs-rhythm":{"name":"Relf'in Ritmi","description":"Kendine atış ve bir tutma, ardından üç kaskad atışı. Döngü tek olduğu için, kendine atış her turda diğer elde düşer.","goodFor":"Her iki tarafta da devam eden bir kaskadın içine bir numara eklemek.","alignmentCues":["Önce kaskad, sonra 42'yi düşür.","Dörtlüyü kendi tarafında tutun."],"commonMistakes":["Sadece güçlü elde yapmak.","Kaskadın sonrasında hızlanmasi."]},"frostbite":{"name":"Donmuş","description":"İki hızlı dörtlü, hızlı bir geçiş, ardından iki kaskad atışı. Geçiş, dörtlüler havada asılırken alttan geçer.","goodFor":"Bir döngüde hızlı geçişlerle yüksek atışları karıştırmak.","alignmentCues":["1, doğrudan karşıya bir flik'tir.","Dörtlüler dikey kalır."],"commonMistakes":["1'i atmak yerine geçirmek.","İkinci dörtlüyü unutmak."]},"siteswap-52512":{"name":"52512","description":"Bir tutulan ritimle ayrılmış iki yüksek beş, ardından bir beş, hızlı bir geçiş ve bir tutma. Bu desen yüksek çapraz atışlarla kısa düşük atışları karıştırır.","goodFor":"Üç top ile hassas yüksek-düşük kontrol.","alignmentCues":["Beşlerin hepsi aynı yüksekliğe ulaşır.","İkiler elde kalır."],"commonMistakes":["2'leri atmak.","Eşit olmayan beşler."]},"high-low-shower":{"name":"Yüksek-Alçak Duş","description":"Bir dönüşle duş: bir top çok yükseğe giderken diğerleri altından hızlı ve düşük geçer. Ritim bir koşu gibi ses çıkarır.","goodFor":"Üç top düzeninde büyük yükseklik kontrastı ve hızlı eller.","alignmentCues":["Yediler yüksek ve düz gider.","Birler düz geçişlerdir."],"commonMistakes":["Yedilerin ileriye doğru kayması.","Birlerin çok yüksek geçişi."]},"siteswap-612":{"name":"612","description":"Yüksek bir kendine atma, hızlı bir geçiş ve bir tutma. Altı aynı tarafta yanınızda yukarı çıkar, diğer iki top ise altından karşıya geçer.","goodFor":"Yüksek kendine atma ile hızlı düşük geçişlerin karışımı.","alignmentCues":["Altı aynı tarafta kalır.","1'i düz ve hızlı geç."],"commonMistakes":["Altının üzerinden geçmesi.","2'de çok uzun tutulması."]},"three-in-one":{"name":"Üçlü Bir Elde","description":"Üç top, sadece sağ el ile yüksek sütunlarda veya küçük bir şelalede juggled. Her atış yüksek olduğu için yakalamak ve tekrar atmak için zaman vardır.","goodFor":"Bir el kontrolü ve yükseklik tutarlılığı.","alignmentCues":["Atışlar başın çok üzerinde zirveye çıkar.","El küçük bir daire içinde hareket halinde tutulur."],"commonMistakes":["Atışların dışa doğru kayması.","Üçü devam ettirmek için atışlar çok düşük."]},"columns":{"name":"Sütunlar","description":"Üç top dikey sütunlarda yükselir. Her iki el de dıştaki topları birlikte atar, sonra sağ el orta topu tek başına atar. Yukarı, yukarı, yukarı, pistonlar gibi.","goodFor":"İlk aynı anda atışlar ve birçok senkron numaralar için temel.","alignmentCues":["Dış sütunlar birlikte yukarı çıkar.","Orta sütun merkezden düz yukarı çıkar."],"commonMistakes":["Sütunlar eğilerek top birbirine çarpıyor.","İkili eş zamanlılıkta dengesizlik."]},"infinity":{"name":"Sonsuzluk","description":"Tek atışın doğrudan yukarı değil, yanlara geçtiği sütun deseni; ortadaki top her seferinde yan değiştirmektedir. Toplar bir sekiz şeklinde izler.","goodFor":"Yandan eş zamanlı desenleri değiştirmek için.","alignmentCues":["İkili doğrudan yukarı, tek atış yanlara.","Her döngüde yanlar değişir."],"commonMistakes":["Habits nedeniyle tek atışın doğrudan yukarı gitmesi.","İkili kayma."]},"rainbow-cross":{"name":"Renkli Kemer","description":"İki top bir çift arasında kesişerek, sonra ortada doğrudan yukarı atılır. Kesişen yaylar başınızın üzerinde bir gökyüzü oluşturur.","goodFor":"Kesişen eş zamanlı atışları çarpışmadan yapmak için.","alignmentCues":["Bir kesişme atışı diğerinden hafifçe öne doğru.","Orta atış doğrudan yukarı gitmelidir."],"commonMistakes":["Kesişen toplar birbirine çarpıyor.","Orta atış eğilerek."]},"crossunder":{"name":"Çapraz Alt","description":"Her atış kesişir: kesişen çift, ardından her döngüde yan değiştiren tek kesişme atışı. Toplar birbirlerinin üzerinden ve altından dönerler.","goodFor":"Tüm kesişen eş zamanlı kontrol için.","alignmentCues":["Kesişen atışları hafifçe farklı düzlemlerde tutun.","Her yerde eşit yükseklikte kalın."],"commonMistakes":["Ortada çarpışma.","Tek atış yeterince kısa."]},"yo-yo":{"name":"Yo-Yo","description":"Bir el sütun atarken, diğer el bir topu tutar ve birinin altında yukarı aşağı hareket eder; iki top bir iple bağlanmış gibi görünür.","goodFor":"Sütunun karşı tarafında hareket eden bir topu tutan bir illüzyon.","alignmentCues":["Tutulan top, sütun topunu takip eder.","Sütunlar dikey kalır."],"commonMistakes":["Tutulan topun geride kalması.","Sütunların birbirinden uzaklaşması."]},"box":{"name":"Kutu","description":"Toplar bir kare izler. Bir el bir topu düz yukarı atarken diğer el bir topu geçer, sonra roller değişir. Yüksek kenarlar, düz üst ve alt.","goodFor":"Yatay geçişleri eğiten klasik bir senkronizasyon modeli.","alignmentCues":["Geçişler el yüksekliğinde düz bir şekilde geçer.","Dikeyler düz yukarı yükselir."],"commonMistakes":["Geçişlerin çok yüksek bir yörüngeyle yapılması.","Sütunların içeriye doğru eğilmesi."]},"broken-box":{"name":"Kırık Kutu","description":"Her atışta yanlar değişen bir kutu: dikey atış ve çapraz geçiş el değiştirdikçe, kare kendini katlamaya devam eder.","goodFor":"Hızlı senkronizasyon rol değişimi.","alignmentCues":["Her vuruşta dikeyi değiştirin.","Düz ve hızlı geçiş yapın."],"commonMistakes":["Dikeyi aynı tarafta tekrarlamak.","Geçişi acele etmek."]},"als-slide":{"name":"Al'ın Kayması","description":"Bir çapraz yüksek atış, düz geçiş, ardından bir tutma ve başka bir çapraz yüksek atış. Toplar üst ve altta düzgün bir yuvarlanma şekliyle kayar.","goodFor":"Geçişler ve tutmalarla karışık senkronize çapraz atışlar.","alignmentCues":["Çapraz dörtlüler birlikte zirveye ulaşır.","2'yi tutun."],"commonMistakes":["Tutulan topu atmak.","Ortada çarpışma."]},"factory":{"name":"Fabrika","description":"Bir el, topu bel seviyesinde taşıyarak bir kemer gibi hareket ederken, diğer el sütunlar atar. Toplar makine gibi bir döngü içinde döner.","goodFor":"Senkron ritimde taşıma ve atma koordinasyonu.","alignmentCues":["Taşıyan el geniş bir döngü içinde hareket eder.","Dikeyler dik kalır."],"commonMistakes":["Taşıyan el topu sütuna düşürür.","Sütunlar eğilir."]},"broken-shower":{"name":"Kırık Duş","description":"Senkron bir duş: sağ el yüksek atarken sol el aynı anda düşük geçiş yapar. Toplar sık bir döngü içinde döner.","goodFor":"Düş döngüsünün senkron bir versiyonu.","alignmentCues":["Her iki el birlikte bırakır.","Sağ el için yüksek kavis, sol el için düz geçiş."],"commonMistakes":["Birini diğerinden sonra bırakmak.","Geçiş, yüksek topa doğru yukarı doğru kavis yapar."]},"crossed-arm-shower":{"name":"Kapalı Kollu Duş","description":"Kolları kesişik tutarak yapılan duş. Yüksek atışlar vücudun sol tarafından gelir ve hızlı geçişler altından geri gelir.","goodFor":"Bilinmeyen kollu pozisyonda duş kontrolü.","alignmentCues":["Süre boyunca kesişik kalın.","Geçişleri vücuda yakın tutun."],"commonMistakes":["Kavramaları yapmak için kolları açmak.","Geçişler çok yüksek."]},"siteswap-534":{"name":"534","description":"Kesişen beş, bir kaskad üç ve bir kendine dörtten oluşan dört top deseni. Dört top 423 gibi hissettirir ve fountaına güzelce bağlanır.","goodFor":"En popüler dört top numarası ve daha yüksek siteswap'lere giriş yolu.","alignmentCues":["Beş en yüksek, üç en düşük.","Dört yanında kalır."],"commonMistakes":["Yüksekliklerin düzleşmesi.","Üçü acele etmek."]},"siteswap-552":{"name":"552","description":"İki kesişen beş ve bir tutma. Dört top beş top ritmiyle bir nefes almak için bir vuruşla jugglenir.","goodFor":"Zamanla iyileşen beş yüksek atışlar.","alignmentCues":["İki beş de aynı.","İki'yi hâlâ tut."],"commonMistakes":["Tutmayı atmak.","Beşlerin ileri kayması."]},"siteswap-5551":{"name":"5551","description":"Sırayla üç beş ve hızlı bir geçiş. Beş top kaskadına doğru iyi bir adım.","goodFor":"Dört top ile beşlerin sıralarını pratik yapmak.","alignmentCues":["Beşlerin hepsi aynı yükseklikte.","Bir için düz hızlı geçiş."],"commonMistakes":["Beşlerin aşağı doğru ilerlemesi.","Bir'i topa atmak."]},"siteswap-55550":{"name":"55550","description":"Dört beş ve boş el. Bir top eksik olan beş top kaskadı, bu da beş top için harika bir prova yapar.","goodFor":"Beş top kaskadına geçmeden önceki son adım.","alignmentCues":["Boşluğu yerleşmek için kullan.","Beşler tutarlı."],"commonMistakes":["Boşluğa atmak.","Beşlerin kayması."]},"siteswap-633":{"name":"633","description":"Yüksek bir kendine atış, ardından iki kaskad atışı. Altı, kaskadın altında geçerken havada kalır.","goodFor":"Dört top ritmine entegre edilmiş yüksek kendine atışlar.","alignmentCues":["Altı, kendi elinin üzerinde kalır.","Üçler alçak kalır."],"commonMistakes":["Altının kayması.","Üçlerin çok yüksek olması."]},"siteswap-53":{"name":"53","description":"Bir el, diğer elin düşük kaskad üçlerini atarken, yüksek geçiş beşlerini atar. Dört topun yarısı ve yarısı bir duşak. ","goodFor":"İki el arasında yükseklik kontrolü.","alignmentCues":["Sağ el yüksek, sol el alçak.","Eşit ritim."],"commonMistakes":["Yüksekliklerin birleşmesi.","Üçlerin acelesi."]},"wimpy":{"name":"Wimpy Deseni","description":"Her çift aynı anda kesişen dört top. Geniş bir çaprazlamada her vuruşta yarışlar yan yana değişir.","goodFor":"Dört top ile kesişme senkronizasyonu.","alignmentCues":["Bir el, biraz öne atar.","Aynı anda bırakılır."],"commonMistakes":["Ortada çarpışma.","Bırakma zamanının gecikmesi."]},"four-ball-shower":{"name":"Dört-Ball Duşu","description":"Dört top bir daire içinde: bir elden çok yüksek atışlar ve diğer elden düz geçişler.","goodFor":"Dört top ile yüksek atış tutarlılığı.","alignmentCues":["Yediler düz ve yüksek.","Geçişler hızlı ve düz."],"commonMistakes":["Yedilerin ileri doğru kayması.","Geçişlerin yükselişi."]},"tsunami":{"name":"Tsunami","description":"Yüksek bir yedi, bir tutma, bir kendi kendine dört, bir geçiş ve yüksek bir kendi kendine altı. Yükseklik dalgaları desenin içinden geçer.","goodFor":"İleri düzey karışık yükseklikte dört top kontrolü.","alignmentCues":["Atışları sırayla yavaşça öğrenin.","Yedi ve altı ikisi de yüksek."],"commonMistakes":["Yükseklikler tutarsız.","Sayıyı kaybetmek."]},"siteswap-645":{"name":"645","description":"534'ün beş top versiyonu: yüksek bir kendi kendine altı, bir kendi kendine dört ve bir kesişen beş.","goodFor":"Beş top döngüsünden çıkan ilk hareket.","alignmentCues":["Altı en yüksek.","Dört yan tarafında kalır."],"commonMistakes":["Yüksekliklerin düzleştirilmesi.","Kayma."]},"siteswap-744":{"name":"744","description":"Çok yüksek bir kesişen yedi ardından iki kendi kendine dört.","goodFor":"Beş top içinde yüksek atış eklemesi.","alignmentCues":["Yedi düz ve yüksek.","Dörtlüler dikey."],"commonMistakes":["Yedi kayması.","Dörtlülerin kesişmesi."]},"five-ball-shower":{"name":"Beş Toplu Duş","description":"Bir elden devasa dokuzlara ve alttan düz geçişlere kadar beş top döngüde.","goodFor":"En yüksek seviyede yükseklik ve doğruluk.","alignmentCues":["Dokuzlar düz ve tutarlı.","Geçişler düz."],"commonMistakes":["Dokuzlar dolaşıyor.","Geçişler yükseliyor."]},"five-ball-half-shower":{"name":"Beş Top Yarım Duş","description":"Beş top ile eş zamanlı geçiş atışları, bir el diğerinden daha yüksek.","goodFor":"Beş top ile eş zamanlı geçiş kontrolü.","alignmentCues":["Sağ daha yüksek, sol daha düşük.","Birlikte bırakın."],"commonMistakes":["Yükseklikler birleşiyor.","Çarpışmalar."]},"martins-one-count":{"name":"Martin'in Deseni","description":"Bir çoklu atış: yüksek bir altı ve birlikte bırakılan tutulan top, ardından bir tutma ve geçiş beşi.","goodFor":"Beş top ile çoklu atış zamanlaması.","alignmentCues":["Çoklu atış temiz bir şekilde bırakılır.","Beş geçiş."],"commonMistakes":["Çoklu atışın bölünmesi.","Altı kayıyor."]},"six-ball-fountain":{"name":"Altı Top Şelale","description":"Her elde üç top, yan yana yüksek şelaleler halinde juggled.","goodFor":"Altı top sayısının kilometre taşı.","alignmentCues":["Her el kendi şelalesini yürütür.","Atışlar yüksek ve tutarlı."],"commonMistakes":["Şelalelerin birbirine doğru kayması.","Atışlar çok düşük."]},"club-swing":{"name":"Tek Kulüp Döndürme","description":"Bir kubbe tutucuyu sapıyla tutun, sapın ucu elin avuç içine oturacak şekilde. Bel seviyesinden yukarı doğru sallayın, kubbe havada bir kez dönsün ve diğer elinize sap önde gelerek ulaşsın. Aynı şekilde geri atın.","goodFor":"Her kubbe deseninin yapıldığı tek dönüşü öğrenmek.","alignmentCues":["Dirsekten kaldırın, bilek kubbe üzerinde yuvarlanmasına izin verin.","Sapı bel seviyesinde yakalayın."],"commonMistakes":["Bilekleri çarparak kubbenin fazla döndürülmesi.","İleriye atarak sapın çok uzakta düşmesi."]},"club-exchange":{"name":"İki Kulüp Değişimi","description":"Her iki elde bir kubbe. Sağdan tek dönüş atın; zirvede, sol kubbe ile birlikte altından atın. Her ikisini de saplarından yakalayın ve durun, ardından diğer el ile başlayın.","goodFor":"Çarpışmalar olmadan iki dönüşlü kubbe zamanlaması.","alignmentCues":["İkinci kubbe birincinin zirvesine gider.","İkinci kubbe birincinin içine atın."],"commonMistakes":["Kubbelerin ortada birbirine çarpması.","Eller arasındaki dönüşün eşit olmaması."]},"club-cascade":{"name":"Üç Kulüp Kaskadı","description":"Kubbelerle yapılan kaskad, her kubbe havada bir dönüş yapar. Atışlar vücudun içinden gelir ve geçerken, kubbe sapları size doğru tutulur.","goodFor":"Tüm kubbe jugglinden temel desen.","alignmentCues":["Dirsekten atın, bilekleri yumuşak tutun.","Kubbeler göğsünüze paralel kalır."],"commonMistakes":["Kubbelerin eğilmesiyle yanlara doğru dönmesi.","Çok hızlı dönerek vücuda yakalanması."]},"club-doubles":{"name":"Kulüp Çiftleri","description":"Her kubbe havada iki dönüş yapan üç kubbe kaskadı. Atışlar daha yüksek ve daha yavaş olur ve kubbeler büyük daireler halinde bulanık görünür.","goodFor":"Dört kulübe gerekli olan döndürme kontrolü ve yükseklik.","alignmentCues":["Kolundan daha çok kaldır, bilekten değil.","Çift döndürmeyi düzgün ve eşit tut."],"commonMistakes":["Bileği çekiştirip fazla döndürmek.","Çiftleri çok düşük atmak."]},"club-flats":{"name":"Kulüp Düzleri","description":"Kulüplerin hiç dönmeyen bir kaskad. Her kulüp, düz bir bilek ile yukarı itilerek, sap aşağı doğru süzülür ve dik olarak yakalanır.","goodFor":"Bilek kontrolü ve dönen atışlarla kolay bir karşılaştırma.","alignmentCues":["Bileği kilitleyin ve dirsekten itin.","Kulüp tüm yol boyunca dik kalır."],"commonMistakes":["Kazara yarım dönüşler.","Kulübü sallaması için çok yüksek atmak."]},"club-under-leg":{"name":"Kulüp Bacağın Altında","description":"Her altıncı atışta sağ bacağın altından geçen bir kulüp kaskadı. Dizini kaldır, kulübü uyluğun altından sallayarak desene dönmeye bırak.","goodFor":"Kulüplerle yapılan ilk vücut atışı.","alignmentCues":["Dizini erken kaldır.","Bacak atışında biraz daha fazla yükseklik."],"commonMistakes":["Kulübü bacağa vurmak.","Dizini kaldırarak değil, eğilerek atmak."]},"club-behind-back":{"name":"Kulüp Arka Tarafta","description":"Her altıncı atışta belin arkasından sallanarak karşı omuza atılan bir kulüp kaskadı.","goodFor":"Vücut arkasında kör kulüp atışları.","alignmentCues":["Kolunu erken arkaya sallayın.","Uzak omuza doğru hedef al."],"commonMistakes":["Kulübün çok öne düşmesi.","Gövdeyi bükme."]},"club-four-fountain":{"name":"Dört-Kulup-Şelale","description":"Her elde iki kulüp, her el kendi şelalesinde çift atış yapar. Kulüpler asla ortayı geçmez.","goodFor":"Dört kulüp dönüm noktası.","alignmentCues":["Çiftler kendi tarafında.","Eller eşit olarak değişir."],"commonMistakes":["Kulüplerin ortaya doğru kayması.","Eller arasında eşit olmayan dönüş."]},"ring-cascade":{"name":"Üç-Ring-Kaskad","description":"Yönlendirme tekerleği gibi yanlardan görünen, her halka dönüşü sırasında dönmeyen bir kasırga. Böylece kenarlar hava ile temiz bir şekilde kesişir.","goodFor":"Halkaları denemek ve nasıl yüzdüklerini hissetmek için basit bir yol.","alignmentCues":["Halkayı kenarına tutun.","Düz bir bilek ile bırakın."],"commonMistakes":["Bükülmüş bilekten kayma.","Rüzgara yakalanacak şekilde yüzeye atma."]},"ring-pancakes":{"name":"Ring-Pancakes","description":"Her halkanın atışının tepesinde düz bir şekilde dönen ve yakalama için tekrar kenarına dönen bir halka kasırgası, tencerede bir pankek gibi.","goodFor":"Bilek kontrolü ve gösterişli bir halka süslemesi.","alignmentCues":["Bırakma anında hızlı bir bilek dönüşü.","Halkayı tekrar kenarına yakalayın."],"commonMistakes":["Aşırı çevirme.","Yüksek atış yapmadan düşük atış yaparak halkanın dönüş yapamaması."]},"ring-four-fountain":{"name":"Dört-Ring-Şelale","description":"Her elde iki halka, ayrı şelalelerde, kenarları düz yukarı ve aşağı kesilerek juggled.","goodFor":"Hafif, yüzen bir araçla dört nesne.","alignmentCues":["Çemberler kenarları ile kalıcı durumda olmalı.","Her el kendi sütununu yönetir."],"commonMistakes":["Ortada çemberlerin teması.","Atışların ileriye kayması."]},"hoop-juggle-single":{"name":"Tek Halat Atışı","description":"Bir çemberi kenarından tutarak, yanınızda asılı tutun. Diğer eline yumuşak bir yayla atın; bu şekilde çember kenarları ile ilerleyip aynı yükseklikte gelmelidir.","goodFor":"Daha fazla çember eklemeye başlamadan önce tam boy çemberin nasıl uçtuğunu öğrenmek için idealdir.","alignmentCues":["Çemberi göğsünüze kenarları ile tutun.","Omuzdan, bilekten değil atın."],"commonMistakes":["Yüzeyine karşı atarak çemberin uzaklaşmasını engellemek.","Düşük atıp yakalamak."]},"hoop-juggle-exchange":{"name":"İki Halat Değişimi","description":"Her elde bir çember var. Sağdaki çemberi atın; zirve noktasında sol çemberi alttan atın. Çemberler birbirinin önünde geçerken, birbirine yakın kalır.","goodFor":"İki çemberli zamanlama ve çemberlerin çarpışmasını engellemek için idealdir.","alignmentCues":["İkinci çember, ilk çemberin zirvesinde olmalı.","İkinci çemberi hafifçe öne atın."],"commonMistakes":["Çemberlerin birbirine çarpışması.","Her ikisini de çok hızlı atmak."]},"hoop-juggle-cascade":{"name":"Üç Halat Kaskadı","description":"Tam boy çemberlerle yapılan kaskad. Eller geniş kalır, atışlar büyük ve yavaş olur; her çember desen içinde kenarları ile döner.","goodFor":"Çember jügelenin temel deseni.","alignmentCues":["Eller geniş, kol uçları yumuşak olmalı.","Her çember aynı düzlemde olmalı."],"commonMistakes":["Çemberlerin ileriye kayması.","Atışları hızlandırmak."]},"hoop-juggle-reverse":{"name":"Ters Hoop Kaskadı","description":"Dışarıdan yukarıdan atılan halkaların içte yakalanması, büyük ölçekte ters dönen döngü.","goodFor":"Halkalı dış atışlar.","alignmentCues":["Dışarıdan, yukarıdan at.","Ortada yakalayın."],"commonMistakes":["Halkaların çok geniş düşmesi.","Eşit olmayan yaylar."]},"hoop-juggle-shower":{"name":"Hoop Duşu","description":"Üç halka bir daire içinde: bir elden yüksek atışlar ve hızlı el değiştirme altından.","goodFor":"Yükseklik ve halkalarla geçiş kontrolü.","alignmentCues":["Yüksek atışlar düz ve çapraz.","Vücuda yakın geçiş yapın."],"commonMistakes":["Yüksek atışların sapması.","Geçişlerin yükselişi."]},"hoop-juggle-two-in-one":{"name":"Bir Elde İki Hoop","description":"Sadece sağ el tarafından juggled iki halka, yanınızda sütunlar halinde yükselen.","goodFor":"Bir el ile halka kontrolü.","alignmentCues":["Sütunlar dikey kalır.","Zaman kazanmak için yüksek atın."],"commonMistakes":["Halkaların dışa doğru sapması.","Çok düşük."]},"hoop-juggle-423":{"name":"Hoop 423","description":"Üç halka ile 423 siteswap: bir kendi kendine dört, tutulan iki ve kesişen üç.","goodFor":"Halkalı siteswap çeşitliliği.","alignmentCues":["Dört kendi tarafında kalır.","2'yi tut."],"commonMistakes":["2'yi atma.","Dörtün birbirine doğru kayması."]},"hoop-juggle-441":{"name":"Hoop 441","description":"İki tane kendi dördü ve halkalarla hızlı bir el atma. El atma, yüksek çiftin altından kayar.","goodFor":"Yüksek halka atışları arasında hızlı el atma.","alignmentCues":["Dörtlüler dikey.","El atma düz."],"commonMistakes":["El atma havada.","Dörtlülerin kayması."]},"hoop-juggle-four":{"name":"Dört-Hoop Şelalesi","description":"Her elde iki halka, yan yana şelaleler halinde juggled.","goodFor":"Dört halka dönüm noktası.","alignmentCues":["Her taraf ayrı.","Eşit ritim."],"commonMistakes":["Halkaların birlikte kayması.","Atışlar çok düşük."]},"hoop-juggle-under-leg":{"name":"Bacak Altında Hoop","description":"Her altıncı atışta kaldırılmış sağ bacak altından geçirilen bir halka kaskadı.","goodFor":"Büyük bir ekipmanla vücut atışları.","alignmentCues":["Diz yüksekçe kaldır.","Biraz daha yüksek at."],"commonMistakes":["Halka ayakla temas ediyor.","Öne eğilme."]},"hoop-juggle-back-throw":{"name":"Hoop Arka Atış","description":"Her altıncı atışın arkadan ve uzak omuzun üzerinden geçen bir halka kaskadı.","goodFor":"Halkalarla kör atışlar.","alignmentCues":["Erken arkadan sallayın.","Uzak omuzun üzerinden."],"commonMistakes":["Halkanın ön tarafa düşmesi.","Bükülme."]},"hoop-juggle-body-hoop":{"name":"Bel Halkasında Jügleme","description":"Bir halkayı belde döndürürken üç tane daha kaskad içinde juggleyin. Kalçalar kolların altında kendi ritimlerini korur.","goodFor":"Vücut halkası ve juggleye dikkat dağıtmak.","alignmentCues":["Kalçalar vücut halkasını hareket ettirir, kollar bağımsız kalır.","Juggleyi vücut halkasının önünde tutun."],"commonMistakes":["Juggleye odaklanırken vücut halkasının yavaşlaması.","Kolların vücut halkasına düşmesi."]},"pass-one-ball":{"name":"Bir Top Geçirme","description":"Birbirinize yaklaşık iki buçuk metre uzakta durun. Sağ elinizden bir topu hafif bir yay şeklinde sol elinize atın. Onlar onu sağ eline geçirip sol elinize atar ve siz onu tekrar sağ elinize geçirirsiniz.","goodFor":"Herhangi bir juggleye başlamadan önce geçişin yüksekliğini ve mesafesini öğrenmek.","alignmentCues":["Doğrudan karşıya atın, geçmeden.","Zirve, baş heightinin biraz üzerinde, aranızda yarım mesafede.","Topa değil, partnerinize bakın."],"commonMistakes":["Partnerin yüzüne değil, bir yay şeklinde atın.","Onun sağ eline hedef alarak geçişin geçmesi."]},"pass-hand-across":{"name":"İki Top Geçirme","description":"İkinizde iki top. Her ikisi de aynı anda sağdan geçiş yapar. Her sol el, gelen geçişi yakalar ve sağa doğru doğrudan geçirir, bir sonraki geçiş için hazır olur. Kendinize atma yoktur, bu yüzden tüm şey geçişleri birlikte zamanlamaktan ibarettir.","goodFor":"Kaskad eklenmeden önce paylaşılan bir ritimde geçiş yapmak.","alignmentCues":["Birlikte geçin: sağ el sayarken.","Sol el ile yakala, eli düşük ve hızlı bir şekilde geç."],"commonMistakes":["Sizden birinin erken geçmesi, bu da geçişlerin farklı zamanlarda havada kesişmesine neden olur.","Eli geçirmek yerine eli atmak."]},"pass-six-count":{"name":"Altı Sayım","description":"İkiniz de üç top ile cascadeda juggleyin ve her altıncı atışta, her zaman sağ elinizden partnerinizin sol eline geçiş yapın. Geçişler arasında, modeli oturtmak için beş kendi atışınız var.","goodFor":"İlk tam geçiş modeli: geçişler arasında yeterli zaman var.","alignmentCues":["Sesli say: geç, iki, üç, dört, beş, altı.","Geçişle aynı yükseklikte kalın.","Partnerinize bakın, kendi ellerinize değil."],"commonMistakes":["Sayıyı kaybedip yanlış vuruşta geçiş yapmak.","Partnerinizin atlamasına neden olacak kadar kısa geçiyor olabilirsiniz."]},"pass-four-count":{"name":"Dört Sayım","description":"Her dördüncü atışı, diğer her sağ el atışını geçirin. Geçir, kendine, kendine, kendine, sonra tekrar geçir. Bu, standart kulüp geçiş ısınmasıdır ve çoğu varyasyonun temelidir.","goodFor":"Günlük geçiş modeli; çoğu numara buradan başlar.","alignmentCues":["Sağ eller birlikte geçsin.","Üç self, sonra geçiş tekrar döner."],"commonMistakes":["Geçiş için kendini çökmek.","Atış yapmak yerine kolun ön kısmını kullanmadan omuzları döndürmek."]},"pass-three-count":{"name":"Üç Sayım","description":"Her üçüncü atışı geçin, böylece geçişler sırayla farklı el ile yapılır: sağ, sonra sol, sonra sağ. Her sol el atışı, eşinizin sağ eline doğrudan geçer.","goodFor":"Her iki elden geçiş yapmak ve her iki el ile yakalamak.","alignmentCues":["Sol el ile yapılan geçişler sağ el gibi doğrudan geçmelidir.","Her iki elinizle de geçiş yüksekliğini aynı tutun."],"commonMistakes":["Zayıf sol el geçişi, kısa bir şekilde düşer.","Sol geçişi sol eline atmak."]},"pass-two-count":{"name":"İki Sayım","description":"Her sağ el atışı bir geçiş ve her sol el atışı bir kendine atıştır. Geçiş, kendine, geçiş, kendine. Aynı ayak hareketiyle dört sayımın iki katı kadar geçiş.","goodFor":"Hızlı, eşit geçiş ritmi; yedi nesne desenlerine giriş.","alignmentCues":["Sağ el geçiş, sol el kendine.","Sol kendiyi içte, gelen geçişin altında tut."],"commonMistakes":["Kendilerinin giderek daha aşağıya inmesine izin vermek.","Geçişleri vücuda çok yakın yakalamak."]},"pass-left-two-count":{"name":"Sol El ile İki Sayım","description":"İki sayımın aynalanmış hali: her sol el atışı, partnerin sağ eline doğru doğrudan geçiş, ve sağ el kendine atış yapar.","goodFor":"Zayıf geçiş elinizi dengelemek.","alignmentCues":["Sol el doğrudan geçiş, geçiş yapmamak.","Sağ el geçişlerinizle aynı yükseklikte ve itmeyle."],"commonMistakes":["Zayıf elden kısa geçiş yapmak.","Alışkanlıkla sağ el geçişlerine geri dönmek."]},"pass-ultimates":{"name":"Ultimates","description":"Her atış bir geçiş. Sağ el doğrudan sol elinize, sol el de doğrudan sağ elinize geçer; kimse kendine atış yapmaz. Toplar sizin arasında sürekli bir akış oluşturur.","goodFor":"Basınç altında geçiş doğruluğu ve ritim.","alignmentCues":["Her atış geçiş: sağ, sol, sağ, sol.","Kaptırma ve geçişi bir akış halinde birlikte yapın."],"commonMistakes":["Bir topu tutarak akışı kesmek.","Tempo yükseldikçe geçişlerin daha düz hale gelmesi."]},"club-pass-four-count":{"name":"Kulüp Dört Sayım","description":"Kluplarla dört sayım. Her geçiş, sağ elden partnerin sol eline doğru, sapla birlikte gelir. Geçişler arasında üç tek self.","goodFor":"Her klup geçiş oturumunun standart başlangıcı.","alignmentCues":["Sağ kalça yanında doğrudan bir sallanma ile geçiş yapın.","Bir tek dönüş: sap, partnerinizin eline düşmeli."],"commonMistakes":["Fazla dönüş yaparak, geçişin sapla başlaması.","Vücudunuzun üzerinden partnerinizin sağ tarafına geçiş yapmak."]},"club-pass-two-count":{"name":"Kulüp İki Sayım","description":"Her sağ el atışı tek bir geçiş, her sol el atışı ise tek bir kendine atıştır. Topu geçiş yapmanın temel ritmi.","goodFor":"Düzenli top geçiş ritmi.","alignmentCues":["Çift sayılarda geçiş, kendine atış, geçiş, kendine atış.","Sol kendine atışı sıkı ve içte tutun."],"commonMistakes":["Sol kendine atışta dönüşü düşürmek.","Geçişlerin sola ve sağa sapması."]},"club-pass-three-count":{"name":"Kulüp Üç Sayım","description":"Toplar her üçüncü atışta geçiş yapılır, böylece el değişimleri olur. Sol el geçişleri doğrudan partnerinizin sağ tarafına gider.","goodFor":"Zayıf elden top geçişi.","alignmentCues":["Her iki elde aynı sallanma.","Sağ, sonra sol, sonra sağ: sayın."],"commonMistakes":["Sol el geçişinde yeterli dönüş yapmamak.","Sol geçiş için vücut dönmek."]},"club-pass-doubles":{"name":"Kulüp Dörtlü Sayım ile Çiftler","description":"Her geçişin çift dönüş yaptığı dört sayım. Daha yüksek atılır ve bir sayım sonra düşer. Yer açmak için sol el geçişten sonra topu bir sayım boyunca tutar ve atmaz.","goodFor":"Çift geçiş, yedi top geçişine ilk adım.","alignmentCues":["Çift geçiş daha yüksek ve daha yavaş: iki tam dönüş.","Geçiş boyunca sol topu tutun, sonra devam edin."],"commonMistakes":["Çifti tek gibi hızlı atmak, böylece fazla dönüş yapar.","Sol topu atmak yerine tutmak."]},"club-pass-ultimates":{"name":"Kulüp Ultimates","description":"Her atış, tek bir klub geçişi olmalı; sağdan sola ve soldan sağa sırayla geçmeli. Altı klub senin arasında akıyor ve kendinden geçiş yok.","goodFor":"Klub geçişinde tam hızda doğruluk.","alignmentCues":["Bir sallama ile yakalayıp at.","Doğru geçişler: sağdan sola, soldan sağa."],"commonMistakes":["Geçişler ortaya kayarak çarpışıyor.","Bir klub tutup akışı kesiyor."]},"club-pass-seven-doubles":{"name":"Yedi-Kulüp Geçiş Çiftleri","description":"Senin arasında yedi klub var. Sağ elindeki çift geçişi, her ikinci atışta ortaklığın sağ eline geçiriyorsun; onun sol eli bir atış sonra kendi soluna doğru çapraz çift geçiş yapar. Tekler aralıkları dolduruyor.","goodFor":"İlk yedi-klub deseni, çiftler üzerine kurulmuş.","alignmentCues":["Çiftlerin ortaklığın sağ eline çapraz geçmesi gerekir.","Kendi atışından hemen sonra, sol elinde onların çiftini yakalayın."],"commonMistakes":["Çapraz değil doğrultuda geçiş yapmak.","İki turu tamamlamak için çok düşükten geçiş yapmak."]},"staff-wheel-spin":{"name":"İki Elde Çark Döndürme","description":"Her iki elin de göğüs yüksekliğinde, palmlarını aşağıya dönük tutarak sapı ortasında tut. Vücudun yan tarafında tekerlek gibi döndürerek, elden eline geçiş yaparken vücudun yanında tut.","goodFor":"İlk sap dönüşü; kavrama ve bilek dönmeyi geliştirir.","alignmentCues":["Sap vücutla paralel kalmalı, eğilmemeli.","Yumuşak kavrama: parmaklar aracılığıyla kaymasını bırak."],"props":["sap"],"commonMistakes":["Kavramayı sıkı tutarak dönüş durur.","Dönüş düzlemi ileriye eğilir."]},"staff-front-spin":{"name":"Ön Değirmen","description":"Sapını vücudun önünde, duvar düzleminde, merkez etrafında elden eline yumuşak geçiş yaparak propeller gibi döndür.","goodFor":"Duvar düzlemi ve elden eline geçiş ekler.","props":["sap"]},"staff-figure-8":{"name":"Figure-8 Dokuması","description":"Çubuğu sağ tarafınızda tekerlek düzleminde döndürün, ardından sol tarafa geçerek orada döndürün ve önünüzde bir sekiz çizgisi oluşturun.","goodFor":"Vücudun her iki tarafını da bağlar; çubuk akışının omurgası.","alignmentCues":["Uçlar zemine geçtiğinde taraf değiştirin.","Her taraf için gövdeyi biraz döndürün."],"props":["çubuk"]},"staff-pass-through":{"name":"Geçiş","description":"Duvar düzleminde dönerken her yarım turda bırakın: bir el çubuğu bırakır ve diğer el merkezde yakalar, böylece çubuk ellerinizin arasından geçer.","goodFor":"Bırakma ve yakalama zamanlamasını öğretir.","props":["çubuk"]},"staff-one-hand-spin":{"name":"Bir Elde Döndürme","description":"Çubuğu bir elinizle elinizin arkasından geçerek parmaklarınızın arasından geçirerek önünüzde döndürün. Her iki eli de pratik yapın.","goodFor":"Parmak ve bilek gücü; diğer eli numaralar için serbest bırakır.","props":["çubuk"]},"staff-helicopter":{"name":"Üstte Helikopter","description":"Çubuğu başınızın üzerinde kaldırın ve bir elinizle zemin düzleminde helikopter kanatları gibi düz bir şekilde döndürün.","goodFor":"Zemin düzlemini tanıtır.","props":["çubuk"]},"staff-butterfly":{"name":"Kelebek","description":"Önünüzde döndürün, ardından çubuğu omzunuzun arkasına katlayın ve geriye doğru çıkarın, her iki tarafta kanatlar gibi ön ve arka sırayı değiştirerek.","goodFor":"Omuz hareketliliği ve akıcı bir ön-arka geçiş.","props":["çubuk"]},"staff-behind-back-pass":{"name":"Arka Ters Geçiş","description":"Dönen çubuğu dönmeyi tamamladıktan sonra sırtınızın arkasından bir elden diğerine geçirin, ardından ön tarafa getirin.","goodFor":"Vücut sarmaları ve gösteri geçişleri.","props":["sopa"]},"staff-isolation":{"name":"Personel İzolasyonu","description":"Sopanın bir ucunun yakınında tutun ve elinizi sopanın ortasının etrafında döndürün, böylece sopa dönerken orta noktası havada sabit kalıyormuş gibi görünür.","goodFor":"İllüzyon çalışmaları ve hassas el yolları.","props":["sopa"]},"staff-antispin-flower":{"name":"Dört-Petallı Antispin","description":"Sopanın ters yönde üç kat daha hızlı dönmesiyle birlikte elinizi bir yöne doğru döndürün, böylece sopa dört yapraklı bir çiçek çizsin.","goodFor":"VTG'nin imzası olan çiçek; derin zamanlama kontrolü.","props":["sopa"]},"staff-neck-roll":{"name":"Boyun Yolu","description":"Sopayı omuzlarınızın arkasına bırakın ve sopanın boyun üzerinden diğer elinize doğru kaymasına izin verin. Yumuşak bir sopayla yavaş başlayın.","goodFor":"Kontakt sopa: sopa eller olmadan vücut üzerinde hareket eder.","avoidIf":["Boyun ağrısı."],"props":["sopa"]},"staff-reverse-wheel":{"name":"Ters Tekerlek Döner","description":"Ters yönde tekerlek dönüşü: sopanın ön ucu yükselir ve tepeden geriye doğru hareket eder. Her iki el de ortada kalır ve ileri dönüşte olduğu gibi tam olarak onu yuvarlar.","goodFor":"Her sonraki hareketin her iki yönde de çalışması için her iki dönüş yönünü dengeleme.","alignmentCues":["Sizin yanında aynı düz tekerlek, sadece yön değişir.","Parmak kemikleri ile ilerleyin ve geriye doğru yuvarlayın."],"props":["sopa"],"commonMistakes":["Düzlemin vücudunuzun üzerinden kayması.","Dönüşü fark etmeden ileri yöne geri dönmek."]},"staff-reverse-front-spin":{"name":"Ters Ön Döner","description":"Ters yönde geçen iki el ile ön dönüş. Üst uç, solunuza değil sağınıza doğru düşer.","goodFor":"Geçiş veya örgülemeden önce ön dönüşün her iki yönü.","alignmentCues":["Çubuğu göğsünüzün önünde kare şeklinde tutun.","Eller aynı şekilde değişir, sadece tersine."],"props":["çubuk"],"commonMistakes":["Uçların size doğru eğilmesi.","El değişimi sırasında ritmi kaybetmek."]},"staff-one-hand-wheel":{"name":"Bir Elde Çark Çevirme","description":"Çubuğu sadece bir elinizle, tekerlek düzleminde, elin arkasından geçerek ve parmaklarınızdan geçirerek çevirin.","goodFor":"Vücut yanında tek el kontrolü: tekerlek izolasyonlarının ve çift çubuğun temeli.","alignmentCues":["Çubuk kalçanın hemen dışında geçer.","Dirsek kaburgalara yakın kalır."],"props":["çubuk"],"commonMistakes":["Uçun bacağa çarpması.","Bileğin kilitlenmesi."]},"staff-wheel-pass":{"name":"Çark Geçişi","description":"Her yarım turda el değiştiren bir tekerlek dönüşü. Her el, çubuk seviyede olduğunda çubuğu alır, etrafında taşır ve elden ele geçirir.","goodFor":"Vücut yanında düzgün el değişimleri.","alignmentCues":["Seviyede yakalayın.","Serbest el yakınlarda bekler."],"props":["çubuk"],"commonMistakes":["Çubuk seviyede olmadan tutmak.","Her geçişte düzlemin sapması."]},"staff-two-hand-helicopter":{"name":"İki Elde Helikopter","description":"Çubuk, her iki elinizle başınızın üzerinde düz bir şekilde döner, bir el diğerinin üzerinden geçerek bir rotor gibi çalışır.","goodFor":"Zemin düzlemine nazik bir ilk bakış.","alignmentCues":["Kollar yumuşak, çubuk başınızın hemen üzerinde.","Eller yüzün önünde değişir."],"props":["çubuk"],"commonMistakes":["Çubuğun öne doğru eğilmesi.","Omuzların çökmüş olması."]},"staff-overhead-pass":{"name":"Üstten Geçiş","description":"Helikopter, başın üzerinde elden ele geçer, her el çubuğu yarım tur taşır.","goodFor":"Zemin düzleminde el değişimi.","alignmentCues":["Çubuk ileri ve geri işaret ederken geçir.","Kolları yumuşak tut."],"props":["çubuk"],"commonMistakes":["Çubuğun başın arkasına düşmesi.","Erken kavrama."]},"staff-one-hand-reverse":{"name":"Bir El ile Ters Dönüş","description":"Bir el ile ön dönüş, diğer yöne doğru, başparmak tarafıyla ilk önce yuvarlanarak.","goodFor":"İki yönde bir el kontrolü.","alignmentCues":["Aynı düzlem, aynı hız, ters.","Çubuk yuvarlanırken parmaklar gevşer."],"props":["çubuk"],"commonMistakes":["Bilek gerilmesi.","Bir yarısında dönüşin yavaşlaması."]},"staff-reverse-helicopter":{"name":"Ters Helikopter","description":"Başın üzerinde diğer yöne doğru dönen tek el helikopteri.","goodFor":"Her iki yönde de başın üzerinde.","alignmentCues":["Seviye kanatlar.","El alnın üzerinde kalır."],"props":["sopa"],"commonMistakes":["Öne doğru eğilme.","Kolun tamamen doğrultulması."]},"staff-extension":{"name":"Uzatma","description":"Sopayı bir ucundan tutun ve elinizin etrafında büyük bir daire çizsin, eliniz neredeyse hareket etmesin. Uzak ucu sizin önünde büyük bir halka çizsin.","goodFor":"Büyük şekiller ve izolasyonlar için gerekli bilek yuvarlanışı.","alignmentCues":["El, dairenin merkezidir.","Bileği yuvarlayın, kolu sallamayın."],"props":["sopa"],"commonMistakes":["Omuzdan sallanma.","Dairenin oval şekle dönüşmesi."]},"staff-wheel-extension":{"name":"Tekerlek Uzatması","description":"Vücut yanında bir uzantı: sopa, bel yüksekliğindeki elin etrafında büyük bir tekerlek çizer.","goodFor":"Büyük tekerlek-düzlemi daireleri.","alignmentCues":["Daireyi bacağın dışında tutun.","Bilek döner, kol sessiz kalır."],"props":["sopa"],"commonMistakes":["Ayakta kesilme.","Sopadan uzaklaşarak eğilme."]},"staff-floor-extension":{"name":"Yukarı Uzatma","description":"Yukarıda düz bir uzantı: sopa, uzatılmış elin etrafında uzun bir rotor kanadı gibi döner.","goodFor":"Yukarıya uzanma ve dramatik bir zemin-düzlemi şekli.","alignmentCues":["El başın üzerinde.","Kanat düz kalır."],"props":["sopa"],"commonMistakes":["Çubuk arkaya doğru çöküyor.","Kol ileri doğru kayıyor."]},"staff-wheel-isolation":{"name":"Tekerlek İzolasyonu","description":"Vücut yanında izolasyon: çubuğun merkezi sabit kalırken el onun etrafında döner.","goodFor":"İkinci düzlemde izolasyon kontrolü.","alignmentCues":["Merkez için belinizin yanında bir nokta seçin.","El küçük bir daire çizerek hareket eder."],"props":["çubuk"],"commonMistakes":["Merkezin kayması.","Düzlemin eğilmesi."]},"staff-floor-isolation":{"name":"Üstten İzolasyon","description":"Başın üzerindeki bir izolasyon, el dönerken çubuk sabit bir noktada döner.","goodFor":"Baş üzerinde izolasyonlar.","alignmentCues":["Sizin üzerinde sabit bir nokta.","Küçük el dairesi."],"props":["çubuk"],"commonMistakes":["Merkezin kayması.","El dairesinin büyümesi."]},"staff-isolation-pass":{"name":"İzolasyon Geçişi","description":"Her yarım turda el arasında geçirilen bir izolasyon, böylece sabit nokta hareketsiz kalırken eler değişir.","goodFor":"İki el ile izolasyon kontrolü.","alignmentCues":["Dairenin alt kısmında geçirin.","Geçiş sırasında merkezi sabit tutun."],"props":["çubuk"],"commonMistakes":["Geçişte merkezin atlaması.","Eller çarpışıyor."]},"staff-antispin-3":{"name":"Üç-Petallı Antispin","description":"El, bir yönde dönerken, direk diğer yönde döner ve üç petal çiçeği çizer.","goodFor":"İlk antispin çiçeği.","alignmentCues":["El dairesi yavaş ve düzgün olmalı.","Direk bu karşı yönde döner."],"props":["direk"],"commonMistakes":["Petal eşit değil.","El dairesi çöküyor."]},"staff-antispin-5":{"name":"Beş-Petallı Antispin","description":"Beş petalı olan daha ince bir antispin çiçeği, el daha yavaş şekilde dönerek spinle karşı durur.","goodFor":"Dokunulmaz antispin zamanlaması.","alignmentCues":["Petal say.","El yavaş hareket etmelidir."],"props":["direk"],"commonMistakes":["Petal birleşiyor.","El hareketini hızlandırıyor."]},"staff-wheel-antispin":{"name":"Tekerlek Antispin","description":"Kolayca dönen, vücudun yanındaki tekerlek düzlemindeki antispin çiçeği.","goodFor":"İkinci düzlemdeki çiçekler.","alignmentCues":["Düzgün düzlem.","Eşit petallar."],"props":["direk"],"commonMistakes":["Düzlem eğilirken.","Petal ileriye kayıyor."]},"staff-floor-antispin":{"name":"Üstteki Antispin","description":"Başın üzerinde düz bir antispin çiçeği.","goodFor":"Üstteki çiçekler.","alignmentCues":["Seviye düzlemi.","El başın üzerinde."],"props":["sopa"],"commonMistakes":["Yönelim.","Petaller eşit değil."]},"staff-inspin-3":{"name":"Üç-Petallı Inspin","description":"El, dönüşle aynı yönde, ancak daha yavaş döner ve sopa, içe doğru bakan üç petal çizer.","goodFor":"Öğrenmek için en yumuşak çiçek.","alignmentCues":["El ve sopa aynı yönde döner.","El geniş ve yavaş döner."],"props":["sopa"],"commonMistakes":["El, sopaya eşit hızda hızlanıyor.","Petaller dengesiz."]},"staff-inspin-4":{"name":"Dört-Petallı Inspin","description":"Dört içe doğru petalı bir inspin çiçeği.","goodFor":"Daha fazla inspin kontrolü.","alignmentCues":["Dört petal sayın.","Düzenli el."],"props":["sopa"],"commonMistakes":["Petaller birleşiyor.","El kayıyor."]},"staff-wheel-inspin":{"name":"Tekerlek Inspin","description":"Vücut yanında çizilmiş üç petallı bir iç dönüş.","goodFor":"Çark düzlemindeki iç dönüşler.","alignmentCues":["Dik düzlem.","Yavaş el."],"props":["sopa"],"commonMistakes":["Yönelme.","Bacağın kırılması."]},"staff-reverse-figure-8":{"name":"Ters 8","description":"Diğer yöne çevrilen sekiz: sopa her iki tarafta da önde yükselir ve arkada düşer.","goodFor":"Dokuma hareketinin her iki yönü.","alignmentCues":["Vücut önünde çapraz.","Her taraf dikey."],"props":["sopa"],"commonMistakes":["Çaprazda düzlemin çökmesi.","Gövde sert."]},"staff-front-weave":{"name":"Ön Dokuma","description":"Her dönüşte vücuttan bir yandan diğerine kayan bir ön dönüş, göğüs onunla birlikte döner.","goodFor":"Dönenin vücut üzerinde hareket ettirilmesi.","alignmentCues":["Göğüs sopa takip eder.","Dönerken kare kalır."],"props":["sopa"],"commonMistakes":["Ayakların çok dönmesi.","Çaprazda düzlemin eğilmesi."]},"staff-overhead-weave":{"name":"Üst Dokuma","description":"Her dönüşte başın bir tarafından diğerine sallanan iki el ile helikopter.","goodFor":"Zemin düzleminde örmek.","alignmentCues":["Tüm süreç boyunca bıçakları düz tut.","Gövde, çubukla birlikte döner."],"props":["çubuk"],"commonMistakes":["Bir tarafta çökme.","Baş yolunun önünde."]},"staff-fountain":{"name":"Şelale","description":"Tekerlek düzlemindeki bir iki zamanlı örmek: uçlar, bir şelale gibi dönüşlerde alternatif taraflara doğru yukarı ve üzerinden sıçrar.","goodFor":"Vücut yanında iki zamanlı.","alignmentCues":["Uçlar, alternatif taraflarda yukarı çıkar.","Kesişmeyi hızlı tut."],"props":["çubuk"],"commonMistakes":["Bir düzlemde 8 şekline çökme.","Düzlemin eğilmesi."]},"staff-reel":{"name":"Reel","description":"Her kesişimde el değiştirilen bir 8 şekli; çubuk bir taraftan diğer tarafa doğru dolanır.","goodFor":"Örmeleri ve geçişleri birleştirmek.","alignmentCues":["Kesişimde geçiş yap.","Her taraf dik."],"props":["çubuk"],"commonMistakes":["Erken tutma.","Gövde sert."]},"staff-wall-wheel-hybrid":{"name":"Duvar-Tekerlek Hibriti","description":"Her dönüşte dönüş, ön düzlem ile yanında tekerlek düzlemi arasında değişir; çubuk dik olduğunda geçiş yapılır.","goodFor":"Durmadan düzlemleri değiştirme.","alignmentCues":["Çubuk dik yukarıyı gösterdiğinde değiştir.","Bilek dördüncü bir tur."],"props":["çubuk"],"commonMistakes":["Seviyede değiştirme.","Değişimde hız kaybı."]},"staff-floor-wall-hybrid":{"name":"Duvar-Zemin Hibriti","description":"Dönen hareket, çubuk seviyede olduğunda her seferinde önünüzde ve üstünüzde değişir.","goodFor":"Ön dönmeleri ve helikopterleri birleştirmek için.","alignmentCues":["Seviyede değiştir.","Kolü düzgün bir şekilde kaldır."],"props":["çubuk"],"commonMistakes":["Dikeyde değiştirme.","Dirsek kilitlenmesi."]},"staff-floor-wheel-hybrid":{"name":"Zemin-Tekerlek Hibriti","description":"Her dönüşte bir yandan bir tekerleğe düşen ve tekrar yukarı çıkan bir helikopter.","goodFor":"Tam uçak değişiklikleri seti.","alignmentCues":["Kol düzgün bir şekilde yükselir ve düşer.","Uçaklar temiz."],"props":["çubuk"],"commonMistakes":["Karmakarışık orta uçak.","Hızın düşmesi."]},"staff-under-leg-pass":{"name":"Bacak Altından Geçiş","description":"Her iki geçişte bir kez kaldırılmış sağ bacağın altına dalmak.","goodFor":"Geçiş hareketlerine bacak eklemek.","alignmentCues":["Çubuğa doğru diz yüksekçe kaldır.","Uyluklarda bükülerek uzun bir sırtla duran dizin içine oturun.","Çubuk bacaktan geçtiğinde geriye doğru kalkın."],"props":["çubuk"],"commonMistakes":["Bel bükülerek aşağıya ulaşmak yerine uyluklarda bükülerek.","Dizin düşük kalmasıyla çubuğun altından geçmesi gerekiyor.","Bacağın altından geçişi aceleyle yapmak."]},"staff-reverse-behind-back":{"name":"Arka Ters Geçiş","description":"Gövdenin diğer tarafında geçen, dönüşün ters yönde olduğu arka geçiş.","goodFor":"Çubuğun her iki yönde de gövde etrafında dolaşması.","alignmentCues":["Arka taraftaki el alçakta bekler.","Dönmeye arka tarafta devam edin."],"props":["çubuk"],"commonMistakes":["Arka taraftaki düzlemi kaybetmek.","Dönmeyi durdurmak."]},"staff-fishtail":{"name":"Balık Kuyruğu","description":"Çubuk, bir balığın kuyruğunu salladığı gibi açık elin üzerinde geriye doğru sallanır, asla tam olarak dönmeyerek.","goodFor":"Açık el kontrolü ve dönüş yönünün değiştirilmesi.","alignmentCues":["Baş parmağı ve parmaklar arasında döner.","Küçük bilek sallamaları sallanışı tersine çevirir."],"props":["çubuk"],"commonMistakes":["Çok sıkı tutmak.","Sallanmaların çok büyük olması."]},"staff-wheel-fishtail":{"name":"Tekerlek Balık Kuyruğu","description":"Çubuğun tekerlek düzleminde gövdenin yanında bir balık kuyruğu.","goodFor":"İkinci düzlemde balık kuyruğu.","alignmentCues":["Dik düzlem.","Açık el."],"props":["çubuk"],"commonMistakes":["Yan yatırma.","Sıkma."]},"staff-steering-wheel":{"name":"Direksiyon","description":"Büyük bir direksiyon gibi, elinizi düz, açık avuçlarla önünüzde çevirin.","goodFor":"Rahat el ve açık avuç teması.","alignmentCues":["Avuçlar düz, parmaklar gevşek.","Üstte el üstüne."],"props":["çubuk"],"commonMistakes":["Kavramak yerine yönlendirmek.","Kolların yayılması."]},"staff-palm-spin":{"name":"Palm Spin","description":"Çubuğun ortasını düz, yukarı doğru elinizi dengede tutun ve bir pervane gibi orada döndürün.","goodFor":"Denge ve hafif bir dokunuş.","alignmentCues":["Avuç düz ve seviye.","Küçük daireler onu döndürür."],"props":["çubuk"],"commonMistakes":["Avuç eğilmesi.","Itmak yerine hafifçe itmek."]},"staff-hand-roll":{"name":"Hand Roll","description":"Çubuk, kavranmadan, açık elin arkasından ve baş parmağın etrafından yuvarlanır.","goodFor":"İlk gerçek temas yuvarlanma.","alignmentCues":["El açık ve yumuşak.","Çubuğun işi yapmasına izin ver."],"props":["çubuk"],"commonMistakes":["Parmakları kapatmak.","Elin çok fazla hareket etmesi."]},"staff-forearm-roll":{"name":"Kürek Kemiği Yaması","description":"Dönmeyi dirseğe bırak, çubuğu döndür, sonra tekrar elde dönmeye al.","goodFor":"Dönmeyi koldan kola ve geriye taşıma.","alignmentCues":["Dirsek düz ve sabit.","Elin düşerken aç."],"props":["çubuk"],"commonMistakes":["Dirseğin eğilmesi.","Çabuk tutmak."]},"staff-elbow-roll":{"name":"Dirsek Yaması","description":"Dönme, bükülmüş dirseğin kavşağına geçer, el kaldırılmış halde orada döner ve elde geri döner.","goodFor":"İleri düzey temas kontrolü.","alignmentCues":["Dirsek dik.","Dirsek sabit."],"props":["çubuk"],"commonMistakes":["Dirseğin düşmesi.","Çubuğun kayması."]},"staff-shoulder-roll":{"name":"Omuz Yaması","description":"Bir tekerlek dönüşü omuzun üstüne kaldırılır, başın yanında döner ve sonra tekrar elde düşer.","goodFor":"Vücutta yüksek temas dönüşleri.","alignmentCues":["Omuz hafifçe kaldırılır.","Baş uzaklaşır."],"props":["kaydırma çubuğu"],"commonMistakes":["Başın yolu engelliyor.","Omuz düşüyor."]},"staff-chest-roll":{"name":"Göğüs Yolu","description":"Çubuk, bir elden diğerine doğru göğüs üzerinden düz bir şekilde kayar ve tekrar geri döner.","goodFor":"Göğün önünde temaslı hareketler için.","alignmentCues":["Göğü yukarı kaldırın.","Çubuk düz kalır."],"props":["kaydırma çubuğu"],"commonMistakes":["Göğ çöküyor.","Çubuk eğiliyor."]},"staff-angel-roll":{"name":"Melek Yolu","description":"Kollar genişçe açılır ve çubuk omuzların arkasından, her iki kol boyunca bir elden diğerine kayar.","goodFor":"Gösterişli temaslı kaydırma için.","alignmentCues":["Kollar düz, palmlar yukarı.","Omuz kemiği sıkıştırılır."],"props":["kaydırma çubuğu"],"commonMistakes":["Kollar düşüyor.","Baş öne doğru."]},"staff-toss":{"name":"Çubuk Atışı","description":"Seviyede tek elde bir dönüş bırakın, hava içinde bir kez dönsün ve aynı dönüşle yakalayın.","goodFor":"Dönen çubuğu bırakıp yakalamak için.","alignmentCues":["Seviyede bırakın.","Ortada yakalayın."],"props":["kaydırma çubuğu"],"commonMistakes":["İleriye fırlatma.","Bir uçtan yakalama."]},"staff-double-toss":{"name":"İki Katlı Atma","description":"Kavrama öncesinde iki tam dönüşle daha yüksek bir fırlatma.","goodFor":"Havada yükseklik ve dönüş kontrolü.","alignmentCues":["Daha fazla kaldırma, aynı dönüş.","Ortaya odaklan."],"props":["staff"],"commonMistakes":["Aşırı dönüş.","İleriye kayma."]},"staff-flat-toss":{"name":"Düz Atma","description":"Bir helikopteri düz bir şekilde yukarı fırlatın, havada düz döndürün, ardından başın üzerinde yakalayın.","goodFor":"Zemin düzleminde fırlatma.","alignmentCues":["Seviye serbest bırakma.","Başın üzerinde yakalama."],"props":["staff"],"commonMistakes":["Serbest bırakılırken eğilme.","Arkaya fırlatma."]},"double-staff-same-time":{"name":"İki Çubuk Aynı Anda","description":"Her iki elde birer kısa staff, her ikisi de aynı yönde ve adım adım önünde dönüyor.","goodFor":"İlk çift staff deseni.","alignmentCues":["Staff'lar yan yana, biri biraz önde.","Her iki el de aynı hızda."],"props":["iki kısa staff"],"commonMistakes":["Staff'ların çarpışması.","Bir el geride kalıyor."]},"double-staff-split-time":{"name":"İki Çubuk Bölme Zamanı","description":"Her iki çubuk da aynı yönde döner, ancak biri dörtte bir tur geride, bu yüzden biri yatayken diğeri dik durur.","goodFor":"Eller arasındaki bağımsız zamanlama.","alignmentCues":["Biri dik, biri yatay.","Düzenli bir sapma."],"props":["iki kısa çubuk"],"commonMistakes":["Aynı zamana geri düşmek.","Çarpışma."]},"double-staff-wheels":{"name":"İki Çubuk Çarkları","description":"Vücudun her iki tarafında birer tekerleme, her ikisi de birlikte ileri dönüyor.","goodFor":"Vücudun yanında iki çubuk.","alignmentCues":["Her tekerleme kalçanın dışında.","Aynı hız."],"props":["iki kısa çubuk"],"commonMistakes":["Tekerleklerin içe doğru eğilmesi.","Ellerin birbirinden uzaklaşması."]},"double-staff-split-wheels":{"name":"İki Çubuk Bölme Çarkları","description":"Her iki tarafta tekerlekler, dörtte bir tur arayla, yürüyen bacaklar gibi.","goodFor":"Vücudun yanında ayrı zamanlama.","alignmentCues":["Biri yukarı, biri yatay.","Düzenli bir sapma."],"props":["iki kısa çubuk"],"commonMistakes":["Senkronize olmak.","Eğilme."]},"double-staff-windmill":{"name":"İki Çubuk Rüzgar Mühlesi","description":"Her iki tarafta da karşıt yönlere dönen tekerlekler, yanlardan görünen bir yel değirmeni gibi.","goodFor":"İki elde karşıt yönler.","alignmentCues":["Biri ileri, biri geri.","Eşit hız."],"props":["iki kısa sopa"],"commonMistakes":["İkisi de aynı yöne doğru kayma.","Hızın eşit olmaması."]},"double-staff-reverse":{"name":"İki Çubuk Ters","description":"İki sopanın da ters yönde dönmesiyle iki zamanlı ön dönüşler.","goodFor":"İki sopayla her iki yön.","alignmentCues":["Saplamayı tut.","İkisi de aynı düzlemde."],"props":["iki kısa sopa"],"commonMistakes":["Çarpışma.","Saplamayı kaybetme."]},"double-staff-helicopters":{"name":"İki Çubuk Helikopterler","description":"Her iki omzun üzerinde bir helikopter, ikisi de adım adım dönen.","goodFor":"Yukarıda iki sopalı.","alignmentCues":["Düz kanatlar.","Kollar yumuşak."],"props":["iki kısa sopa"],"commonMistakes":["Kanatların birbirine temas etmesi.","Kolların yorulması ve düşmesi."]},"double-staff-isolations":{"name":"İki Çubuk İzolasyonlar","description":"Her elde aynı anda bir izoleasyon, her iki merkez yan yana sabit tutulur.","goodFor":"Aynı anda iki izoleasyon.","alignmentCues":["İkinci sabit nokta.","Eller birlikte döner."],"props":["iki kısa direk"],"commonMistakes":["Merkezler kayıyor.","Bir el geri kalıyor."]},"hoop-waist":{"name":"Bel Hooping","description":"Bir ayak diğerinden hafifçe öne doğru durun. Hoop'u alt sırtınıza tutarak, onu belinize atıp her seferinde hoop'un önünden geçtiğinde karınınızı ileri ve geri sallayın (dairesel hareket değil).","goodFor":"İlk hoop becerisi; kas ritmini geliştirir.","modifications":["Daha büyük, daha ağır bir hoop kullanın: daha yavaş döner."],"alignmentCues":["Ön-arka sallanma yapın, dairesel hareketle değil.","Hoop'un karınızı geçerken onu itin."],"props":["hoop"],"commonMistakes":["Hula dansçı gibi beli döndürmek.","Daha küçük veya hafif bir hoop."]},"hoop-hand-spin":{"name":"El Döndürme","description":"Elinizin içine, parmak yukarı olacak şekilde hoop'u önünüzde tutun. Parmakların ağzında dönen hoop'u düz tutarak itin.","goodFor":"Cismi dışındaki hoop temeli.","props":["hoop"]},"hoop-chest":{"name":"Göğüs Hooping","description":"Kollarınızı başınızın üzerinde kaldırıp göğüs etrafında hoop'u döndürün, omuzlarınızı sessiz tutarak kaburga kafesini ön-arka sallayın.","goodFor":"Kaburga kafesini izole eder ve üst vücut kontrolünü geliştirir.","props":["hoop"]},"hoop-lasso":{"name":"Lasso","description":"Hoop'u başınızın üzerinde tutun ve bir lasso gibi başınızın üzerinde düz bir daire çizerek, hoop'u elinizin etrafında döndürün.","goodFor":"Başın üzerindeki zemin düzlemi kontrolü.","props":["hoop"]},"hoop-wedgie":{"name":"Wedgie","description":"Hoop'u duvar düzleminde döndürün ve baş parmağınızla parmaklarınız arasındaki kavşakta yakalayın, ardından orada yuvarlanıp sallanmasına izin verin ve tekrar döndürün.","goodFor":"Kavrama kontrolü ve düzgün geçiş tutuşu.","props":["hoop"]},"hoop-knees":{"name":"Diz Hooping","description":"Ayaklarınızı birbirine yakın tutarak, dizleri ileri-geri sallayarak hoop'u dizlerinizin etrafında döndürmeye devam edin.","goodFor":"Alt vücut hoop'lama ve asansör uygulaması.","props":["hoop"]},"hoop-pass":{"name":"Elde Elde Geçiş","description":"Hoop'u önünüzde döndürün ve her devirde onu bir elden diğerine geçirin, düzlemi sabit tutarak.","goodFor":"Her iki tarafta dış vücut hareketleri.","props":["hoop"]},"hoop-isolation":{"name":"Hoop İzolasyonu","description":"Hoop'un merkezinin hava içinde sizin önünde sabit kalması için elinizi hoop'un etrafında hareket ettirin ve hoop bu noktanın etrafında dönsün.","goodFor":"Klasik hoop illüzyonu.","props":["hoop"]},"hoop-escalator":{"name":"Escalator","description":"Hoop'u döndürmeyi sürdürürken, belden dizlere ve ardından göğse kadar birer vücut bölgesi için yürüyerek aşağı ve yukarı doğru hareket ettirin.","goodFor":"Her vücut-hooplama bölgesini tek bir akışa birleştirir.","props":["hoop"]},"hoop-neck":{"name":"Boyun Hooping","description":"Başınızı hafifçe eğin ve hafif bir hoop'u boyun etrafında döndürün, baş ve omuzların küçük sallanmalarıyla yönlendirin.","goodFor":"Küçük, hassas darbeleri eğiten bir gösteri hareketi.","avoidIf":["Boyun ağrısı."],"props":["halat"]},"hoop-reverse-waist":{"name":"Ters Bel Hooping","description":"Bel halatını ters yönde çevirin. Ön ayaklarınızı değiştirin, halatı yeni yöne atın ve aynı ileri-geri darbeyle devam edin.","goodFor":"Her iki yönde denge kurarak daha sonra herhangi bir numarayı her iki yönde de yapabilme.","alignmentCues":["Ön ayaklarınızı değiştirin.","Aynı darbe, yeni yön."],"props":["halat"],"commonMistakes":["Belinizi çevirin.","Zayıf tarafa çok erken vazgeçmek."]},"hoop-hips":{"name":"Bel Hooping","description":"Halatı belden kalça kemiklerine kadar indirin ve pelvis'ten küçük, düşük bir darbe ile orada tutun.","goodFor":"Bel altı kontrolü ve dizlere doğru bir adım.","alignmentCues":["Dizler yumuşak.","Darbe karın değil, pelvis'ten gelmeli."],"props":["halat"],"commonMistakes":["Aşağıya kaymasına izin vermek.","Darbe çok büyük."]},"hoop-thighs":{"name":"Uyluk Hooping","description":"Ayaklar birbirine yakın olacak şekilde, hızlı, küçük diz zıplamalarıyla halatı üst bacaklarda döndürün.","goodFor":"Bacak ritmi ve kalça ile dizler arasındaki bağlantı.","alignmentCues":["Ayaklar birbirine yakın.","Hızlı küçük zıplamalar."],"props":["halat"],"commonMistakes":["Ayaklar birbirinden uzak.","Çok yavaş sıçramak."]},"hoop-reverse-chest":{"name":"Ters Göğüs Halkası","description":"Kollar yukarıda ve kaburgaların topu yönlendirerek göğüs yönünde topu çevirme.","goodFor":"Her iki yönde de yüksek vücutta.","alignmentCues":["Kollar yukarı ve yoldan uzak.","Kaburga kafesi öne-arka sallanır."],"props":["top"],"commonMistakes":["Kolların topa düşmesi.","Belin iş yapması."]},"hoop-shoulder":{"name":"Omuz Halkası","description":"Kollar yukarıda ve top, omuzlar ve üst göğüs etrafında döner.","goodFor":"Üst vücut topu çevirme.","alignmentCues":["Kollar dik yukarı.","Küçük omuz darbeleri."],"props":["top"],"commonMistakes":["Kolların içeri bükülmesi.","Topun göğüse kayması."]},"hoop-arm":{"name":"Kol Halkası","description":"Bir kolu dik yukarı kaldırın ve topu ön kolda döndürün, topu devam ettirmek için el küçük bir daire çizin.","goodFor":"Uzuv topu çevirme ve kolu yukarı kaldırma lasso hissi.","alignmentCues":["Kol dik, el başın üzerinde.","Küçük el dairesi."],"props":["top"],"commonMistakes":["Bütün kolu döndürmek.","Kolun ileri kayması."]},"hoop-elbow":{"name":"Kol Hooping","description":"Kol yan tarafa uzatılır, dirsek bükülür ve halka dirsek ekleminde döner.","goodFor":"Vücut dışındaki eklem kontrolü.","alignmentCues":["Üst kol seviyesi.","Küçük dirsek daireleri."],"props":["halka"],"commonMistakes":["Dirsek düşmesi.","Halkanın omuza kayması."]},"hoop-foot":{"name":"Bacak Hooping","description":"Bir bacağın kaldırılması ve halkanın baldırın etrafında döndürülmesi, dönmeyi sürdürmek için ayak küçük daireler çizerek.","goodFor":"Denge ve bacak kontrolü.","alignmentCues":["Ayakta kalan bacak güçlü.","Küçük ayak daireleri."],"props":["halka"],"commonMistakes":["Dengesini kaybetmek.","Daireler çok büyük."]},"hoop-full-escalator":{"name":"Tam Bant","description":"Halkayı duraklamadan dizlerden omuzlara kadar ve geriye doğru süresiz olarak sür.","goodFor":"Bir hareketle tam vücut aralığı.","alignmentCues":["Yukarı çıktıkça nabzı hızlandır.","Halka yükseldikçe kollar yukarı çıkar."],"props":["halka"],"commonMistakes":["Bel-göğüs geçişinde kaybolmak.","Kollar yoluna giriyor."]},"hoop-vortex":{"name":"Vortex","description":"Halkayı başının üzerinden bir lasso olarak tutun, omuz ve göğüs etrafına düşürün ve bir spirallenme ile belde yakalayın.","goodFor":"Vücut dışı ve vücut üzerinde halka atma.","alignmentCues":["Halkayı bırakırken lasso hızını koruyun.","Düşmeden önce pulsasyon başlayın."],"props":["halka"],"commonMistakes":["Çok yavaş bırakmak.","Halkanın düşerken eğilmesi."]},"hoop-duck-out":{"name":"Duck Out","description":"Halkayı belden geçerek göğüsten yukarı doğru yürütün, başının üzerinden bir lasso olarak tutun, ardından elde bir dönüşle önüne getirin.","goodFor":"Vücuttan temiz bir şekilde ayrılma.","alignmentCues":["Kaburgalarla kaldırın.","Tepede ritimle tutun."],"props":["halka"],"commonMistakes":["Çok erken tutmak.","Hızı kaybetmek."]},"hoop-drop-in":{"name":"Drop In","description":"Başının üzerinden bir lasso halinde tuttuğunuz halkayı bırakın ve göğüste yakalayın, ardından beline düşürün.","goodFor":"Vücut dışıdan vücuta geri dönüşün en basit yolu.","alignmentCues":["Düşerken kolları yukarı kaldırın.","Pulslayarak yakalayın."],"props":["halka"],"commonMistakes":["Çok hızlı düşürmek.","Kolları sıkıca kapatmak."]},"hoop-chest-lift":{"name":"Chest Lift","description":"Halkayı belden göğüse ve geriye daha güçlü bir atışla kaldırın.","goodFor":"Vücut bölgeleri arasında hareket etmek.","alignmentCues":["Yukarı çıkmak için daha hızlı atış.","Kolları erken yukarı."],"props":["halka"],"commonMistakes":["Değişimde kaybetmek.","Kolların düşmesi."]},"hoop-knee-drop":{"name":"Knee Drop","description":"Halkayı belden dizlere doğru indirin, orada tutun, sonra beline geri atlayın.","goodFor":"Alt vücut geçişleri.","alignmentCues":["Dizler için ayaklar birbirine yakın.","Yukarı çıkmak için daha büyük bir atış."],"props":["halka"],"commonMistakes":["Ayaklar birbirinden uzak.","Yukarı çıkmada kaybetmek."]},"hoop-side-spin":{"name":"Side Spin","description":"Vites düzleminde, vücudun yanında bir el dönüşü, halka sizin yanında bir tekerlek gibi dönüyor.","goodFor":"Halkalar için vites düzlemi.","alignmentCues":["Halka sizin yanında düz.","El bel yüksekliğinde."],"props":["halka"],"commonMistakes":["Halkanın bacağa çarpması.","Düzlemin eğilmesi."]},"hoop-reverse-hand-spin":{"name":"Ters El Döndürme","description":"Önünüzde diğer yöne dönen el dönüşü.","goodFor":"Her iki yön de vücuttan uzakta.","alignmentCues":["Aynı düzlem, diğer yön.","Baş parmak yukarıda kalsın."],"props":["halat"],"commonMistakes":["Sallanma.","Yavaşlama."]},"hoop-reverse-lasso":{"name":"Ters Lasso","description":"Diğer yöne dönen üstten lasso.","goodFor":"Her iki lasso yönü.","alignmentCues":["Seviye halat.","Küçük el dairesi."],"props":["halat"],"commonMistakes":["Yönelme.","Büyük kollar dairesi."]},"hoop-palm-spin":{"name":"Üstten Palm Spin","description":"Açık avuçta yukarı kaldırılan bir el döneri, halat yüzüne dönük olarak üzerinizde döner.","goodFor":"Yükseklikte vücut dışı dönerler için.","alignmentCues":["Kol uzun.","Avuç açık."],"props":["halat"],"commonMistakes":["Halat arkaya kayma.","Kol bükülmesi."]},"hoop-coin-flip":{"name":"Coin Flip","description":"Halatı parmak uçlarında dik tutun ve fırlatılmış bir madeni para gibi dik orta eksende döndürün.","goodFor":"İnce parmak kontrolü ve yeni bir eksen.","alignmentCues":["Daire dikey.","Vuruş yap, sonra dönmeye bırak."],"props":["hoop"],"commonMistakes":["Daire eğilmesi.","Kavrama."]},"hoop-cateye":{"name":"Kedi Gözü","description":"Daireyi çemberin yanından tut ve dikey ortasında sallayarak, önünden kedi gözü gibi daralıp genişleyecek şekilde tut.","goodFor":"Sallama hareketleri ve etkileyici bir illüzyon.","alignmentCues":["El hâlâ çemberde.","Eşit sallayın."],"props":["hoop"],"commonMistakes":["El hareketi.","Eşitsiz sallama."]},"hoop-weave":{"name":"Kumaş","description":"Bir el döndürmesi, bedenin bir tarafından diğerine kayarak, göğüsle birlikte dönme düzlemiyle hareket eder.","goodFor":"Döndürülen hareketi beden üzerinden taşımak.","alignmentCues":["Göğüs bu harekete eşlik eder.","Devam ettirin."],"props":["hoop"],"commonMistakes":["Ortada durma.","Eğilme."]},"hoop-halo":{"name":"Halo","description":"Daire başın etrafında düz bir şekilde döner, kaldırılmış el çemberin üzerinde yukarıda dolaşır.","goodFor":"Baş seviyesindeki dönmeler.","alignmentCues":["Daire başın etrafında düz.","El başa yakın."],"props":["halat"],"commonMistakes":["Halatın öne düşmesi.","Baş eğme."]},"hoop-toss":{"name":"Hoop Toss","description":"Bir el döndürmesi düz yukarı atın, hâlâ dönerken, onu tekrar dönmeye yakalayın.","goodFor":"Dönen bir halatı bırakma ve yakalama.","alignmentCues":["Düz yukarı atın.","Attığınız yerde yakalayın."],"props":["halat"],"commonMistakes":["İleri atma.","Kenarı geç yakalama."]},"hoop-boomerang":{"name":"Boomerang","description":"Hala geriye doğru dönerek halatı aşağı ve uzaklara atın, böylece zemine yuvarlanarak size geri gelir.","goodFor":"Geriye doğru dönüş ve eğlenceli bir zemin numarası.","alignmentCues":["Bileği geriye doğru çekiş.","Düşük ve ileri atın."],"props":["halat"],"commonMistakes":["Yeterli geriye doğru dönüş yok.","Çok yüksek atma."]},"hoop-jump-through":{"name":"Atla Geç","description":"Hala iki elinizle bir atlayış ipi gibi tutun: başınızın üzerinden sallayın ve geçerken ayaklarınızın altından atlayın.","goodFor":"Ritim, koordinasyon ve bir nefes kesen kardiyofitlik.","alignmentCues":["Küçük bir atlamayla, yumuşak dizlerle.","Bileklerden sallayın."],"props":["halat"],"commonMistakes":["Çok erken atlamak.","Büyük kolların sallanması."]},"hoop-behind-back-pass":{"name":"Arka Ters Geçiş","description":"Bir elden diğerine, ardından ön tarafa geçerek sırtın arkasından yapılan bir el dönüşü.","goodFor":"Vücudun tamamında geçiş yapmak.","alignmentCues":["Sırtın arkasında dönmeye devam et.","Bekleyen el geriye uzanır."],"props":["halat"],"commonMistakes":["Halatın sırtın arkasında durması.","Halatın sırtı vurması."]},"hoop-under-leg-pass":{"name":"Bacak Altından Geçiş","description":"Yüksek duran sağ bacağın altından geçen elden ele geçiş.","goodFor":"Geçişlerde bacakları eklemek.","alignmentCues":["Dizini halata doğru yüksekçe kaldır.","Uzun bir sırtla kalçalarda bükülerek ayakta kalan dizin içine otur.","Halat diğer taraftan çıktığında tekrar yukarı kalk."],"props":["halat"],"commonMistakes":["Kalçalarda bükülmeden aşağıya uzanmak yerine sırtı yuvarlaklaştırarak.","Dizini düşük tutarak halatın uyluğa çarpmasına izin vermek.","Hızlanmak."]},"hoop-corkscrew":{"name":"Korkscrew","description":"Kalçalara doğru spiraller halinde inen ve tekrar yukarı çıkan bir halat, halat bir şamandıra çiziyor.","goodFor":"Bir halatı seviyeler arasında hareket ettirmek.","alignmentCues":["Aşağı inmek için dizleri bük.","Hoop'u düz tut."],"props":["halat"],"commonMistakes":["Hoop'un aşağı doğru eğilmesi.","Dönmeyi yavaşlatma."]},"hoop-barrel-roll":{"name":"Barrel Roll","description":"Dört vuruşta bir kez vücudun etrafında dönen bir el döndürmesi, hoop sizin etrafında yuvarlanıyor.","goodFor":"Tam daire şeklinde vücut dışı akış.","alignmentCues":["Hoop ile birlikte dön.","Sürekli dönmeye devam et."],"props":["halat"],"commonMistakes":["Hoop'un vücuda takılması.","Dönmeyi arkada durdurma."]},"hoop-chest-roll":{"name":"Göğüs Yolu","description":"Bir el döndürmesini göğse bırakın ve diğer elin yanına doğru yuvarlanmasına izin verin.","goodFor":"İlk hoop yuvarlanışı.","alignmentCues":["Göğüs yukarı.","Yuvarlanırken kolları aç."],"props":["halat"],"commonMistakes":["Göğüs çökmesi.","Erken kavrama."]},"hoop-back-roll":{"name":"Arka Yol","description":"Hoop, bir elden diğer eline doğru omuzların arkasından geçer.","goodFor":"Vücudun arkasında yuvarlanmalar.","alignmentCues":["Omuz bıçakları birbirine yakın.","Baş biraz öne."],"props":["halat"],"commonMistakes":["Sırtın kıvrılması.","Halatın düşmesi."]},"hoop-isopop":{"name":"Iso Pop","description":"Her iki vuruşta bir halatı yan tarafa durdurup patlatan ve devam eden bir izolasyon.","goodFor":"İzolasyonlarda vurgular ve duraklamalar.","alignmentCues":["Vuruşta patlat.","Patlamalar arasında izolasyon temiz kalır."],"props":["halat"],"commonMistakes":["Patlamalar çok büyük.","Merkezin kayması."]},"hoop-wheel-isolation":{"name":"Yan İzolasyon","description":"Vites düzleminde vücut yanında bir izolasyon.","goodFor":"İkinci düzlemde izolasyonlar.","alignmentCues":["Sizde sabit merkez.","El onun etrafında döner."],"props":["halat"],"commonMistakes":["Merkezin kayması.","Yamukluk."]},"hoop-floor-isolation":{"name":"Düz İzolasyon","description":"Hoop düz bir şekilde yatarken, merkezi sabitken elin döndüğü bir izolasyon.","goodFor":"Zemin düzleminde izolasyonlar.","alignmentCues":["Hoop seviyesinde.","Sabit merkez."],"props":["halat"],"commonMistakes":["Yan yatırma.","Merkez kayması."]},"doubles-hand-spins":{"name":"İki Eli Döndürmeler","description":"Her iki elde birer halka, karşılıklı olarak önünüzde dönen.","goodFor":"İlk çift hareket.","alignmentCues":["Halkalar yan yana.","Hızı eşitle."],"props":["iki halka"],"commonMistakes":["Halkaların çarpışması.","Birinin yavaşlaması."]},"doubles-offset-spins":{"name":"İki Eli Kaydırılmış Döndürmeler","description":"Aynı yönde dönen çift el dönerleri, yarım tur arayla.","goodFor":"Elin bağımsız ritmi.","alignmentCues":["Birinin yukarı birinin aşağı olması.","Aynı yönde."],"props":["iki halka"],"commonMistakes":["Senkronize olma.","Çarpışma."]},"doubles-side-spins":{"name":"İki Eli Yan Döndürmeler","description":"Çark düzleminde her iki kalçanın yanında birer halka dönen.","goodFor":"Çark düzlemindeki çiftler.","alignmentCues":["Halkalar dik.","Bacaklardan uzak."],"props":["iki halka"],"commonMistakes":["Bacaklara çarpmak.","Yan yatma."]},"doubles-floor-spins":{"name":"Çift Lasso","description":"Her elde bir lasso, ayna görüntüsü.","goodFor":"Üstteki ikililer.","alignmentCues":["İkisi de düz.","Küçük el döngüleri."],"props":["iki halka"],"commonMistakes":["Halkaların birbirine değmesi.","Kolların yorulması."]},"doubles-wedgies":{"name":"Çift Wedgies","description":"Her elde bir wedgie, her iki halka da baş parmak çukurlarında sallanıyor.","goodFor":"İkililer sallanma hareketleri.","alignmentCues":["Baş parmaklar dışarı.","Eşit sallanmalar."],"props":["iki halka"],"commonMistakes":["Halkaların çarpışması.","Eşit olmayan zamanlama."]},"doubles-coin-flips":{"name":"Çift Para Atışı","description":"Her iki elde aynı anda bir madeni para atışı.","goodFor":"İkililer parmak kontrolü.","alignmentCues":["İkisi de dik.","Birlikte fırlat."],"props":["iki halka"],"commonMistakes":["Yan yatma.","Çarpışma."]},"doubles-isolations":{"name":"Çift İzolasyonlar","description":"Her elde bir izoleasyon, her ikisi de yan yana sabit merkezlerle.","goodFor":"Bir kez iki izoleasyon.","alignmentCues":["İkinci merkezler hâlâ sabit.","Eller birlikte döner."],"props":["iki halka"],"commonMistakes":["Merkezler kayıyor.","Halkalar çarpışıyor."]},"doubles-toss":{"name":"Çift Atma","description":"İkisini de birlikte yukarı atıp, tekrar çift dönerliklere alarak yakalayın.","goodFor":"Çift bırakmalar için.","alignmentCues":["Birlikte doğrultuyla yukarı atın.","Attığınız yere yakalayın."],"props":["iki halka"],"commonMistakes":["Eşit olmayan atışlar.","İleriye kayıyor."]},"doubles-waist-and-hand":{"name":"Bel Hoop ve El Çevirme","description":"Belde bir halkayı devam ettirirken, sol elde ikinci birini döndürün.","goodFor":"Vücut ve el arasında dikkat dağıtmak için.","alignmentCues":["Omuzlar ritmini korur.","El dönerliği vücut halkasının önünde olmalı."],"props":["iki halka"],"commonMistakes":["Vücut halkası yavaşlıyor.","El halkası vücut halkasına çarpıyor."]},"doubles-chest-and-hand":{"name":"Göğüs Hoop ve El Çevirme","description":"Bir kol yukarıda iken diğer el ile ikinci bir halka döndürülerek göğüs halkası.","goodFor":"El hareketi ile yüksek vücut halkası.","alignmentCues":["Bir kol yukarı.","Kaburga vücut halkasını hareket ettirir."],"props":["iki halka"],"commonMistakes":["Kolun göğüs halkasına düşmesi.","Pulsu kaybetmek."]},"doubles-waist-and-lasso":{"name":"Bel Halkası ve Lasso","description":"Beldeki halka aşağıda, lasso ise başın üzerinde: iki seviyede aynı anda iki halka.","goodFor":"İki seviyede birlikte halka.","alignmentCues":["Bel pulsu, el döner.","Lasso seviyesi başın üzerinde."],"props":["iki halka"],"commonMistakes":["Vücut halkasının düşmesi.","Lassonun eğilmesi."]},"poi-one-hand-spin":{"name":"Bir El ile Poi Öne Dönüş","description":"Bir saat eli gibi önünüzde dönen bir poi, başınız yanınızdan geçer. Bilek küçük ve sabit bir daire yapar ve bağ gevşek kalır.","goodFor":"Bağın çekmesini ve bir vuruşta bir dönüş ritmini hissetmek.","alignmentCues":["Küçük bilek daireleri, büyük poi daireleri.","Daireyi önünüzde düz tutun, bir pencere camı gibi."],"props":["bir poi"],"commonMistakes":["Omuzdan sallamak.","Daireyi size doğru eğmek."]},"poi-wall-spin":{"name":"Öne Duvar Dönüşü","description":"Her iki poi de önünüzde birlikte döner, biri her omzun yanında, bir eksen üzerinde iki tekerlek gibi yan yana. İlk iki poi hareketi.","goodFor":"İkisi de birbirleriyle ve ritimle aynı anda.","alignmentCues":["İki baş da birlikte en üste ulaşır.","Eller omuz genişliğinde."],"props":["bir çift poi"],"commonMistakes":["Bir poi diğerinden geride kalıyor.","Dairesel hareketler birbirine doğru kayıyor."]},"poi-reverse-wall-spin":{"name":"Arka Duvar Döndürmesi","description":"Duvar dönüşünün tersi: başlar dışarıya doğru yukarı çıkar ve ortaya düşer.","goodFor":"Ön ve çiçeklerden önce her iki yönde.","alignmentCues":["Aynı düzlem, sadece yön değişiyor.","Daireleri bileğin arkasıyla yönet."],"props":["bir çift poi"],"commonMistakes":["İleri dönüşe geri kayma.","Düzlemler öne doğru eğiliyor."]},"poi-split-time":{"name":"Split-Time Duvar Döndürmesi","description":"İki poi aynı yönde dönüyor ama yarım tur farkla: biri en tepede iken diğeri en altta. Her örgüdeki zamanlama buna dayanıyor.","goodFor":"İki elde bağımsız zamanlama.","alignmentCues":["Yukarı, aşağı, yukarı, aşağı: başlar dönüşür.","Her poi'nin en üstteki anını ritimde ve ve sayın."],"props":["bir çift poi"],"commonMistakes":["Aynı zamana geri kayma.","Ellerin farklı hızlarda hareket etmesi."]},"poi-butterfly":{"name":"Kelebek","description":"Eller birbirine yakın, poi'ler ters yönde dönüyor, böylece başlar bir kelebek kanatları gibi yukarı ve aşağıda buluşuyor.","goodFor":"Ters yönlü zamanlama ve yakın el.","alignmentCues":["Üstte ve altta başlar öpüşür.","Bilekler neredeyse dokunuyor."],"props":["iki adet poi"],"commonMistakes":["Düzlemler kesişirken başlar çarpışıyor.","Eller birbirinden uzaklaşıyor."]},"poi-reverse-butterfly":{"name":"Ters Kelebek","description":"Her iki kanat da diğer yöne dönen kelebek: başlar ortada birlikte yukarı çıkar ve dış taraflardan aşağı iner.","goodFor":"Kelebeği her iki yönde dengelemek.","alignmentCues":["Üstte ortada buluşun.","İleri kelebekle aynı yakın el."],"props":["iki adet poi"],"commonMistakes":["Üstte başlar birbirine dolanıyor.","Bir kanat sarkıyor."]},"poi-chase-the-sun":{"name":"Güneşi Takip Et","description":"Eller önde birlikte ve zamanlama ayrı: iki baş bir büyük daire boyunca birbirini takip eder, her zaman yarım dönüş uzaktadır.","goodFor":"Eller yakın, örgü için hazır, zamanlama ayrı.","alignmentCues":["Bir baş her zaman diğerine zıt.","Eller birlikte hareket eder."],"props":["iki adet poi"],"commonMistakes":["Başlar birbirine yetişiyor.","Eller ayrılıyor."]},"poi-wheels":{"name":"İleri Tekerlekler","description":"Her iki poi de bisikletin tekerlekleri gibi yanınızda dönüyor, tepeleri ileri doğru yuvarlanıyor.","goodFor":"Vites düzlemi, vücudun yanında.","alignmentCues":["Daireler yanlarınızla paralel gidiyor.","Dirsekler yumuşak ve yakın."],"props":["iki adet poi"],"commonMistakes":["Poi'lerin bacaklara çarpması.","Tekerleklerin dışa doğru yayılması."]},"poi-reverse-wheels":{"name":"Geride Çarklar","description":"Siz yanınızda geriye doğru dönen tekerlekler, başlar ön tarafta yukarı çıkıp arkada düşer.","goodFor":"Tekerlek düzleminde her iki yön.","alignmentCues":["Aynı tekerlekler, ters yönde.","Omuzlar aşağı ve rahat."],"props":["iki adet poi"],"commonMistakes":["Tekerleklerin vücudun arkasına kayması.","Bileklerin sertleşmesi."]},"poi-fountain":{"name":"Şelale","description":"Tekerlekler eş zamanlı değil: bir poi yükselirken diğeri düşer, sizin yanında bir şelale gibi.","goodFor":"Tekerlek düzleminde eş zamanlı olmayan zamanlama, yürüyüş örgüsünün temeli.","alignmentCues":["Biri yukarı, biri aşağı.","Eller arasındaki ritmi eşit tutun."],"props":["iki adet poi"],"commonMistakes":["Zamanlamada eş zamanlı hale gelme.","Tekerleklerin içeriye doğru eğilmesi."]},"poi-opposite-wheels":{"name":"Karşıt Çarklar","description":"Bir tekerlek ileri dönerken diğeri geri döner. Başlar yukarıda ve aşağıda birbirini geçer.","goodFor":"Ellerin karşıt yönde dönmesiyle koordinasyon.","alignmentCues":["İkisi de aynı anda tepede.","Her el kendi yönünü korur."],"props":["iki poi"],"commonMistakes":["Her iki el aynı yönde geçiş yapar.","Bir tekerlek küçülür."]},"poi-overhead":{"name":"Üstten Zemin Döndürmesi","description":"İkinci poi, başınızın düz ve hafifçe dışa doğru düşen bir şekilde helikopter pervaneleri gibi yukarıda döner.","goodFor":"Yere paralel ve sabit omuzlarla üstteki pozisyon.","alignmentCues":["Ellerin başın hemen üzerinde olması.","Poi düzlemini aç; kaslamayın."],"props":["iki poi"],"commonMistakes":["Omuzların çökmesi.","Poi ön tarafında düşer."]},"poi-low-floor":{"name":"Bel Yüksekliğinde Zemin Döndürmesi","description":"Yere yakın, bel seviyesindeki düzlemde: poi'ler yanınızda bel yüksekliğinde dönerken taranır.","goodFor":"Zemin-karışık duvar pozisyonlarında kullanılan düşük düzlem.","alignmentCues":["Elleri kalçaların yanında dışarıya doğru uzat.","Daireleri seviyeli tut."],"props":["iki poi"],"commonMistakes":["Poi dizlerine çarpar.","İleriye eğilme."]},"poi-three-beat-weave":{"name":"Üç-Beat Dokuma","description":"Özgün poi hareketi: bir taraftan diğer tarafa geçerek, kolların düzlem değiştikçe kesişip kesişmemesiyle dönen split-time poi.","goodFor":"Her poi spinerinin geliştirdiği akış hareketi.","alignmentCues":["Kolların döndüğü yönde omuzları çevirin.","Düzlemler hafifçe her tarafa doğru eğilir."],"props":["iki poi"],"commonMistakes":["Ellerin ortada kalması.","Poi'ların kesişme noktasında birbirine çarpması."]},"poi-reverse-three-beat-weave":{"name":"Ters Üç-Nefes Dokuma","description":"Her iki poi'nin de geriye doğru dönen üç vuruşlu dokuma. Kollar alttan değil, üstten geçer.","goodFor":"Her iki yönde dokuma yapmak.","alignmentCues":["Aynı yan yana desen, ters dönüş.","Elleri göğüs yüksekliğinde tutun."],"props":["bir çift poi"],"commonMistakes":["Kafaların tepede çarpışması.","Dokumanın bir tarafa küçülmesi."]},"poi-two-beat-weave":{"name":"İki-Nefes Dokuma","description":"Her vuruşta taraf değiştiren daha hızlı bir dokuma. Daha hızlı geçişler daha yoğun ve daha kompakt hale getirir.","goodFor":"Hızlı taraf değişiklikleri.","alignmentCues":["Daha küçük, daha hızlı omuz dönüşleri.","Bilekleri göğsün yakınında kesiştirin."],"props":["bir çift poi"],"commonMistakes":["Üç vuruşlu tempo geriye düşmek.","Bölünmeyi kaybetmek."]},"poi-five-beat-weave":{"name":"Beş-Nefes Dokuma","description":"Daha uzun, daha geniş bir dokuma: poi'lar tekrar geçmeden önce her iki tarafta daha fazla dönüş yapar.","goodFor":"Dokuma şeklini daha uzun parçalarda tutmak.","alignmentCues":["Geniş omuz dönüşleri.","Kesişmeleri düzgün tutun."],"props":["bir çift poi"],"commonMistakes":["Çok erken kesişmek.","Uçurumun düzleşmesi."]},"poi-behind-back-weave":{"name":"Arka Arkası Dokuma","description":"Her iki ritimde bir, sağ poi arkanızın arkasından dolaşıp zamanı bozmadan ön tarafa döner.","goodFor":"Basit bir desenin görünümünü değiştiren vücut geçişleri.","alignmentCues":["Belin arkasına doğru alçakta uzanın.","İleriye bakın, zamanlamaya güvenin."],"props":["poi çifti"],"commonMistakes":["Poi'nin sırtı vurması.","Ön poi dururken arka olan hareket eder."]},"poi-crossers":{"name":"Kesici","description":"Kollarınız önünüzde kesişirken ve tekrar açılırken aynı anda duvar dönüşleri yapın, her ritimde poi'ler yanlar arasında değişir.","goodFor":"Poi'lerle zaman içinde kolların kesişmesi.","alignmentCues":["Bileklerde kesişin.","Her iki poi'yi de adım adım tutun."],"props":["poi çifti"],"commonMistakes":["Kollar kesişirken tethers'ın birbirine girmesi.","Bir poi'nin durması."]},"poi-reels":{"name":"Sargılar","description":"Her iki poi birlikte bir tarafında bir bar boyunca döner, sonra diğer tarafa sallanır.","goodFor":"Her iki poi'yi bir birim olarak vücut etrafında hareket ettirme.","alignmentCues":["Eller birbirine yakın kalsın.","Vücudunuzu her iki tarafa bakacak şekilde çevirin."],"props":["poi çifti"],"commonMistakes":["Geçerken ellerin ayrılması.","Ritimden sapma."]},"poi-thread-the-needle":{"name":"İğne İpi","description":"Karşı yönde, kolları kesişen iki zamanlı poi: bir poi, diğerinin az önce bıraktığı boşluktan geçer.","goodFor":"İki el arasındaki hassas zamanlama.","alignmentCues":["Boşluk açıldığında kesiş.","Dairesi sık tut."],"props":["poi çifti"],"commonMistakes":["Poi'lerin kesişme anında çarpışması.","Zamanlama aynı zamana kayması."]},"poi-buzzsaw":{"name":"Buzzer","description":"Eller birbirine bastırılmış ve her iki poi de birlikte dönmüş, iple birlikte bir dönen bıçak gibi yan yana.","goodFor":"İki poi'nin tam olarak eşleştirilmesi.","alignmentCues":["Avuçlar birbirine, bilekler gevşek.","Bir daire, iki baş."],"props":["poi çifti"],"commonMistakes":["Başların ayrılması.","Ellerin birbirinden uzaklaşması."]},"poi-one-hand-isolation":{"name":"One-Poi İzolasyonu","description":"El, başın tam karşısında aynı hızda döner, böylece ipin ortası havada sabit gibi görünürken poi onun etrafında döner.","goodFor":"İlk illüzyon: uzaydaki sabit bir nokta.","alignmentCues":["El her zaman başın karşısında olmalı.","Başa değil, ipin ortasına bak."],"props":["bir poi"],"commonMistakes":["El dairesi çok küçük, bu yüzden nokta dolaşır.","En tepede hızlanma."]},"poi-isolation":{"name":"Ayrılıklar","description":"İki elde aynı anda izolasyonlar, iki sabit nokta önünüzde yan yana.","goodFor":"İki el illüzyon kontrolü.","alignmentCues":["İkinci eliniz başlarınızın karşısındadır.","Kollarınız yumuşak, omuzlarınız aşağıdadır."],"props":["poi çifti"],"commonMistakes":["Bir elin izolasyonunu kaybetmesi.","Noktalar ileriye doğru kayıyor."]},"poi-split-isolation":{"name":"Split-Time İzolasyonları","description":"Yarım dönüş aralığında izolasyonlar: bir el yukarı, diğer el aşağı; hala sabit duran noktalar.","goodFor":"Split zamanında izolasyon zamanlaması.","alignmentCues":["Eller sırayla üst ve alt pozisyonlarda olur.","Noktalar birbirlerine eşit seviyede kalır."],"props":["poi çifti"],"commonMistakes":["Ellerin senkronize olması.","Noktaların düşmesi."]},"poi-wheel-isolation":{"name":"Wheel-Plane İzolasyonları","description":"Tekerlek düzleminde yanınızda izolasyonlar, hala yanlarınızda süzülen noktalar.","goodFor":"İkinci bir düzlemde izolasyonlar.","alignmentCues":["Noktalar kalça seviyesinde olur.","Eller yanlarınıza paralel olarak döner."],"props":["poi çifti"],"commonMistakes":["Düzlemlerin dışa doğru dönmesi.","Ellerin vücudunuzdan çok yakın olması."]},"poi-extension":{"name":"Uzantılar","description":"Kol ve kablo tek bir doğrusal çizgide, el genişçe dönerken poi en büyük çemberi izler.","goodFor":"Büyük, açık şekiller ve cateye'nin yarısı.","alignmentCues":["Omuzdan uzanın.","El ve baş merkezden aynı doğrultuda."],"props":["poi çifti"],"commonMistakes":["Bilekten bükülme.","Dairesel hareketlerin alt kısmında çökme."]},"poi-cateye":{"name":"Kateye","description":"Bir el izole edilirken diğer el uzatılır. İki yol, bir kedi gözü gibi badem şeklinde üst üste gelir.","goodFor":"Aynı anda iki farklı el yolu karıştırma.","alignmentCues":["İzole edilen el sıkı, uzatılan el geniş.","İkisi de aynı anda tepeden başlar."],"props":["poi çifti"],"commonMistakes":["İki el aynı şeyi yapar.","Şekil dengesiz."]},"poi-one-hand-antispin":{"name":"Bir El Antispin","description":"El bir yönde dönerken poi diğer yönde döner, her el dönerken üç dönüş, dört yapraklı bir çiçek çizer.","goodFor":"İki poi ile çiçeklerden önce antispin hissi.","alignmentCues":["El döngüsü geniş ve yavaş.","Her yaprak ucu el döngüsünün kenarında."],"props":["bir poi"],"commonMistakes":["Poinin düz dönmeye geri dönmesi.","Yapraklar eşit değil."]},"poi-antispin-flower":{"name":"Dört-Petallı Antispin","description":"İki elde aynı anda antispin çiçekleri, yan yana iki dört yapraklı çiçek açar.","goodFor":"Klasik poi çiçeği.","alignmentCues":["Eller birlikte döner.","Yapraklar hizalanır: üst, yan, alt, yan."],"props":["iki poi"],"commonMistakes":["Bir el spin'e düşüyor.","Çiçekler ileriye kayıyor."]},"poi-split-antispin":{"name":"Bölünmüş-Zaman Antispin","description":"Dört petal çiçeği, poi'lar birbirinden yarım dönüş ayırmış ve bir çiçeğin petalleri diğerinin boşluklarını dolduruyor.","goodFor":"Split zamanında çiçek zamanlaması.","alignmentCues":["Eller, dairelerinde karşı karşıya olmalı.","Petaller kesişmeli."],"props":["iki poi"],"commonMistakes":["Aynı zamana çöküyor.","Eller farklı hızlarda dönmeli."]},"poi-three-petal-antispin":{"name":"Üç-Petallı Antispin","description":"Üç petal çiçeği: her el daireye iki antispin vererek üçgen bir açılım oluşturur.","goodFor":"El hızını değiştirerek petal sayısını değiştirmek.","alignmentCues":["Dört petallıdan daha hızlı el hareketi.","Petal, eşit aralıklarla üç noktada olmalı."],"props":["poik çifti"],"commonMistakes":["Dört petallıya geri dönmek.","El çemberinin küçülmesi."]},"poi-five-petal-antispin":{"name":"Beş-Petallı Antispin","description":"Her el çemberinde dört antispin, daha yavaş ve geniş bir el ile beş petallı bir çiçek.","goodFor":"El-poi oranını ince ayarlamak için.","alignmentCues":["Çok yavaş el hareketi.","Her el çemberinde dört poi dönüşü say."],"props":["poik çifti"],"commonMistakes":["Pembe sayısını kaybetmek.","El durması."]},"poi-wheel-antispin":{"name":"Tekerlek-Uçak Antispin","description":"Dairesel düzlemde senin yanında dört yapraklı antispin çiçekler.","goodFor":"Dairesel düzlemdeki çiçekler.","alignmentCues":["Çiçekler yanlarınıza paralel olmalı.","Eller kalçaların yanında dönmeli."],"props":["poi çifti"],"commonMistakes":["Düzlem içeriye eğilmek.","Yapraklar bacakları kesmek."]},"poi-overhead-antispin":{"name":"Üstten Antispin","description":"Antispin çiçekler başının düz, açılan yapraklarıyla üstünde.","goodFor":"Zemin düzlemi çiçekleri.","alignmentCues":["Eller başın hemen üzerinde olmalı.","Yapraklar seviyede kalmalı."],"props":["poi çifti"],"commonMistakes":["Çiçekler ileriye eğilmek.","Omuzlar yorulup düşmek."]},"poi-antispin-and-spin":{"name":"Antispin ve Spin","description":"Sağ el, dört yapraklı antispin çiçeği çizerken sol el basit ileri dönüş yapar.","goodFor":"El bağımsızlığı: Aynı anda iki farklı şekil.","alignmentCues":["Dönen el sıkı kalmalı.","Çiçek eli geniş dönmeli."],"props":["poi çifti"],"commonMistakes":["İkinci el birbirini kopyalıyor.","Poi'nun dönüş hızının azalması."]},"poi-inspin-flower":{"name":"Dört-Petallı Inspin","description":"El, poi ile aynı yönde yavaşça döner, her el döngüsü için beş dönüş, içe doğru bakan döngüler çizer.","goodFor":"Antispin'in karşıtı olan inspin çiçekleri.","alignmentCues":["El ve poi aynı yönde döner.","Petek döngüleri merkeze bakar."],"props":["bir çift poi"],"commonMistakes":["El döngüsü çok hızlı.","Döngüler eşit değil."]},"poi-three-petal-inspin":{"name":"Üç-Petallı Inspin","description":"Her el döngüsü için dört dönüşle inspin, üç döngülü bir çiçek çizer.","goodFor":"Inspin petek sayılarını değiştirme.","alignmentCues":["Dört petekten biraz daha hızlı el.","Üç döngü, eşit aralıklarla."],"props":["bir çift poi"],"commonMistakes":["Yanlış sayma.","Döngülerin düzleşmesi."]},"poi-wall-wheel-hybrid":{"name":"Duvar–Çark Hibriti","description":"Her devirde poi'ler düzlemleri değiştirir, önce ön sonra yan, baş aşağı geçerken dönüş yapar.","goodFor":"Dönmeyi bozmadan düzlemleri değiştirme.","alignmentCues":["Poi zemine doğru gösterdiğinde değiştir.","Bilek döner, tam kollar değil."],"props":["bir çift poi"],"commonMistakes":["Döngünün ortasında değiştirme.","Poi'lerin düzlemler arasında sallanması."]},"poi-wheel-floor-hybrid":{"name":"Tekerlek–Zemin Hibriti","description":"Poi'lar senin yanında dönerken ve düz bir şekilde tararken geçiş yapar, ileriye doğru işaretlerken değişir.","goodFor":"Yatay bir düzlemle ikinci bir hibrit.","alignmentCues":["Poi'nin ileriye doğru gösterdiği anda değiştirin.","Elleri bel seviyesinde tutun."],"props":["poik çifti"],"commonMistakes":["Poi'yi geçiş sırasında eğmek.","Ritm kaybetmek."]},"poi-floor-wall-hybrid":{"name":"Zemin–Duvar Hibriti","description":"Yatay üstten dik ön ve arka tarafa, poi'ların yanlara doğru gösterdiği anda değiştiren bir hareket.","goodFor":"Üstteki ve duvar düzlemlerini bağlamak için.","alignmentCues":["Poi yanlara doğru gösterdiğinde değiştirin.","Ellerini yumuşakça kaldırıp indir."],"props":["poik çifti"],"commonMistakes":["Poi başa çarpma.","Eşit olmayan geçişler."]},"poi-top-stall":{"name":"Durak","description":"Poi en tepede yükselir, elinin tam üstünde bir an durur ve oradan geldiği yoldan geri düşer.","goodFor":"Durdurma ve tersine çevirme: stall kombinleri ve hyperloopların temelidir.","alignmentCues":["Poi zirve yaparken elini kaldır.","Asılı kalsın, sonra geriye yönlendir."],"props":["tek poik"],"commonMistakes":["Tether gevşeyip sarılma.","Duraklama sırasında acele etme."]},"poi-stalls":{"name":"Çift Stall","description":"İki poi aynı anda tepede durur ve yan yana ters yönde döner.","goodFor":"İki el ile durma kontrolü.","alignmentCues":["İkisi de aynı anda zirveye ulaşır.","Eller birlikte kalkar."],"props":["bir çift poi"],"commonMistakes":["Bir poi'nin geç durması.","Poi'ların aşağı inerken çarpışması."]},"poi-side-stall":{"name":"Yan Staller","description":"Poi'lar tepede değil, yanlarda durur; her biri geri sallanmadan önce omuz hizasında durur.","goodFor":"Dairenin farklı bir noktasında durma.","alignmentCues":["Poi yanlara doğru gösterdiğinde durur.","Kollar yumuşak."],"props":["bir çift poi"],"commonMistakes":["Poi'nin durmak yerine düşmesi.","Zamanlama kayması."]},"poi-chasing-stalls":{"name":"Kovalamaca Staller","description":"Yarım bir vuruş arayla durma: bir poi zirvede dururken diğeri hâlâ yukarı doğru gider.","goodFor":"Yarım zamanlı durma.","alignmentCues":["Bir durma, sonra diğeri.","Elleri göğüs yüksekliğinde tutun."],"props":["bir çift poi"],"commonMistakes":["İkisinin birlikte durması.","İkinci durmayı acele etmek."]},"poi-hyperloop":{"name":"Hiperloop","description":"Uçak tepede ters dönen bir durma, böylece poi döner ve dairenin diğer yüzeyinde aşağı iner.","goodFor":"Duruşun tepesindeki üç boyutlu döngüler.","alignmentCues":["Duruşun tepesinde bileği çevir.","Bağlantıyı gergin tut."],"props":["bir poi"],"commonMistakes":["Poi zirveye ulaşmadan önce ters çevirmek.","Bağlantının gevşemesi."]},"poi-arm-wrap":{"name":"Kol Sarmalı","description":"Poi, öndeki diğer kolumuzun etrafında döner, daha kısa bir bağlantı ile daha hızlı döner, ardından tekrar tam bir daireye döner.","goodFor":"İlk sarma ve sarmaların poi'yi hızlandırması.","alignmentCues":["Sabit kolu sabit ve düz tut.","Dönen eli postun arkasında tut."],"props":["bir poi"],"commonMistakes":["Post kolu hareket etmek.","Yanlış yönde açmak."]},"poi-leg-wrap":{"name":"Bacak Sarmalı","description":"Dizini kaldır ve poi'nin uyluğa sarılmasını sağla, ardından açılırken bacağın aşağı indir.","goodFor":"Vücut üzerindeki sarmalar.","alignmentCues":["Poi geldiğinde diz yukarı.","Ayakta duran bacağın üzerinde dik kal."],"props":["bir poi"],"commonMistakes":["Dizini geç kalkmak.","Dengesini kaybetmek."]},"poi-neck-wrap":{"name":"Boyun Sarmalı","description":"Üstteki dönüşten başlayarak eli aşağı indirerek poi'yi boynun arkasına sar, ardından tekrar üstteki konuma aç.","goodFor":"Gösterişli bir sarma ve üstteki dönüşleri birbirine bağlar.","avoidIf":["Yumuşak başlı pratik poi kullanın; asla ateşli ile boy çevirmeler öğrenmeyin."],"alignmentCues":["Çene seviyesi, boy uzun.","Tetheri boyun tabanına yönlendirin."],"props":["bir poi"],"commonMistakes":["Başta sarmak.","Tether çok gevşek."]},"poi-cord-wrap":{"name":"Bağlama Sargısı","description":"Bir kelebekten, iki tether altta birbirine sarılır, başlar kısa kablolar üzerinde dönerken sonra çözülür.","goodFor":"İki poi arasında sarmalar.","alignmentCues":["Tetherleri kelebeğin alt kısmında buluşturun.","Sarmalarken elleri hareketsiz tutun."],"props":["poi çifti"],"commonMistakes":["Ellerin birbirinden uzaklaşması.","Sarma karmaşası."]},"poi-toss":{"name":"Poi Atışı","description":"Poi yukarı doğru sallandığında sapı bırakın. Hava içinde döner ve geri döndüğünde sapı yakalayın.","goodFor":"Bırakmalar ve yakalamalar.","avoidIf":["Yumuşak poi ile atışları ve etrafınızda boşlukla pratik yapın."],"alignmentCues":["Yukarı sallanırken bırakın.","Sapı, başa değil, sapı izleyin."],"props":["bir poi"],"commonMistakes":["Çok geç bırakmak.","Sap yerine tetheri tutmak."]},"poi-high-toss":{"name":"Yüksek Atış","description":"Kavrama öncesinde havada ekstra bir dönüşle daha yüksek bir atış.","goodFor":"Daha büyük ve dönen atışlar.","alignmentCues":["Atış sırasında daha güçlü bir itiş.","Kolu dönerek yakalayın."],"props":["tek poi"],"commonMistakes":["Atış ileriye kayıyor.","Yakalama sırasında çabuk yakalamaya çalışıyorsunuz."]},"poi-double-toss":{"name":"İki Katlı Atma","description":"İkinci poi, birincisinden sonra eş zamanlı olarak atılır ve tekrar dönen hareketin içine geri alınır.","goodFor":"İki el ile atış zamanlaması.","alignmentCues":["Birini, sonra diğerini bırakın.","Aynı sırayla yakalayın."],"props":["poi çifti"],"commonMistakes":["İkisini aynı anda bırakmak.","Bir poi'yu izlerken diğerini kaybedersiniz."]},"shake-out":{"name":"Sallanma","description":"Eşyaları yerleştirin ve elleri, bilekleri ve ön kolunu sallayın. Omuzlarınızı düşürün.","goodFor":"Zorlu rutinler arasında kısa bir sıfırlama için."},"breathe":{"name":"Dinlen ve Sıfırla","description":"Eşyaları yerleştirin, rahat ayakta durun ve kollarınızı gevşetin. Bir sonraki atıştan önce bir an dinlenin.","goodFor":"Kalp ritmini düşürür ve düşüşlerden sonra öfkeyi temizler."}}`),t={"warmup-mobility":{name:`Akış ısınması`,description:`Bilekler, omuzlar, sırt ve kalçaları sabit bir ritimle gevşetin. Herhangi bir eşya oturumuna önce kullanın.`,focus:`Sıcaklaştırma · esneklik`},"first-throws":{name:`İlk atışlar`,description:`Bir top, göz seviyesinde elden eline yayılan hareketle başlar, ardından her desenin temelini oluşturan iki top değişimi.`,focus:`Yakalama · temeller`},"cascade-builder":{name:`Kaskad oluşturucu`,description:`Üçüncü top katıldığında iki top dönüşümleri sırayla: kısa kaskad koşuları, sıfırla, tekrar koş.`,focus:`Yakalama · temeller`},"juggling-tempo-ladder":{name:`Kaskad tempolu merdiven`,description:`Üç tempoda kaskad, her basamakta birkaç vuruş daha hızlı. Hızlı basamaklar için daha düşük atışlar.`,focus:`Yakalama · tempo`},"siteswap-sampler":{name:`Siteswap örneği`,description:`423, 441 ve 531'e kaskad, ters kaskad ve duşak gibi temizleyici olarak. Her desen kaskad ile başlar ve biter.`,focus:`Yakalama · desenler`},"four-ball-session":{name:`Dört top oturumu`,description:`Her iki taraf için bir elde iki top, dört top şelalesi, ardından senkron şelale.`,focus:`Yakalama · sayılar`},"juggling-combo-flow":{name:`Sallama kombinasyonu akışı`,description:`Uzun bir akıcı set: kaskad, ters kaskad, Mills mess ve siteswap'ler bir müzik parçasına bağlanarak.`,focus:`Yakalama · kombinasyonlar`},"cascade-tricks":{name:`Kaskad teknikleri`,description:`Tenis, yarım duşak ve pençeler, her biri koşan bir kaskada düşürülür ve tekrar çıkarılır.`,focus:`Yakalama · varyasyonlar`},"juggling-body-throws":{name:`Vücut atışları`,description:`Altında, arkasından, kesikler ve penguenler: vücut etrafında atılan kaskade.`,focus:`Juggling · Vücut Atışları`},"sync-shapes":{name:`Senkron şekiller`,description:`Sütunlar, gökkuşağı kesişimi, kutu ve yo-yo: ikişer top atarak üç top kullanılır.`,focus:`Juggling · Senkron Desenler`},"club-foundations":{name:`Kulüp temelleri`,description:`Tek dönerler, iki çubuk değişim ve üç çubuk kaskadı, düzelerle bitirin.`,focus:`Koşu · çubuklar`},"passing-with-a-partner":{name:`Partnerle geçiş`,description:`Karşıya dönün ve geçiş yapın: bir topu karşıya, sonra her ikisi de iki topu, ardından altı sayım, dört sayım ve iki sayım.`,focus:`Koşu · geçiş`},"club-passing-session":{name:`Kulüp geçişi`,description:`Çubuk dört sayımıyla ısınma, ritim için iki sayım ve üç sayım, ardından çift geçişler.`,focus:`Koşu · çubuk geçişi`},"hoop-juggling-session":{name:`Hoop juggligni`,description:`Tam boy halkalar kenarları ile atılır: tek atışlar, değişim, kaskad ve tersi.`,focus:`Koşu · halkalar`},"staff-first-spins":{name:`İlk çubuk dönüşleri`,description:`Köşe dönmeleri, ardından ön dönmeler. Yavaş ve eşit dönüşler, biri her vuruşta.`,focus:`Köşe · temeller`},"staff-foundations":{name:`Çubuk temelleri`,description:`Köşe dönmeleri, ön dönmeler, figür 8 ve elden eline geçişler, vuruşlara uygun şekilde bağlanır.`,focus:`Köşe · temeller`},"staff-flow-weave":{name:`Çubuk akış dokuması`,description:`Figür 8'den kelebek yapısına geçiş, tek el dönmeleri ve helikopter hareketleri, köşeyi hiç durdurmadan birleştirilir.`,focus:`Köşe · akış`},"staff-isolation-lab":{name:`Çubuk izolasyon laboratuvarı`,description:`Yavaş tempo ile izolasyonlar ve antispin çiçeği, aralarında arkadan geçen hareketlerle.`,focus:`Köşe · teknik`},"staff-advanced-flow":{name:`Çubuk ileri akış`,description:`Bir bütün parçada tam dili: dokunma, sarılma, izolasyonlar ve boyun çevirileri.`,focus:`Kalemi · akış`},"staff-both-ways":{name:`İki yönlü çubuk`,description:`Her temel dönüşün önce ileri sonra ters yönde yapılması, ayrıca iki el ile üstte helikopter hareketi.`,focus:`Kalemi · yön ve düzlemler`},"staff-contact-lab":{name:`Çubuk temas laboratuvarı`,description:`Açık el ve vücut teması: balık kuyrukları, direksiyon tekeri, el ve kol çevirileri ve sonunda bir atış.`,focus:`Kalemi · temas`},"double-staff-session":{name:`Çift çubuk oturumu`,description:`Her elde kısa bir kalemi: aynı zamanda, bölünmüş zamanla, tekerlekler ve bölünmüş tekerlekler.`,focus:`Kalemi · çift kalemi`},"hoop-first-spins":{name:`İlk halka dönüşleri`,description:`Ön-arka itiş ile belde halka döndürme, ardından bir el etrafında halkayı döndürme.`,focus:`Halka · temeller`},"hoop-body-flow":{name:`Halka vücut akışı`,description:`Halkayı göğsüne, dizlerine ve tekrar beline kadar hareket ettirme, durmadan.`,focus:`Halka · vücutta`},"hoop-off-body":{name:`Vücut dışı halka`,description:`El döndürmeleri, lasso, wedgies ve geçişler, sonunda halkayı uzayda sabit tutan izolasyonlarla bitirme.`,focus:`Halka · vücut dışında`},"hoop-full-flow":{name:`Halka tam akışı`,description:`Vücutta ve vücut dışında birlikte: eskalatörler, boyun halkası ve tek bir uzun akış içinde vücut dışı trickerler.`,focus:`Halka · akış`},"hoop-body-zones":{name:`Halka vücut bölgeleri`,description:`Bel hem ileri hem geri, ardından kalça, bacaklar ve göğüs bölgelerinde halkayı kaldırıp indirme.`,focus:`Hoop · vücut üzerinde`},"hoop-tricks-session":{name:`Halka numaraları`,description:`Yan dönüşler, madeni para çevirme, örgü, bir atış ve vücuda geri düşme.`,focus:`Hoop · vücut dışı`},"hoop-doubles-session":{name:`Halka ikilileri`,description:`İki halka: aynalı ve kaymalı el dönüşleri, yan dönüşler ve bir bel halkası ile el dönüşü.`,focus:`Hoop · çiftler`},"poi-foundations":{name:`Poi temelleri`,description:`Bir poi, sonra iki: ileri ve geri duvar dönüşleri, yanınızda çarklar, bölünmüş zaman ve kelebek.`,focus:`Poi · ilk dönüşler`},"poi-weave-session":{name:`Poi dokumaları`,description:`Bölünmüş zamanı üç vuruşlu örgüye, her iki yönde, ardından iki vuruşlu örgü, makaralar ve çaprazlar.`,focus:`Poi · örgüler`},"poi-flower-lab":{name:`Poi çiçek laboratuvarı`,description:`Uzatmalar ve izolasyonlar, ardından tek poi ve iki poi ile anti-spin, sonunda bir inspin çiçeğiyle bitirin.`,focus:`Poi · çiçekler`},"daily-mixed-flow":{name:`Günlük karışık akış`,description:`Her sanatın birazı: sıralama, direk döndürmeleri ve halka dansı, eşyalar arasında esneklik hareketleriyle.`,focus:`Karışık · uygulama`},"poi-symmetry-lab":{name:`Poi symmetry lab`,description:`Visit vertical-axis (together-opposite), central-point (split-same) and horizontal-axis (split-opposite) patterns with catalog moves.`,focus:`Poi · geometry`},"poi-hybrid-session":{name:`Poi hybrid session`,description:`Cateye, antispin-and-spin and plane hybrids with hide-one-prop study in mind.`,focus:`Poi · hybrids`},"poi-weave-degrees":{name:`Poi weave degrees`,description:`Split foundation into three-beat and five-beat weaves — try degree-of-twist cues in Settings.`,focus:`Poi · weaves`},"staff-symmetry-lab":{name:`Staff symmetry lab`,description:`Together-opposite butterfly, split-same fountain and figure-8 weave — three cells of the timing map on one staff.`,focus:`Staff · geometry`},"staff-flower-lab":{name:`Staff flower lab`,description:`Extensions into isolations, then four-petal antispin and a slower three-petal antispin.`,focus:`Staff · flowers`},"staff-contact-session":{name:`Staff contact session`,description:`Fishtail into hand and forearm rolls, angel roll, then a calm held spin to finish.`,focus:`Staff · contact`},"hoop-plane-lab":{name:`Hoop plane lab`,description:`Visit on-body floor work, off-body wall spins and a horizontal lasso so the plane map sticks.`,focus:`Hoop · planes`},"hoop-isolation-session":{name:`Hoop isolation session`,description:`Hand spin into isolation and cateye, then weave and pass to reconnect with travel.`,focus:`Hoop · isolations`}},n=JSON.parse(`{"start-here":{"title":"Buradan başlayın: Akışınızın ilk haftası","summary":"Bir alet seçin, ritme uygun şekilde günlük on dakika uygulayın ve kilidini açan ağacın size ne gelmesi gerektiğini söyler.","imageAlt":"3D figür, tek bir juggling topunu elden elye atıyor","body":["Akış sanatları dışarıdan bakıldığında büyüklük gibi görünür: toplar hava içinde asılı durur, bir direk bulanıklaşır, bir halka dansçıyı sadece hafifçe hareket eden bir şekilde döner. İçeriden bakıldığında ise çok küçük becerilerin yığıldığıdır, her biri bir öğleden sonra öğrenilebilir ve katman katman yığılınca kolay görünür. İlk haftanız bu yığının alt kısmını öğrenmek için.","Başlangıç için bir alet seçin. Juggling zamanlama ve göz-elle koordinasyonu öğretir; direk düzlemleri ve yumuşak el değişimlerini öğretir; halka tam vücutta ritmi öğretir. Üçünü de öğrenebilirsiniz, ancak biri bir kez öğrenmek dikkatinizin ilerleme noktasında kalmasını sağlar. Ödüller ağacı her sanatta ilk atış veya dönüşten ileriye doğru gelişmiş desenlere kadar tüm hareketleri gösterir ve size neyi öğrendiğinizi tamamladığınızda sonrakileri açar.","Kısa ve sık uygulayın. Günlük on dakikalık odaklı uygulama, Pazar günü bir saatlik uygulamadan daha etkilidir çünkü koordinasyon oturumlar arasında, özellikle uyku sırasında katlanır. Rütinler sayfasından kısa bir rutin, bir ısınma ve mevcut hareketinizin birkaç sayılı adımı tam bir uygulama oluşturur.","Birinci gününden itibaren ritme uygun olarak uygulayın. SynthFlow’da her hareket, müzik veya eşleşen bir perküsyonla eş zamanlı olarak ölçülen barlar cinsinden sayılır. Ritim, aletin işe yaramaması durumunda size tutunacak bir şey ve ilerlemenizi ölçebilir: bu hafta 90 BPM’de temiz bir geçiş, sonraki haftada 100 BPM’ye çıkar.","Düşmeler beklenir. Herkes düşer, özellikle profesyoneller de hazırlık sırasında düşerler. Bir düşme, hangi atış veya yakalama dikkat gerektirdiğini söyler; yetenekle ilgisi yoktur. Aleti alıp, bir sonraki aşağı vuruşu bekleyip tekrarlayın. Hafta sonunda düşünmeden yapabileceğiniz bir hareket edeceksiniz ve o anda akış başlar."]},"counting-and-the-beat":{"title":"Sayılar, çubuklar ve ritim","summary":"Her hareketin ritme göre bar cinsinden nasıl sayıldığı ve atışlarınız ve dönmelerinizin müzikle nasıl uyumlu hale getirileceği.","imageAlt":"3D figürün ellerinde üç top kaskadıyla, ellerinin üzerindeki yarım daireler çizilmiş","body":["Müzik, genellikle bir bar içinde dört vuruşla gruplandırılmış ritimlerden oluşur. Akış hareketleri, döngülerden oluşur: her elin atışı, direğin yarım dönüşü, halkanın bir turu. Bir döngünün ritme denk gelmesiyle hareket ve müzik tek bir şey haline gelir. Bu yüzden SynthFlow, her rutinin adımlarını saniyeler yerine barlar cinsinden ölçer ve her hareketin bir döngü için kaç vuruş gerektiğini belirtir.","Üç top kaskadında her atış, ritme denk gelir ve sağ-sol olarak değişir. Direğin önündeki dönüşte genellikle bir yarım dönüş bir vuruş alır. Belde halka yaparken gevşek bir tempo ile genellikle bir tur bir vuruşa denk gelir. Oyuncu adındaki sayılar, her vuruşta ne olacağını belirtir ve 3D figür sesle aynı saatte hareket eder, böylece zamanla kopyalayabilirsiniz.","Tempo, dakikada kaç vuruş (BPM) cinsinden ölçülür. Her hareketin bir aralıkta olması gerekir: yavaşça temiz kalmanızı sağlar ve hızlı olup aletin momentumunu korumasını sağlar. Bu aralığın altındaysa dönmeler durur ve atışlar çok yüksek olur; üstündeyse hızlanıp düşer. İnşaatçının, bir adım hareketinin aralığından dışarıda kaldığında uyarır.","Her adımı aşağı vuruşa (barın 'bir'ine) başlayın. Sayıma girme, ölçülen barlar başlamadan önce aleti hareket ettirmenizi sağlar. Ritmi kaybederseniz onu takip etmeyin: durun, bir sonraki 'bir'ini dinleyin ve geri dönün. Müzikçiler bu işlemi 'barın tepesine gelmek' olarak adlandırır ve akış sanatçıları için de geçerlidir.","Birkaç seans boyunca sesli saymak, göründüğünden daha fazla yardımcı olur. Topu atarken \\"bir, iki, üç, dört\\" demek, ritmi nefesinize ve sesinize bağlar, böylece desen zorlaştığında hayatta kalır. Sayılar vücudunuzda yaşayınca, Ayarlar'dan sözlü sayımı kapatın ve müziğin sizi taşımasına izin verin."]},"tempo-ladders":{"title":"Tempo merdivenleri: yavaş düzgün, düzgün hızlı","summary":"Temponuzu düzgün yapabildiğiniz bir noktadan başlayarak, her seferinde birkaç BPM yukarı çıkın ve form bozulduğunda hemen geri inin.","imageAlt":"Duvar düzleminde vücudun önünde bir sopa dönen 3D figür","body":["Bir tempo merdiveni, artan tempolarda tekrarlanan aynı harekettir: 80 BPM'de sekiz bar, 88'de sekiz, 96'da sekiz vb. Bir hareketi daha hızlı yaparken onu daha da karışık hale getirmeden bunu yapmanın en güvenilir yolu budur ve birkaç yerleşik rutin de buna dayanır.","Hatta çok kolay hissettikçe bile düzgün yapabileceğiniz bir basamaktan başlayın. Alt basamağın amacı zorluk değil; hızlanan şeyin form olması için doğru formu prova etmektir. Küçük bir miktar, yaklaşık beş ila on yüzde, yukarı çıkın. Büyük atlamalar hareketi değiştirir: atışlar daha düşük olur, dönüşler daha az derin olur ve farklı bir numara pratik etmiş olursunuz.","Düşürdüğünüzde değil, formunuz bozulduğunda tırmanmayı bırakın. Erken belirtileri izleyin: zirveler eşit olmaz, sopa düzleminden sapar, halka yukarı veya aşağı doğru kayar. Bunlar bir basamak geri inip tekrar yapmak için ipuçlarıdır. Bir merdiveni, sınırınızın biraz altında temiz bir şekilde bitirmek, vücudunuza o tempoyu öğretir; bir çarpmayla bitirmek ise çarpmayı öğretir.","Yavaş tempolar, dönen ekipmanlar için göründüğünden daha zordur çünkü ekipmanın geçişini sağlayacak daha az ivmesi vardır. Bir sopa veya halka aralığın alt kısmında durursa, tempoyu koruyun ve hareketi biraz daha genişletin ya da müziğin yarısında yapın: her iki vuruşta bir döngü.","Her hareket için ilerlemenizde en yüksek düzgün tempoyu takip edin. Bu sayının haftalar içinde yavaşça yükseldiğini görmek iyi bir motivasyondur ve aynı zamanda bir hareketin düzene girdiğini ve aynı şeyin daha fazlasından ziyade farklı bir egzersiz gerektirdiğini gösterir."]},"siteswap-notation":{"title":"Siteswap: jugglaj sayılarla yazılır","summary":"Her sayı, bir topun tekrar atıldığı saniyeyi gösterir; tek sayılar geçer, çift sayılar kalır ve ortalaması top sayısını verir.","imageAlt":"3D figür, iki yüksek atış ve hızlı bir zip ile siteswap 441'i top atarken","body":["Juggling desenleri sözlere çok zor ancak sayılarla kolayca anlatılabilir. Siteswap, 1980'ların ortalarında Cambridge, Caltech ve Santa Cruz'daki jüglerler tarafından bağımsız olarak geliştirildi ve bir deseni tekrar eden rakamlar dizisi şeklinde yazılır. Bu, jüglerlerin desenleri paylaşmaları, bir fikrin çalışıp çalışmayacağını kontrol etmeleri ve hiç kimse denememiştrickleri keşfetmeleri için kullanılır. SynthFlow bu sistemle her juggling desenini aynı motorla animate eder.","Her vuruşta sırayla sağ, sol, sağ, sol el ile fırlatmayı hayal edin. Siteswap'da bir rakam, bu vuruştan itibaren ne kadar sonra topun tekrar fırlatılacağını söyler. 3, üç vuruş sonra geri döner; çünkü üç tek sayıdır, diğer elde düşer. Üç top kaskadı sadece 3, 3, 3, 3... şeklinde sonsuza kadar devam eder ve basitçe 3 olarak yazılır. 4 ise aynı elde dört vuruş sonra geri döner ve bu dört top fountanıdır.","Küçük rakamlar özel anlamlara sahiptir. 2, iki vuruş sonra aynı elde döner ve pratikte bunun anlamı bir anda topu tutmaktır. 1, hemen bir sonraki vuruştan diğer elde geçer, hızlıca doğrudan karşıya geçer. 0 ise boş el anlamına gelir. Büyük rakamlar daha yüksek fırlatmaları ifade eder: 5, uzun kesişen bir fırlatmadır.","Bir deseni rakamdan rakama okuyun. 441'de iki top kendi tarafında kalırken üçüncü top onların altında hızlıca geçer. 531'de yüksek kesişen bir fırlatma yukarı çıkar, bir kaskad fırlatması ve bir zip diğer iki topu hareket ettirir. 423'te fountan boyutunda bir fırlatma, tutulan top ve bir kaskad fırlatması sırayla geçer.","Ortalama teoremi, bir desenin ne kadar top gerektirdiğini söyler: rakamları toplayıp kaç rakam olduğunu bölün. 441 üç rakamda 9'a eşit olur, yani üç top gerekir. Eğer ortalama tam sayı değilse, bu sıralama jüglenemez. İkinci kontrol ise aynı vuruşta iki topun aynı elde düşmemesi gerektiğidir; bu da jüglerlerin denemeden önce imkansız desenleri tespit etmelerini sağlar.","Siteswap ayrıca her iki elin birlikte fırlatmasını ifade eden parantez içinde yazılan (örneğin (4,4)) ve aynı elden birden fazla top fırlatmayı ifade eden kare parantezlerle yazılır. İyi jüglenmek için bunları kullanman gerekmez, ancak rakamların anlamları belli olunca her yeni desen adı kendini açıkça açıklar. Bireysel rakamlar için Flow sözlüğünü aç."]},"passing-basics":{"title":"Geçiş temelleri: bir partnerle jugglaj","summary":"Bir partnerine dön, sağ elleriyle birlikte fırlat ve doğrudan karşıdaki sol eline geç, say: altı-sayım, dört-sayım, iki-sayım.","imageAlt":"İki 3D jügler, birbirlerine dönük olarak, aralarında top geçirmek için doğrudan karşıya fırlatıyorlar","body":["Geçiş, başka biriyle yuvarlanmak demektir. İki yuvarlakçı, yüzlerini karşıya dönük olarak durur ve her ikisi de sıralı yuvarlama yapar; bazen biri topunu kendisine değil, partnerine doğru fırlatır. Yuvarlanmanın en sosyal yönlerinden biridir: kulaklık geçişleri, çoğu yuvarlakçı festival gecelerini geçirir ve bu şekilde pratik, bir konuşma haline gelir.","Toplar için yaklaşık iki metre yarımdan fazla mesafe bırakın; kulaklıklar için daha uzak olun. Her ikisi de aynı sayıyı kullanarak yuvarlanmaya başlayın ve sağ ellerinizle birlikte fırlatın. Standart geçiş doğrudur: sağ elden çıkar ve partnerinizin sol eline düşer, sizin karşısında doğrudan yer alır. Yüzünüze doğru değil fırlatılır. Sol kalça hedef alın ve başınızın hizasında zirve alan bir yayla fırlatın.","Geçiş desenleri, kaç kez geçiştirmenizle adlandırılır. Altı sayılı birde her altıncı atışta geçiş yaparsınız, bu da arada beş self bırakır. Dört sayılı, standart ısınma deseni olarak, her ikinci sağ el atışıyla geçiş yaparsınız: geçiş, self, self, self. İki sayılıda ise her sağ el atışı geçiş olur ve her sol el atışı self olur. Üç sayılıda geçişler sırayla farklı ellerden yapılır, bu da size sol el ile de geçiş yapmayı öğretir. Ultimates veya bir sayılıda ise her tek atış geçiş olur.","Başlangıçta beraber yüksek sesle sayın. 'Geçiş, iki, üç, dört' diye saymak aynı ritmi korur ve biriniz ritimden çıkarsa geçişler zamanında gelmez. SynthFlow'un sayma sesi, beat üzerinde geçiş atışlarınızda 'geçiş', diğer atışlarda ise 'self' der; bu şekilde yalnızca zamanlama pratik edebilirsiniz, ekranındaki partnerinizle beraber jügülür.","Bir top ile başlayın. Karşıya atın, partneriniz sol elden sağ eline geçirecek ve geri atacak. Sonra her biriniz iki top alıp sağ ellerinizi beraber kullanarak gelen topu soldan sağa doğru geçirmeniz gerekir. Sadece o zaman cascade ekleyebilirsiniz. En çok karşılaşılan düşmeler, uzun veya düz atışlardan kaynaklanır ve bunlar tek bir top ile daha kolay düzeltilir.","SynthFlow notasyonunda bir geçiş deseni, her bir vuruşu ve partnerinizin vuruşunu, her bir dövme için listeler: 'p' sembolü bir geçişi ifade eder; dört sayım <3p 3 3 3|3p 3 3 3> şeklindedir. Sayılar siteswap'da olduğu gibi aynı anlama gelir. Bir 4p, bir çift geçiştir ve bir vuruş sonra düşer; bu da yedi top desenlerinin nasıl oluşturulduğunu gösterir."]},"planes-and-geometry":{"title":"Düzlemler: duvar, tekerlek ve zemin","summary":"Dönen aletler düz planlarda hareket eder; bir staff veya halka keskin görünmesini sağlayan en büyük şey, planın temiz tutulmasıdır.","imageAlt":"Bir figür, vücudunun her iki tarafında da bir figure-8 deseniyle bir staff döndürüyor","body":["Dönen bir direk veya halka düz bir yüzey tarar; bu yüzeye 'düzlem' denir. Akış sanatçıları, vücuduna göre üç temel düzlem tanımlarlar. Duvar düzlemi, ellerinizi bastığınız cam gibi önünüzde yer alır. Tekerlek düzlemi, yanınızda, bir arabanın tekerleğinin yan tarafında döndüğü gibi durur. Zemin düzlemi yataydır ve zemine paraleldir; örneğin, hava yoluyla veya bir kovboyun kovboyuyla aynı şekilde.","Temiz düzlemler, izleyicilerin yetenek olarak algıladığı şeydir. Düzleminden çıkarak sallanan bir direk, düşmesine rağmen bile belirsiz görünür; geçiş sırasında tamamen düz kalan bir halka ise zorluk duymadan döner gibi görünür. Erken pratiklerin çoğu, düzlemlerle ilgili sessizdir: bileklerin dönmemesini sağlamak, kolun yayılmamasını sağlamak ve omuzların aleti elle değil, omuzlarla hareket ettirmek.","Çok sayıda trük, düzlemleri değiştirmekle tanımlanır. Bir figür-8 doku, çubuğu bir tarafındaki tekerlek düzleminden diğer tarafındaki tekerlek düzlemine taşır. Bir kelebek, çubuğu omzun arkasına katlar ve geriye doğru hareket eder. Bir merdiven, çubuğun vücudunu yukarı ve aşağı kaydırdığı bir halka ile ilerlerken düzlemi sabit tutar. Her hareketin uzayda nerede başladığını ve nerede bittiğini öğrenmek, onları akışa bağlamak için yeterlidir.","3D görüntüleyici, egzersiz yaparken düzlemi çizer. Yeni bir dönüş öğrendiğinizde açın ve karşılaştırın: çubuk, üstte sizden doğruya doğru eğiliyor mu? Halka, önünde aşağıya iniyor mu? Ayna veya telefon kamerası aynı şeyi gösterir. Duvar düzlemi hareketleri için yan görünümü özellikle faydalıdır çünkü eğim ön yüzten görünmez.","Düzlemler aynı zamanda güvenlik ve alan için de yardımcı olur. Bir oturumdan önce, kullanacağınız her düzlemin boş olduğundan emin olun: önündeki duvar, yanlarındaki duvarlar ve üstteki tavan, zemin düzlemi ve yukarıdaki hareketler için. İçinde hiçbir şey olmayan temiz bir düzlem, güvenli bir düzlemdir."]},"spin-and-antispin":{"title":"Spin, antispin ve izolasyonlar","summary":"Öğe el ile karşılaştırıldığında dönme yönüne göre üç hareket ailesi vardır: döndürme, antidöndürme ve izolasyon.","imageAlt":"3D figür, bir direk kullanarak dört petalı olan bir antidöndürme çiçeği çiziyor","body":["Bir dönme öğesini daire şeklinde hareket ettirdiğinizde iki dönüş aynı anda gerçekleşir: eliniz daire boyunca ilerler ve öğe kendi merkezine göre döner. Akış teorisi bu iki dönüşün nasıl ilişkili olduğunu adlandırır. Bu terimler, direk, halka ve poi için aynıdır ve bu nedenle öğeler arasında becerilerin kolayca aktarılmasını sağlar.","Döndürmede (bazen içdöndürme olarak da adlandırılır), öğe elin dairesel hareketiyle aynı yönde döner. Bu doğal bir yönüdür; çoğu ilk döndürme bu şekilde gerçekleşir ve bunun adı verilmez. İzlenen şekil, dışa doğru petallarına sahip bir çiçek gibidir.","Antispin'da, alet elin döndüğü yöne zıt yönde döner. İlk başta garip hissettirir, kafanı püfleyip karınını sürtmek gibi; ancak klasik bir petal çiçeği oluşturur. Petalların sayısı, her el dönüşünde aletin kaç kez döndüğünden kaynaklanır: her dönüşte üç ters dönme yapılırsa dört petal oluşur ve bu, direk ağacındaki Dört-Petal Antispin'dir.","İzolasyon, elin aleti döndürdüğü şekilde bir nokta uzayda donmuş gibi görünen özel bir durumdur. Direkte merkez sabit kalırken uçlar etrafında döner; halkada ise halkanın merkezi veya kenarındaki bir nokta sabit kalır. İzolasyonlarda alet havada asılı görünür ve beden onu çevreler. Bu, her diğer trıkk için mükemmel bir antrenmandır.","Bunları yavaşça ve ritme uygun olarak öğrenin. Özellikle antispin, normal döndürme hızınızdan çok daha düşük bir tempo ile fayda sağlar; bu durumda, aletin hangi konumda olacağını belirten sayılara (üst, yan, alt, yan) bakın. 3D görseldeki 'ghost' kullanarak son ritim pozisyonunu görün ve izi takip ederek çiçeğinizin eşit petallı olup olmadığını kontrol edin.","Spin, antispin ve izolasyon bir düzlemde alışkanlık kazandığınızda, başka bir düzleme geçin. Teorik yapı aynı kalır ve bedeniniz düzlemi sadece ayar olarak algılar; bu, akış içinde improvisasyona geçmenizin büyük bir adımıdır."]},"timing-and-direction":{"title":"Timing and direction: the four relationships","summary":"Together or split time, same or opposite direction — four relationships that let spinners name patterns and move between them.","imageAlt":"3D figure spinning a poi butterfly with hands close together","body":["Siteswap gives jugglers a shared language for throws. Spinners have something similar for two hands and two props: timing and direction. Timing asks whether the hands (or prop heads) reach the same place in the circle at the same moment — together — or half a turn apart — split. Direction asks whether they turn the same way around that circle or opposite ways. Combine the two and you get four basic relationships: together-same, together-opposite, split-same and split-opposite.","Together-same is the first wall spin most people learn: both poi or both staff ends travel as a pair. Split-same is the classic weave foundation, where one head is at the top when the other is at the bottom. Together-opposite looks like a butterfly when the hands sit close: the heads kiss at the top and bottom. Split-opposite is the remaining corner, with opposite directions and staggered timing.","These four states are not just labels. They form a small map. Each relationship shares two cardinal positions — top, bottom, or the far sides — with two of its neighbours. At a shared position you can reverse one hand and step into the neighbouring relationship. That is Transition Theory in everyday language: a circle of legal hops, like a musician’s circle of fifths for spinning. The hops that are forbidden are the ones with no shared position, such as jumping straight between together-opposite and split-same without an intermediate stop.","Hand-to-prop speed ratios sit on top of that map. Plain spin, where the hand and the head travel together, is often called a 1:1 CAP. A four-petal antispin flower is a 1:3 relationship: three head turns for each hand circle. A six-petal antispin (or the matching inspin) is 1:5. SynthFlow’s Timing lab lets you switch CAP presets while the 3D coach keeps the beat, so you can see the flower change without leaving offline practice.","Open Learn → Timing & Direction to explore the four cells, hide one prop to read hybrids more clearly, and drill recognition quizzes that stay on your device. The same words appear in the glossary under same time / split time, butterfly, antispin and flower. Once the map clicks, catalog move names stop feeling arbitrary — they become addresses you can travel between on purpose."]},"sequencing":{"title":"Akış rutinlerinin nasıl oluşturulduğu","summary":"Isınma yapın, tek odak noktasıyla akıcı bağlantılarla uygulama yapın, tempo atlamalarını küçük tutun ve kolay soğutma ile bitirin.","imageAlt":"3D figürün vücudu önünde elden elye halkayı geçişi","body":["İyi bir akış rutini, iyi bir müzik setinin şekline sahiptir: açılış odak noktasını ısıtır, orta kısım yükseltir ve son bölüm herkesin nefes almasına izin verir. SynthFlow’un yerleşik rutinleri bu yapıya uygun olup, inşa edici yardımcı, senin rutinin de bu şekle uygun olup olmadığını kontrol eder.","Isınma ile başlayın. Kollarınız ve omuzlarınız için yumuşak bir tempo ile bilek dönmeleri, kol dönmeleri ve omuz kaydırma hareketleri, uygulamada yüklenen eklemlerin aralığını kapsar. Kısa bir oturum için iki veya üç dakika yeterlidir; uzun oturumlar ve soğuk günler daha fazla zaman gerektirir.","Uygulama bloğunuzda tek bir odak noktası belirleyin. Çalıştığınız bir hareket seçin ve bunu akıcı bağlantılarla çevreleyin. İnşaatçı, her adımın önceki adıma nasıl bağlandığını gösterir: aynı el pozisyonundan doğrudan devam etmek, küçük tekrar kavrama yapmak, aleti yerleştirmek veya önceki bir trıkk üzerine inşa etmek. Akıcı rutinler dans gibi hissettirirken, çok fazla durdurma içeren rutinler liste gibi hissettirir.","Adım adımı arasında tempo değişikliklerini küçük tutun. 80'den 130 BPM'ye sıçramak zamanınızı sıfırlar ve düşmeleri teşvik eder. Kullanıcı yardımcı programı, yarım, katlanma ve iki katlı zaman atlamalarını işaretler; böylece 70 BPM'lik bir halka adımının 140 BPM'lik bir müzikle yan yana durması mümkün olur.","Fokus hareketine birden fazla kez dönerken, oturum içinde diğer hareketler arasında tekrar etmek, tek bir uzun blokla kıyaslandığında daha iyi beceri kazandırır; çünkü her dönüş, farklı bir başlangıç noktasından yeni bir deneyimdir.","Soğutma yapın: yavaş tempo ile kolay bir hareket veya kısa bir dinlenme ve birkaç nefes. Kalp atış hızınızı düşürür ve koordinasyonunuza hafif, anımsanacak bir son verir. Routine'u oynamadan önce önizleyin ve açıkça ‘dün’ün amacına uygun olan her şeyi kaldırın."]},"effort":{"title":"Tempoyu ne zaman artırmalıyız","summary":"Formun tuttuğu ve enerjiniz yüksekken zorlanın; zirve sallanıyor, kavrama sıkışıyor veya düşmeler bir araya geliyorsa hafifçe geri çekin.","imageAlt":"Yüksek bir sıralamada beş top fırlatan 3D figür","body":["Akış içinde ilerleme, yetenek sınırında pratik yapmaktan gelir, ama bu sınır değişir. Bazı günlerde beklediğinizden daha uzakta olur; bazı günlerde geri çekilmiştir. Bu sınıra bakmayı öğrenmek, herhangi bir tricker kadar değerli bir beceridir.","Temel hareketlerin tuttuğu zaman zorla. Zirveleriniz eşitse, çubuk düz bir düzlemde kalır, halka seviyesi sabit kalır ve nefesiniz kolay olursa, tempo merdiveninin bir üst basamağını alabilir veya ilerleme sırasındaki bir sonraki egzersizi deneyebilirsiniz. Bir oturumun ilk on beş dakikası, ısınma sonrası genellikle yeni içerikler için en iyi zamandır.","Kalite düşerse hafifçe azaltın. Toplu düşmeler, sıkı bir kavrama, omuzlarınızın kulaklarınıza doğru kayması ve nefesinizi tutmanız, sinir sisteminizin yorgun olduğunu gösterir. Tempoyu düşürün, kendinizin yapmayı bildiğiniz bir harekete dönelim ya da oturumu bitirin. Yorgunlukla mücadele etmek çoğunlukla hataları tekrar eder.","Fiziksel uyarıları da takip edin. Tekrarlı fırlatma ve döndürme bilekler, kol ön tarafı ve omuzları yükler. Bir gün içinde geçici olarak kaybolan ağrı normal adaptasyondur. Keskin ağrı, egzersiz sırasında artan ağrı, uyuşukluk veya sızılar durdurulmalı ve dinlenmelidir; sürekli semptomlar bir uzmana başvurulmalıdır.","Her oturumdan sonra çaba derecesini kullanın. Uygulama büyücüsü bu dereceyi okuyar: birkaç zorlu oturum ard arda gelirse daha yumuşak öneriler sunar, birkaç kolay oturum varsa biraz fazla önerir. Gerçekçi derecelendirme, daha iyi öneriler üretir."]},"drops-are-data":{"title":"Düşmeler veridir","summary":"Bir düşüş, hangi fırlatma veya yakalama düzeltileceğini söyler; bunu başarısızlık olarak görmeyin, sadece kasılmaları öğretirsiniz.","imageAlt":"İki juggling topunu eller arasında değiştiren 3D figür","body":["Her jüglerin bir zamanlar zemininde toplarla kaplı olduğu bir anı vardır. Her staff spinner, çalınmayı duymuştur. İyileşenlerle bırakanların arasındaki fark nadiren yeteneğe dayanır; bunun yerine, düşleri nasıl ele aldıklarıdır.","Bir düş, bir ölçümüdür. Hangi atışın yanlış gittiğini, hangi yakalamaya ulaştığınızı, dönmeyi kaybettiğiniz anı belirtir. Aynı top sürekli önünüzde yere düşerse, atışlarınız ileriye doğru kayıyor olabilir. Eğer düşler, altı atıştan sonra gelirse, üçüncü veya dördüncü atışınızda bir şey yanlışlıkta. Nerede ve ne zaman olduğunu gözlemleyin, ardından tek bir şey değiştirmeye çalışın.","Düşleri başarısızlık olarak görmeyi tercih etmek bir maliyetle gelir. Korku omuzları sıkıştırır ve nefesini kısaltır, gerilim hareketleri daha küçük ve hızlı hale getirir ki bu da daha fazla düş yaratır. Sessizce tepki vermek — al, nefes al, aşağı vuruşu bekleyip tekrar başlat — sadece hoş değil; teknik olarak doğru bir tepkidir.","Temiz atışları sayın, düşleri değil. SynthFlow, yeterli temiz atış ve pratik dakikalara sahip olduğunda bir hareketi tamamlar, bu nedenle yolculukta olan düşler sadece dakikaların parçasıdır. Bazı günlerde on temiz atış kaydedebilirsiniz, bazı günlerde iki tane de olabilir. Her ikisi de sayılır.","Bazen düşleri amaçlı olarak yapın. Yeni bir trükle öğrenirken, ilk atışı veya ilk yarım dönüşünü uygulayın ve bırakın. Sonra yakalamayı ekleyin. Riskli anı izole etmek onu küçültür ve öğrenirsiniz ki zemin, düşmanınız değil; sadece öğrendiğinizde aletin nereye gittiğini gösteren yerdir."]},"safety":{"title":"Güvenlik: alan, araçlar ve kırmızı bayraklar","summary":"Alanınızı temizleyin, affedici aletler seçin, ısınma yapın ve keskin ağrı, uyuşukluk veya baş dönmesi hissederken durun.","imageAlt":"3D figür, üstünde düz bir şekilde bir direk döndürüyor ve etrafında açık alan var","body":["Akış sanatları, çoğu sporla kıyaslandığında düşük risklidir; ancak aletleriniz daha hızlı ve beklediğinizden daha uzun mesafede hareket eder. Güvenli bir uygulama için birkaç alışkanlık sizin, yanınızdaki insanlar ve mobilyalarınız için yeterlidir.","Başlamadan önce alanı temizleyin. Kullanacağınız her düzlemi kontrol edin: önünde, yanlarda ve üstte. Direk ve halka genellikle tahmin ettikten daha fazla alan gerektirir; her yönde en az kol uzunluğu artı alet uzunluğunu kapsayan bir daire ve bu mesafede kırılabilir hiçbir şey olmamalıdır. İçi, tavan ışıkları ve fanları dikkat edin; dışarda ise düzensiz zemin ve geçiş yapan kişileri gözlemleyin.","Öğrenirken affedici aletler kullanın. Fazla kumaşlı juggling topu kaymaz. Kapatılmış veya köpük uçlu direkler başınıza vurduğunda daha az acı verir, çünkü bunu yapacaklar. Daha büyük ve ağır halkalar daha yavaş döner ve tutmak daha kolaydır. Temel teknikler otomatik hale geldiğinde daha hızlı veya daha parlak aletlere yükseltin.","Her oturumdan önce ısıtma yapın ve hacmi yavaşça artırın. Atış ve döndürme tekrarlıdır; soğuk dokuda tekrarlı yük, bilek ve kol ağrısının yaygın nedenidir. Eğer aniden çok fazla pratik eklerseniz, aynı zamanda dinlenme günleri de ekleyin.","Kırmızı bayraklar için durun: keskin veya elektrik benzeri ağrı, ellerde duyulan uyumsuzluk ya da sızıntı, devam ederken artan ağrı, baş dönmesi veya başa darbe alıp kalıcı semptomlar varsa. Yatay hareketler ve temaslı dönerler için ekstra dikkat gerekir; yumuşak bir destekle yavaşça öğrenin.","Bu uygulama teknikleri öğretir, tıbbi bakım değil. Hamilelik, yakın yaralanmalar, eklemlerle ilgili durumlar ve endişe veren her şey, yeni yük ekmeden önce yetkili bir profesyonel ile danışmanlık istenmesinin nedenidir. Ateş gösterisi, kendi güvenlik eğitimi olan ayrı bir disiplindir; SynthFlow bu konuyu öğretmez."]},"warm-up":{"title":"Neden ısınmalar araç çalışması için önemlidir","summary":"Bilek, kol, omuz ve kalça esnekliğini iki ila beş dakika ile artırın; döndürmeleri daha yumuşak hale getirir ve eklemlerinizin sağlığını korur.","imageAlt":"3D figür, kolları ileriye doğru yavaşça bilekleri çevirmekte","body":["Akış pratikleri yumuşak görünse de birkaç ekleme ciddi yükler. Juggling binlerce kez aynı atışı tekrarlar; çubuk döndürmesi bileklerin tam aralığını geçirir; halka dönmeleri her turda omurga ve kalçaları sallar. Isınmış dokular, soğuk dokulardan çok daha iyi bu tekrarı tolerans eder.","İyi bir akış için ısınma kısa ve spesifik olmalı. Her iki yönde bilek dönmeleri, en çok çalışılan eklemleri hazırlar. Kol dönmeleri ve omuz kıvırmaları, her dönüşün düzlemi kontrol eden rotator kafesi ve omuz kemiklerini uyanır. Bel dönmeleri ve gövde dönme hareketleri, halka atma için en önemlilerdir. Yüzün yukarıya bakarak oluşan gerilimi azaltmak için boyun yarım dairelerini yapın, tam döndürmeyin.","Yavaşça ve ritme uygun hareket edin. SynthFlow'daki ısınma adımları, diğer her şey gibi rahat bir tempo ile sayılır; bu nedenle oturumun ilk birkaç dakikası aynı zamanda zamanlama ayarlamasını da sağlar. Eşyalar çıkarıldığında, müzikle zaten hareket etmeye başlamış olursunuz.","Eşyanın yarım hızda bitirin. Birkaç yavaş atış, biraz hafif ön dönüş veya büyük yavaş halka döngüsü, mobilite çalışmasını yapacağınız hareketle bağlar ve vücudunuzun bugün nasıl hissettiklerini söyler.","Isınmalar aynı zamanda zihinsel geçişlerdir. Her oturum başlangıcında aynı üç dakika, uygulamanın başladığını gösteren bir işaret olur. İşli günlerde, ısınma bazen tam uygulama olabilir ve hâlâ sayılır."]},"anatomy-basics":{"title":"Aracın arkasındaki vücut","summary":"Kol kemiği sıkıştırır ve serbest bırakır, omuzlar düzlemi yönlendirir, çekirdek vücudunuzu sabit tutar: akış için basit İngilizce bir harita.","imageAlt":"3D figür, bel bölgesinde halka atarken üst gövdesini gevşetmiş durumda","body":["Jüngel yapmak için anatomiyi bilmene gerek yok, ancak basit bir harita seni neyi yoracak, neyi ısınmalı ve neyi dinlemeli konusunda anlamaya yardımcı olur. 'Öğren' bölümündeki Kaslar bölümü etkileşimli bir model sunar; bu makale kısa bir gezintidir.","Kol ön yüzü büyük ölçüde ince işleri yapar. Parmak tarafındaki kaslar parmakları kapatır ve bileği kıvılarak bükür; kol arkasındaki kaslar parmakları açar ve bileği uzatır. Yakalamak ve bırakmak, bir direğe tutunup bırakmak gibi tüm işlemler burada gerçekleşir. Uzun bir oturumdan sonra en yaygın hissedilen şey kolların yorulmasıdır ve bu nedenle gevşek kavrama çok sık bir talimdir.","Omuzlar yön verir. Deltoit kasları kolunu kaldırır; rotatör kafes, dört küçük kas, omuz ekleminin etrafında durarak üst kolun hareket ederken merkezde tutar. Omuz kemiklerinin çevresindeki kaslar tüm sistemini sabit tutar. Direk bir düzlem dışına kaydığında neden genellikle omuz değil, eldir?","Kerneler seni sessize bırakır. Jüngelde, hareketin dengesiz olmaması için gövdenin sabit kalması gerekir. Hooping'de ise karın ve sırt kasları küçük ileri-geri darbelerle halkayı itmektedir. Kalça ve bacaklar temelinizdir: yumuşak dizler hareketi emer ve ağırlığı değiştirmenizi sağlarken ekipmanı bozmadan izin verir.","Gözleriniz ve iç kulak da önemli. Jüngel, zirveleri değil elleri gözlemletmenizi öğretir; döndürme dengeyi eğitir. Kısa oturumlar ve ara vermek her ikisini de baştan başa dengede tutar. Bu harmayı okuma gibi düşünün, teşhis yapmak için değil ve ağrıları geçmeyen durumlarda profesyonel birine başvurun."]},"biomechanics-safety":{"title":"Bilekler, omuzlar ve tekrarlı yük","summary":"Gevşek kavrama, nötr bilekler ve yavaşça artan hacim ekipmanı yoracak olan eklemi mutlu tutar.","imageAlt":"Bir elin arkasında direği döndüren 3D figür","body":["Akış hasarı nadiren dramatiktir. Hemen hemen her zaman aşırı kullanım nedenidir: fazla tekrar, fazla kavrama ve az dinlenme. İyi haber ise bu hasarlardan çoğu aynı birkaç alışkanlıkla önlenir.","Kavramayı gevşetin. Jüngel topu elde kalması için yeterli bir basınca ihtiyaç duyar; direk ise parmaklarının içine kaydırmak için gevşek bir halka gerektirir. Sıkıştırmak kol kaslarını yorar ve kol bileğindeki tendonları yükler. Eğer birkaç dakika sonra parmak köşeleriniz beyazlaşıyorsa veya kollarınız yanıyorsa, gevşeyin ve ritmi düşürün.","Mümkün olduğunda bilekleri nötr tutun. Döndürme bileği büyük aralıklarla geçirir; bu, ölçülü bir şekilde iyi olur. Bileğin aralığının sonunda uzun süre tutulması veya sert bir bileği zorlayarak döndürmek onları rahatsız eder. El ve omuz hareketini paylaşın.","Omuzları çalıştırın ama hizaya gelmeyin. Büyük daireler omuz ekleminden gelir; omuzu kavuşturmak hızlıca sıkıştırır ve yorar. Helikopter ve lasso gibi üstteki hareketlerde omuzlarınızın aşağıda kalmasını aynada veya kameralı modda kontrol edin.","Hacmi zamanla artırın. Genellikle 20 dakika uygulayan birinizse, festival yaklaşırken iki saatte zorlanmayın. Haftalık olarak toplam süreyi küçük artışlarla artırın ve en az bir gün kolay bırakın. Yükü dağıtmak için aletleri değiştirin: halka çalışması, juggling'in yorduğu bileklerini dinlendirir.","Bir gün içinde geçici olan ağrı normal adaptasyondur; uzun süre devam eden, artan veya uyuşuklukla birlikte gelen ağrı değildir. Bu tür ağrılar devam ederse dinlenin, hacmi azaltın ve profesyonel danışmanlık arayın. Bu eğitimdir, tıbbi tavsiye değildir."]},"choosing-props":{"title":"İlk egzersiz aletlerinizi seçin","summary":"Juggling için bez torbaları, hafif kumaşlı bir direk ve büyük yetişkin halkası ilk haftalarda çok daha kolay olur.","imageAlt":"3D figürün bir elinde halkayı döndürüyor","body":["İyi başlangıç aletleri öğrenmeyi daha hızlı ve az stresli hale getirir. Pahalı ekipman gerekmez, ancak birkaç seçim önemli.","Koşu için başlangıçta yaklaşık 60 ila 130 gram ağırlığında üç adet fasulye çantası topu kullanın. Fasulye çantaları düşerse sıçramaz veya kaymaz, bu da pek çok takip etme durumunu azaltır. Ellerinize rahatça sığmalıdır. Daha büyük olan sahne topları ve esnek silikon toplar daha sonra kullanılır. Eşleşen renkler deseni görebilmenizi sağlar; siteswap öğrenirken üç farklı renk bireysel top takibi için yardımcı olur.","Köprü için başlangıçta genellikle 1,2 ila 1,5 metre uzunluğunda, hafif ve yumuşak ya da lastik uçlara sahip bir köprü kullanılır. Genel kılavuz olarak, ayakta durduğunda göğüs ile omzun arasında ulaşmalıdır. Daha uzun ve ağır köprüler temel teknikleri öğrendikten sonra daha yavaş ve daha düzgün döner, ancak başlangıçta zor olur ve vurduğunda daha fazla acı verir. Orta kısımda bir tutma noktası faydalıdır.","Köprü için başlangıçta düşündüğünüzden daha büyük ve ağır olanı seçin. Yetişkin bir başlangıç köprüsü genellikle zeminde durduğunda bel ile göğüs arasında uzanır. Daha büyük köprüler daha yavaş döner, bu da bel çevresinde köprü yaparken ritmi bulmanıza yardımcı olur. Küçük ve hafif köprüler, rahatlandığınızda vücudunuzdan uzaktrikleri hızlıca yapmak için uygun olur.","Seçtiğiniz her şeyde, hareketin ritminin aralığı aletle uyumlu olmalıdır. Daha ağır aletler genellikle daha düşük ritimlere uygun olur. Uygulama içindeki rahat aralık, aletinizle hızlı hissediyorsa, kendi ritminizi yapılandırıcıda ayarlayın; sayılara göre ilerlersiniz."]},"practice-at-home":{"title":"Evde ve parkta pratik yapın","summary":"Kısa günlük oturumlar, net bir alan, düşmeleri yakalayacak bir yatak veya kanepenin kenarı ve zaman bulduğunuzda parkta bir dizi.","imageAlt":"Pratik turu arasında kollarını sallayan 3D figür","body":["Çoğu akış sanatçısı evde, birkaç dakika aralıklarla öğrenir. Biraz hazırlık, evdeki pratikleri başlatmayı ve sürdürmeyi kolaylaştırır.","Yerini bul. Top atma için, yatağın veya kanepenin önünde durmak, düşen topların mobilyanın altına yuvarlanmasını değil, bel yüksekliğinde düşmesini sağlar ve aynı zamanda ileri doğru yürümeni engeller. Çubuk ve halka için, sahip olduğun en büyük boş alanı bulun, tavanı kontrol edin ve kırılabilir her şeyi uzaklaştırın. Büyük dönüşler için bahçe veya park daha iyidir.","Eşyaları görünür tut. Masada bulunan toplar, aralarındaki görüşmelerde ve çay molası sırasında atılır; kapı yanında bulunan bir halka kullanılır. Başlamak için harcanan çaba ne kadar azsa, o kadar sık yaparsınız. Beş dakikalık bir rutin sayılır ve günde birkaç kısa oturum hızla birikir.","Uygulamayı yapı olarak kullanın. Bir rutin seçin veya büyücünün bir tane önermesini sağlayın, oynatın ve çabasını kaydedin. Sıfırdan Kaskad gibi kısa programlar, her hafta için net bir hedef belirler ve bu da sizin farklı teknikler arasında kaybolmanızı önler.","Mümkün olduğunda başkalarıyla birlikte pratik yapın. Juggling kulüpleri, sirk okulları ve park akış toplulukları birçok şehirde mevcuttur. Sizden bir adım ileride olan birini izlemek, bir öğretici videonun yapamadığı bir şeyi genellikle düzeltir ve sizden bir adım geride olan birine öğretmek, kendi tekniğinizi daha net hale getirir. Eşyalarınızı getirin, insanların üzerinde çalıştıklarını sorun ve sayımın size öğrettiği şeyleri paylaşın."]},"learning-with-the-app":{"title":"3D antrenör ile öğrenin","summary":"Yavaşlatın, aynalayın, hayalet ve izleri açın, kamerayı değiştirin ve geri bildirim için kamera modunu kullanın.","imageAlt":"Bir iz gösteren bir çubuk izolasyonu yapan 3D figür","body":["SynthFlow'daki her hareket, müzikle aynı saatten hareket eden 3D animasyonla gösterilir, bu yüzden figür her zaman tam olarak ritimde olur. İyi kullanıldığında, izleyici, aynı atışı size göstermekten yorulmayan sabırlı bir öğreticidir.","Önce yavaşlatın. Her hareketin ilerleme merdiveni, yavaş ve kısmi versiyonlarla başlar, ardından el-only, ardından ritimde tam hareketle devam eder. Yarı hız, zaman ilişkilerini korurken, gözlerinize izlemek için zaman sağlar.","Öğrenmeyi daha iyi öğretmenle yüz yüze yaparsanız figürü aynalayın ve bir görünüm bir şeyi gizliyorsa kamerayı değiştirin. Yan görünüşler, çubuğun eğimini ve atış kaymasını gösterir; üst görünüşler, halka düzlemlerini ve helikopter yollarını gösterir. İzler, her eşyanın nerede olduğunu çizer ve bu da bir bulanıklığı, inceleyebileceğiniz bir şekle dönüştürür. Hayalet, eşyanın bir sonraki vuruşta nerede olacağını gösterir.","Sık yapılan hataları izleyin. Her hareket, ilerlemek, eşit olmayan yükseklikler veya acele etmek gibi tipik hatalarını gösterebilir, figürde bilinçli olarak yanlış oynanır ve bunları düzeltme ipucu ile birlikte. Modelde bir hatayı fark etmek, onu kendi vücudunuzda hissetmeyi çok daha kolaylaştırır.","Kamera modu size geri bildirim sağlar. İzin verildiğinde, pratik yaparken ellerinizi ve vücudunuzu takip eder ve zamanlamayı ritimle karşılaştırır. İşleme cihazınızda yapılır. Mükemmel değildir ve iyi ışık yardımcı olur, ancak erken veya geç olup olmadığınız hakkında kabaca geri bildirim bile değerlidir.","Son olarak, izleyiciyi bazen kapatın. Sadece müzikle pratik yapın ve sayılara güvenin. Hedef, hiçbir şey izlemeksizin yapabileceğiniz bir harekettir."]},"music-for-flow":{"title":"Uygun müziği bulmak","summary":"Ölçülü tempolar, yarım ve iki katı zaman, oluşturulan perküsyon ve kendi izlenenleriniz tüm sayılara dürüst olmayı sağlar.","imageAlt":"Göğünde halka atan 3D figür, kolları yukarıda","body":["Müzik, ritmi sayılara eşleştirirseniz egzersizi akışa dönüştürür; aksi takdirde değil. 120 BPM'lik bir rutin altında 118 BPM'de olan bir parça, bir dakika içinde ayrılmaya başlar ve müzikle mücadele etmeye başlarsınız.","SynthFlow’un dahili şarkıları ölçülmüş tempolar ve vuruşlarla gelir, böylece oyuncu her adımı müzikteki 'bir' noktasında başlatıp ritimleri eşleştirir. Oluşturucu, bir bölümün temposuna uygun olan şarkıları öncelikle listeler; bu da tempo'nun yarısı veya iki katı olan şarkılar dahil olur: 140 BPM'lik bir şarkının 70 BPM’lik bir halka adımıyla mükemmel çalışması mümkündür.","Oluşturulan perküsyon her tempo'da çalışır. Bir bölüm için bir set seçin ve oyuncu tam olarak eşleşen bir ritim oluşturur, ya da tempo merdiveni yaparken ya da yavaş bir drill yaparken. Ayrıca, melodinin dikkatini dağıtmadan sadece ritmi istiyorsanız en iyi seçenektir.","Kendi cihazınızdan şarkılar analiz edebilirsiniz. Uygulama tempo ve vuruşları tahmin eder ve bunları tıklamalarla kontrol edebilirsiniz. Düzgün elektronik veya akustik ritimlere sahip müzikler en iyi çalışır; tempo değişiklikleri, rubato ya da uzun girişler içeren müzikler ölçülebilir ve pratik edilebilir hale getirilmek daha zordur.","Sayısal uygulama sırasında video akışı kapalıdır çünkü zamanlama tam olarak kontrol edilemez. Bunun yerine, eşleşmesi gerekmeyen sıcaklık alıştırmaları veya serbest oyunlar için kullanın."]},"plateaus":{"title":"Düzler ve uzun orta","summary":"Her flow sanatçısı, hiçbir şeyin gelişmediği haftalara rastlar; hedefi değiştirmeden önce drill'ı, tempo'yı ya da aleti değiştirin.","imageAlt":"3D figür, kollarını kesişerek Mills Mess jügeleniyor","body":["Akışın başlangıcı harikadır: her oturumda yeni bir şey. Sonra, genellikle sabit bir kaskadı jugglere başladığınız veya bir halkayı sonsuza kadar yukarı tuttuğunuz zaman, ilerleme duruyormuş gibi görünür. Bu uzun orta aşama, çoğu kişinin vazgeçtiği yerdir ve en ilginç öğrenme gerçekleştiği yerdir.","Düzler genellikle bir birikimdir. Sinir sisteminiz hareketi daha az dikkat gerektirmesi için yeniden düzenler, bu da yeni numaralar olarak görünmez. Genellikle iki hafta boyunca takılı kalmış bir beceri bir sabah aniden ortaya çıkar. Düz kısmı geçerken pratik yapmaya devam edin.","Eğitimi değiştirin, hedefi değil. Eğer kaskad hızlanmıyorsa, mükemmel zirvelerle daha düşük bir tempoda pratik yapın, sonra desenin üzerinde bir noktaya odaklanarak, sonra sadece bir elinizle. Eğer bir çubuk hareketi gelmiyorsa, iki yarıya ayırın ve her birini ritimle çalıştırın. Yeni eğitimler, aynı beceri hakkında beyninize yeni bilgi sağlar.","Çapraz eğitim yapın. İkinci bir araç öğrenmek genellikle ilkini açar. Halka çalma jugglere arkasındaki ritmi geliştirir; çubuk çalışması, halka numaralarını temiz yapan düzlemleri öğretir. Her sanatın Ödül Ağacı bağımsızdır, bu yüzden çeşitlilik asla ilerlemeyi kaybetmez.","Buna karşı nazik olun. Kendinizi on yıl boyunca pratik yapan çevrimiçi sanatçılarla değil, geçen ay ile karşılaştırın. İlerleme sayfası dakikalar, en yüksek tempolar ve ezberlenmiş hareketler hakkında dürüst bir kayıt tutar. Düz bir hafta boyunca, bakın ve çizginin zaten ne kadar yükseldiğini görün."]},"history-of-juggling":{"title":"Jonglajın kısa tarihi","summary":"Mısır mezar resimlerinden ortaçağ jongleurlerine, çeşitli tiyatrolara ve modern matematiğe kadar.","imageAlt":"3D figür, bir daire içinde üç top şöveri yapıyor","body":["Jonglaj çok eski bir şeydir. En erken bilinen görüntü, Mısır'daki Beni Hasan'ın Orta Krallık mezarındaki duvar resmidir ve yaklaşık dört bin yıl öncesine dayanır; kadınların top atıp almasını göstermektedir. Çin, Yunanistan, Roma ve Pasifik'tan gelen kayıtlar ve görüntüler, birçok kültürde insanların gösteri ve oyun için atma ve alma yeteneğine ulaşmalarını işaret etmektedir.","Orta Çağ Avrupasında 'jongleur' kelimesi, günümüzdeki 'juggler' kelimesinin kökünü taşıyan, şarkı söyleyen, hikayeler anlatan, akrobatik gösteriler yapan ve nesneler atıp alan dolaşan eğlencecileri tanımlar. Jonglaj, yalnızca bir sanat değil, performansçıların ekipmanlarının bir parçasıydı.","On dokuzuncu ve erken yirminci yüzyılların çeşitli tiyatroları ve sirkleri, juggleryi başlık haberi haline getirdi. Sanatçılar uzmanlaştı: şapkaları ve bastonları olan beyefendi jugglerları, kulüp jugglerları ve yedi, sekiz ve daha fazla topa doğru ilerleyen sayı jugglerları. Enrico Rastelli, erken yirminci yüzyılda hâlâ en büyüklerinden biri olarak adlandırılır.","1970'lerden itibaren, kulüpler, festivaller ve kongreler etrafında bir hobii jugglery kültürü gelişti ve insanlar trickleri özgürce paylaştı. 1980'lerde siteswap notasyonu jugglerlere desenleri sayılarla yazma yolu sağladığı için matematik de katıldı ve yeni trickler, kimse onları atmadan önce kağıt üzerinde keşfedildi.","Bugün jugglery, sirk, spor, dans ve matematik kesişme noktasında yer alıyor. Bazı jugglerlar sayı ve dayanıklılık açısından yarışırken, diğerleri müzikle koreografi gerçekleştirirken, diğerleri kendi amaçları için desenleri keşfeder. Her yol, aynı iki topun değişimiyle başlar, bunu bu hafta öğrenebilirsiniz."]},"history-of-staff":{"title":"Çubuk döndürme: silahtan akışa","summary":"Savaş sanatları çubukları, bataon çevirme ve ateş gösterileri, modern dönen çubuğu besledi.","imageAlt":"3D figür, omuzlarının arkasında bir çubuk kelebek yaparken","body":["Bir çubuk, var olan en eski araçlardan biridir ve onu döndürmek de eski bir beceridir. Birçok savaş sanatı geleneği, uzun bir çubukla eğitim alır, bunlar arasında Okinawan bō, Çinli gun ve Avrupa çeyrek çubuk dövüşü yer alır ve bunların eğitimleri savunma ve gösteri için hızlı dönüşler ve el değişimlerini içerir.","Performans döndürme de diğer köklere sahiptir. Bataon çevirme, 20. yüzyılda rekabetçi bir disipline dönüştü ve atışlar, yuvarlanmalar ve dönmeler gibi dönenler hâlâ ödünç aldıkları şeylerdir. Tiyatro, geçit törenleri ve dünya çapındaki sokak gösterileri, akış denilmeden önce uzun süre dönen çubuklar ve direkler kullandı.","Modern akış çubuğu sahnesi, ateş gösterileri ve festival kültürüyle birlikte 20. yüzyılın sonunda gelişti. Her iki ucunda fitil bulunan ateş çubukları, dönmeyi karanlıkta görünür kıldı ve sanatı vuruşlara değil, düzgün, sürekli harekete doğru itti. LED çubuklar daha sonra aynı görselleri iç mekanlara getirdi.","Aynı zamanda, akış sanatçıları dönmeyi paylaşılan bir teoriyle tanımlamaya başladı: düzlemler, dönüş ve antiperyod, izolasyonlar, zamanlama ve yön. Bunların çoğu poi topluluğunda geliştirildi ve çubuk, halka ve diğer malzemelere taşındı, bu yüzden aynı kelimeler bu uygulamada her yerde görünüyor.","Çubuk, elde tutulmak yerine vücut üzerinde yuvarlanarak temas eder; boyun, omuz ve kollar üzerinde yuvarlanarak kendi stilini geliştirir. Bugün çubuk döndürme, dövüş gösterisinden yavaş, meditatif temas akışına kadar değişiklik gösterir ve hepsi aynı ilk çubuk dönüşü üzerinde kuruludur."]},"history-of-hoop":{"title":"Hoop: Antik oyuncaktan akış sanatına","summary":"Halkalar, milyonlarca yıldır oyuncak ve araç olmuştur; 1950'lerdeki bir moda ve festival yeniden canlandırması, halka dansını bir sanata dönüştürdü.","imageAlt":"3D figür, dönen bir halka üzerinde yürüyerek vücut boyunca yukarı çıkıyor","body":["Halkalar, en eski oyuncaklardan biridir. Antik Mısır, Yunanistan ve Roma'daki çocuklar, çubuklarla halkaları yuvarlayarak ve vücutlarının etrafında döndürerek tasvir edilmiştir; halka oyunları, o zamandan beri birçok kültürde görülmüştür.","Halka dansı, bazı geleneklerde derin kültürel anlam taşır. Birçok Kuzey Amerika yerli topluluğunda gerçekleştirilen Halka Dansı, hayvanlar ve dünya gibi şekiller oluşturmak için çok sayıda halka kullanır ve hareketlerle hikayeler anlatır. Bu, kendi başına yaşayan bir gelenektir ve modern akış sahnesinden ayrıdır; kendi uygulayıcılarından öğrenilmesi değerlidir.","1950'lerin sonlarında, Amerika Birleşik Devletleri'nde mass production ile üretilen plastik hula halkaları, bir gecede milyonlarca evde bir halka getirdi. Bundan sonraki onlarca yıl boyunca halka çoğunlukla çocuk oyuncakları ve fitness aleti olarak görüldü.","1990'ların sonundan 2000'lerin başlarına kadar, festivallerde ve çevrimiçi topluluklarda yetişkin halka döndürücüler, halkayı bir dans partneri olarak görmeye başladı. Daha büyük ve daha ağır el yapımı halkalar, yetişkinler için vücut üzerinde halka döndürmeyi kolaylaştırdı, küçük halkalar ise hızlı dış vücut hareketlerini açtı. Paylaşılan videolar, izolasyonlar, wedgies ve eskalatörler gibi sözcükleri tek bir şehir sınırlarının ötesine taşıdı.","Modern halka dansı, çubuk ve poi'den teori ve her tür müzikten ritim alır. Erişilebilir, neşeli ve derindir: bir başlangıç seviyesi oyuncu bir günde bel ritmini bulabilir ve bir uzman tek bir izolasyonu yıllarca geliştirmeyle uğraşabilir."]},"fire-and-led":{"title":"Ateş, LED ve gösteri malzemeleri","summary":"Performans aletleri ağırlık, hız ve risk açısından değişir; her hareketi önce pratik aletleriyle öğrenin ve yangını ayrı ayrı eğitimi yapın.","imageAlt":"3D figür, bir halat gibi düz bir şekilde başının üzerinde dönen bir halka etrafında dolaşıyor","body":["Gece bir yangın çubuğu veya LED halka izlemek, insanları akışa çekmenin çoğu zaman nedenidir. Performans aletleri harikadır, ancak pratik aletlerle aynı değildir ve onlara geçiş bir plan gerektirir.","LED prop'lar, pil ve elektronik nedeniyle genellikle pratik versiyonlarına göre daha ağırdır. Bu, momentumu değiştirir: dönüşler daha uzun sürer, atışlar farklı hissedilir ve bilekler daha çok çalışır. Her hareketi önce pratik prop ile öğrenin, ardından LED'de kısa bir ayar süreci bekleyin. İlk seanslarda tempoyu düşürün.","Ateş gösterisi ayrı bir disiplindir. Yakıt işleme, güvenli dönüş alanları, yangın örtüleriyle birlikte güvenlik gözlemcileri, uygun giysiler ve yerel kurallar hepsi önemlidir ve hepsi deneyimli ateş göstericilerinden kişisel olarak öğrenilir. SynthFlow ateş gösterisi öğretmez ve uygulamadaki hiçbir şey yakılmış prop'larla uygulanmamalıdır.","Birçok akış topluluğunda kullanılan iyi bir kural, bir hareketi performans prop'larıyla sadece pratik prop ile güvenilir bir şekilde, ardı ardına birçok kez yapabildiğinizde yapmaktır. Işıklar altında veya alevler içinde deneme odaklanmak için yer yoktur.","Performans ayrıca sıralamayı da değiştirir. Seyirciler büyük düzlemleri, temiz geçişleri ve net durma anlarını okur. Performans rutinlerini diğerlerine benzer şekilde oluşturucuda oluşturun, önizleyin ve her seferinde aynı müziğe göre prova yapın, böylece sayım koreografi haline gelir."]},"cap-notation":{"title":"Speed ratios and CAP-style notation","summary":"Read hand:head speed ratios and the Θ1 Θ2 ; ρ1 ρ2 shorthand used in community CAP papers — without confusing speed ratio with assembly CAPs.","imageAlt":"3D figure drawing a four-petal antispin flower with poi","body":["Spinners share two related languages that are easy to mix up. The first is a simple speed ratio: how many times the prop head turns for each hand circle. Plain forward spin is 1:1. A three-petal antispin flower is often 1:2, a four-petal flower is 1:3, and a six-petal flower is 1:5. SynthFlow’s Timing lab and viewer chip show this as a speed ratio so you can compare flowers without memorising petal counts alone.","The second language comes from community papers on Continuous Assembly Patterns. A pattern is written as two harmonic turns and two length moduli: Theta1 Theta2 ; Rho1 Rho2. Theta1 is usually the arm’s turn rate; Theta2 is the relative turn of the head. Rho1 and Rho2 are relative lengths of the arm path and the tether path. When the two lengths match, Rho1 equals Rho2, and the curve is a rosette — the familiar even flower. When the lengths are tuned so tip and hand appear to move at the same audience speed, the curve is a cycloid. SynthFlow shows a derived readout such as 1 −3 ; 1 1 for four-petal antispin; it does not yet let you free-edit Rho while keeping petal math intact.","Hybrid and assembly CAP are different ideas that both use the word CAP in older writing. A hybrid here means two hands running different elementary patterns in parallel — for example one hand isolating while the other extends (a cateye). An assembly CAP means chaining elementary patterns in series on one prop into one longer cycle. SynthFlow’s catalog already ships many parallel hybrids; serial assembly remains a future explorer. Quizzes ask you to tell those ideas apart so the vocabulary stays sharp.","Use the Timing lab Notation panel while you change speed-ratio presets. Watch the Θ2 sign flip for antispin, stay positive for inspin, and land on 1 1 for plain spin. Link that picture to the Transition Theory map: the same flower can sit in together-same or split-same, and legal hops still follow shared cardinals. For deeper reading, community HTML references are linked from Credits and from the Timing page footer — SynthFlow ships original coaching copy offline and does not bundle third-party PDFs.","Practice tip: pick one speed ratio for a whole practice block. Name it out loud on the downbeat — “one to three” — before you change petals. When the ratio is stable, change timing or direction instead. That separation of concerns is what makes the four-cell map and the flower language work together instead of fighting in your head."]},"spinning-geometry":{"title":"Spinning geometry: symmetry to timing and direction","summary":"Choose a symmetry — central point, vertical axis, or horizontal axis — and land on the matching timing and direction cell.","imageAlt":"3D figure in a poi butterfly, opposite direction same time","body":["One way to invent poi patterns is to start from geometry instead of from move names. Pick a shape that has a clear symmetry, then ask which rotation of the hands respects that symmetry. Community writing (often summarised as a “symmetry method”) maps three everyday symmetries onto the same Timing and Direction grid SynthFlow already uses.","Central-point symmetry means the pattern looks the same if you rotate it around a centre in the plane. That configuration lands on same direction with split time — the split-same cell, the foundation under weaves and chase patterns. Vertical-axis symmetry mirrors left and right across a vertical line through the body; that wants opposite direction with same (together) time — the butterfly family. Horizontal-axis symmetry mirrors across a waist-high line and wants opposite direction with split time — the remaining opposite corner of the map.","Together-same, the first wall spin many people learn, is not forced by those three symmetries alone. It still matters as a neighbour on the transition map: you can hop into it from together-opposite at the top or bottom, or from split-same at the sides. Thinking in symmetries does not replace Transition Theory; it gives you a reason to visit three of the four cells on purpose.","Open Learn → Timing → Symmetry and tap each symmetry while watching the coach. Hide one prop if the picture is busy. Then take the built-in poi-symmetry-lab routine and visit vertical, central, and horizontal cells with catalog moves you already own. The quiz bank asks both directions: given a clip, name the symmetry; given a symmetry label, recognise the timing and direction.","When you improvise, try one constraint per phrase: “this phrase is vertical-axis only.” Stay in together-opposite until the phrase ends, then hop legally into a neighbour. Geometry becomes a compositional tool instead of a trivia fact, and your transitions stay clean because you already know which cardinals you share with the next cell."]},"hybrid-math":{"title":"Hybrid drivers: spin, isolation, extension, cateye","summary":"Treat each hand as a driver on a unit circle where poi length matches an isolation diameter, then mix same and split timing.","imageAlt":"3D figure performing a poi cateye hybrid","body":["A hybrid in this sense is two hands doing different elementary jobs at once. One hand may spin while the other isolates; one may extend while the other draws a cateye almond; both may isolate in split time. Community hybrid maths treat those jobs as drivers on a shared configuration space. A useful picture is a unit circle where the poi length is about the diameter of an isolation — the hand path of a cateye or extension variant sits on that scale so the two shapes can nest cleanly.","SynthFlow already encodes many of these pairs. Petal tuples such as [4, 0] mean the right hand draws a four-petal antispin while the left keeps plain spin. Extension flags and isolation petals build cateyes and iso–spin pairs. Plane hybrids swap wall, wheel and floor mid-cycle. The Hybrids tab in the Timing lab lays a small grid of timing (same or split) against drivers (spin, isolation, extension, cateye) so you can see the live coach without hunting the catalog first.","Hide one prop when the pattern is asymmetric. Your eyes need a clean read of each driver’s path before you put both back. Count slowly. Name the right hand’s job on the odd beats and the left hand’s job on the even beats until the labels stick. Then restore both props and keep the same names — the hybrid is still two simple patterns, not one mysterious blob.","Quizzes ask which hand is isolating versus spinning, and whether the timing is same or split. The poi-hybrid-session routine and the progression week after antispin start give you a practice path that stays offline. For plane-change hybrids such as wall-to-wheel, remember the switch wants a shared line between planes; for driver hybrids, the switch is about roles, not planes.","Keep vocabulary honest: parallel hybrids are not the same as serial assembly CAPs. If you are chaining stalls into flowers on one hand over time, that is assembly thinking. If both hands run different drivers in the same cycle, that is hybrid thinking. The glossary entries for hybrid, assembly CAP, and speed ratio keep those three ideas separated so coaching cues stay short."]},"degrees-and-weaves":{"title":"Degree of twist and weave counts","summary":"Count weaves in beats or in degree-of-twist labels such as −1_0_+1 for three-beat and −2…+2 for five-beat patterns.","imageAlt":"3D figure in a three-beat poi weave","body":["Weaves sit on split timing: one poi is high when the other is low, and the planes trade sides of the body. The classic three-beat weave crosses after three beats of that split foundation; the two-beat weave crosses faster; the five-beat weave stays longer on each side. SynthFlow already ships these as catalog moves. Degree-of-twist language adds another counting layer without changing how long a beat is.","In that language a three-beat phrase can be written with labels that step through minus one, zero, and plus one — compactly −1_0_+1. A five-beat phrase stretches to −2_-1_0_+1_+2. The signs describe facing and twist relative to the body line: facing inside versus facing outside, outswing versus inswing. Advanced inversions and introversions belong in the glossary as future vocabulary; this pass does not add new inversion generators to the catalog.","In Settings → Timing you can choose weave count style: beats (the default spoken one–two–three) or degrees (the pattern index spoken while the degree labels are what the theory names). The beat clock length does not change — only the cue mapping. Use degrees when you are studying notation; use beats when you are linking to music phrases.","Practice the poi-weave-degrees routine after you own the three-beat weave. Add the five-beat week on the weave ladder progression when the longer side stays clean. On the Timing lab, remember that weaves live in the split-same neighbourhood of the map; legal hops out of a weave still want shared cardinals, just like any other split-same pattern.","Quiz items ask you to match a notation string or a weave clip to two-beat, three-beat or five-beat families. Say the degree string once before you spin, then spin without talking. When the string and the body agree, you can improvise crossings without losing the split foundation underneath."]},"staff-vtg":{"title":"Staff theory: two ends, timing and direction","summary":"How Vulcan Tech Gospel timing and direction apply when both ends of a staff are visible, plus snapshots and speed ratios.","imageAlt":"3D figure drawing a four-petal antispin flower with a staff","body":["Siteswap gives jugglers digits for throws. Staff spinners share a different language with poi and clubs: timing and direction. Timing asks whether the two ends (or two hands on double staff) reach matching places in the circle together or half a turn apart. Direction asks whether they turn the same way or opposite ways. Those four relationships — together-same, together-opposite, split-same, split-opposite — are the backbone of community spin theory often summarised as Vulcan Tech Gospel.","A staff shows both ends at once. When you isolate the centre, one end extends while the other draws the complementary path. Clubs show only one end, so isolation and extension feel like separate moves even when the underlying geometry is the same. In the Timing lab, switch the prop to staff and watch both tips leave trails; that picture is the snapshot idea — a still of arms and props across an axis that you can compare between patterns.","Speed ratios sit on top of the map. Plain spin is 1:1. Four-petal antispin is a 1:3 relationship; six-petal is 1:5. SynthFlow’s lab presets flip those ratios while the beat clock stays steady. Legal transitions still hop only between cells that share a cardinal — top, bottom, or the sides — just as in the poi Timing map.","Double staff borrows the same four cells with one short staff in each hand. Same-time wheels and split-time wheels are addresses on that map, not separate mysteries. Choreography systems such as The Kinetic Alphabet write sequences as pictographs on this geometry; SynthFlow links out for that sheet-music layer and does not ship letter charts.","Open Learn → Timing, choose staff, and drill the quiz in staff mode. Then take a flower or symmetry routine from the catalog. Name the cell out loud before you change petals. When the map and the ends agree, improvisation stops feeling like a list of trick names and starts feeling like travel between addresses."]},"contact-staff-map":{"title":"Contact staff: rolls, wraps and open hands","summary":"A map of contact classes — fishtail, rolls, angel, palm — by body point and plane, without inventing a siteswap for contact.","imageAlt":"3D figure performing a staff fishtail on the open hand","body":["Contact staff means the prop travels across skin and clothing instead of living in a tight grip. There is no community-wide digit system like siteswap for contact. What teachers share is a taxonomy: what kind of contact (roll, wrap, stall, fishtail), where on the body it happens, and which plane the staff sits in while it travels.","Fishtails keep the staff pivoting on an open hand or wrist while the ends draw linked circles front and back. Hand rolls and forearm rolls send the staff across a surface without a catch in the middle. Angel rolls carry that idea across the upper back from arm to arm. Palm spins and steering-wheel turns keep contact but stay more held. Neck and shoulder rolls need padding and clear space — learn them slowly with a soft staff.","Entries and exits matter as much as the middle. Many contact phrases start from a held spin, open the hand at a known beat, ride the roll, then catch again. SynthFlow’s contact explorer lets you preview catalog contacts by class and plane offline so you can see the family before you drill. The quiz asks you to name the family from a short clip.","Treat contact as a second language beside tech spinning. Timing and direction still describe held patterns; contact adds body points and roll direction. Do not force one notation to cover both. Community research notes and forum taxonomies are linked from Credits for operators; the app ships original coaching copy only.","Practice tip: pick one contact class for a week. Fishtail until both hands feel even, then add a hand roll on the same plane. Use the staff-contact-session routine after foundations. Stop when the staff chatters or your wrists tighten — contact rewards soft hands more than ambition."]},"hoop-on-off-body":{"title":"Hoop map: on-body, off-body and planes","summary":"Hoop has no siteswap. Learn the teaching map — on-body versus off-body, horizontal versus vertical planes, and the transitions between them.","imageAlt":"3D figure waist hooping with a relaxed upper body","body":["Juggling has siteswap. Staff and poi share timing and direction. Hoop dance’s closest “theory” is a map, not a digit string. The first axis is on-body versus off-body: is the hoop riding a body zone (waist, chest, knees) or spinning in the hands away from the torso? The second axis is plane: horizontal work parallel to the floor (lasso, vortex, waist orbits) versus vertical work in the wall or wheel plane (weaves, hand spins, many isolations).","Most beginner curricula walk that map on purpose. Waist hooping both ways, then hips and chest, builds on-body rhythm. Off-body vertical weaves and hand spins free the torso. Horizontal tricks above the head open a second plane. Transitions such as escalators, spirals and hinges are the roads between cells — not decorations.","SynthFlow’s Hoop lab lays those axes over live catalog moves. Pick on-body or off-body, pick a plane, pick a family, and watch the coach. Quizzes ask you to classify a clip. Routines such as hoop-plane-lab force you to visit more than one cell in a session so the map sticks in your body as well as your head.","Unit-circle thinking from spinning props still helps. A hoop cateye nests isolation and extension-like paths so the rim draws an almond; the same isolation diameter idea appears in poi hybrids. You do not need equations to use the picture — keep the hoop’s path size matched when you combine floating isolations with open extensions.","Further reading lives on community curriculum sites linked from Credits. SynthFlow does not ship paid course video. Use the lab offline, then take one transition — waist to escalator, or weave to lasso — and repeat it until the change feels boring. Boring transitions are the ones you can dance with."]},"hoop-isolations-and-breaks":{"title":"Hoop isolations and breaks","summary":"Isolations make the hoop look frozen or floating; breaks intentionally interrupt spin to change direction or plane.","imageAlt":"3D figure holding a hoop isolation in the wall plane","body":["An isolation is the illusion that one point of the hoop stays still in space while the rest of the rim turns. Linear isolations slide that freeze point along a line; circular or centred isolations keep the float in one place. Cateyes close the rim toward the audience so the hoop reads as a narrow almond before it opens again. Ghosting traces with the free hand to sell the float.","A break is different. Instead of keeping continuous spin, you interrupt the hoop’s path — a paddle, a pinch, a shoulder break — so direction, plane or body zone can change. Off-body breaks train timing with the hands first; on-body breaks ask the core and shoulders to catch the same idea. Reversals flip the spin direction without dropping the phrase.","In SynthFlow, isolation and cateye modes already exist on the hoop generator. The Hoop lab groups them under the isolation family next to body spins, weaves, escalators and passes. Quizzes ask isolation-versus-spin and family identification. The hoop-isolation-session routine drills float before you stack breaks.","Keep cues short. For isolations: “freeze the far point, walk the hands.” For breaks: “stop the circle on purpose, then choose the next plane.” Tempo should drop when you first learn either skill; momentum hides mistakes until the hoop falls behind the beat.","Link isolations to the shared geometry article trail — hoop cateye and poi/staff isolation diameter are cousins. Link breaks to sequencing: a break is a punctuation mark in a counted phrase. Once both feel clean, on–off-body transitions stop being scary because you already own the ways to interrupt and restart the hoop’s story."]}}`),r=JSON.parse(`{"the-day-the-cascade-clicked":{"title":"Kaskadın tıklandığı gün","summary":"Zeminde topu kovalamakla geçen üç hafta, ellerime bakmayı bırakıp saymaya başladığım anda sona erdi.","body":["Üç hafta boyunca üç topum cascade tam olarak dört atış sürebildi. Sağ, sol, sağ ve sonra üçüncü top kanepenin arkasında bir yerdeydi. Videolar izledim, yavaşladım, hızlandım. Her dersin söylediği gibi yatağın önünde durdum. Değişen tek şey, kelimelerim oldu.","Çözüm, geldiğinde utanç verici derecede basitti. 90 BPM'lik bir parça çalmaya başladım ve sayımı seslendirdim: bir, iki, üç, dört, her vuruşta bir atış. Aniden atışların gidecek bir yeri oldu. Elin hazır hissettiği zaman atmak yerine, panik ona ne zaman atması gerektiğini söyleyince, her atış ritmine göre bekledi. Desen daha yavaş, daha yüksek ve daha sakin hale geldi.","İkinci çözüm, nereye baktığım konusuydu. Ellerime bakıyordum, bu da bir kitap okumak için kirpiklerinizi izlemek gibi. Gözlerimi tepe noktalarına kaldırdığımda, yani yörüngelerin en üstündeki iki noktaya, ellerim kendi kendine yakalamaya başladı. Tepe noktaları atışların eşit olup olmadığını bana söylüyordu; ellerin gözetimine gerek kalmıyordu.","On iki atış, yirmiye, sonra elliye çıktı. Bir akşam, bir tam sekiz barlık adım boyunca hiç düşürmeden yuvarlak yuvarlak yuvarladım ve tavanı aptal gibi gülümseyerek baktım. Uygulama buna temiz bir koşu dedi. Ben buna ilk kez yuvarlamanın bir kavga yerine müzik gibi hissettirdiği an dedim.","Dört atışta卡rak duruyorsan, benim işe yaradığı gibi deneyin: sesli say, ritme göre atış yap, zirveleri gözlemle. Ve dram olmadan düşür. Zemin, her cascade'nın başlangıcıdır."]},"why-we-count-in-bars":{"title":"Neden saniye değil, bar sayıyoruz","summary":"Bir uzatma için 40 saniyelik tutma mantıklı olur; bir juggling deseni bir ritme dayanır, bu yüzden pratikleri çeyreklerle ölçeriz.","body":["SynthFlow'u inşa ederken ilk büyük kararımız, bir rutin adımı nasıl ölçüleceğiydi. Kız kardeşimizin SynthYoga uygulaması tutmaları saniyeler ve nefesler cinsinden ölçer. Bir pozisyon için çalışır. Ancak bir ritme dayalı tekrarlayan desen için çalışmaz.","Bir juggling atışı, bir çubuk yarım dönüşü ve bir halka döngüsü hepsi döngülerdir. Eğer müzik 100 BPM'de çalışıyorsa ve cascade'niz 103'tür, müzikle juggling yapıyorsunuz değil; ona yakın juggling yapıyorsunuz, ve dakika içinde bir ritim geride kalırsınız. Ritmik ölçümlerle adımları ölçmek, müzik, sayım, 3D figür ve sonraki adımın hepsi aynı inme vuruşunda başlamasını sağlar.","Bars ayrıca ilerlemeyi somutlaştırır. 'Bir dakika juggling yap' ifadesi belirsizdir: ne kadar, hangi hızda? '96 BPM'de sekiz çeyrek cascade' ise belirli ve tekrarlanabilir bir zorluktur. Eğer temizce başarısınıza sahipseniz, sonraki oturum 104 isteyecek. Bu tempo merdivenlerinin nasıl çalıştığıdır ve neden uygulamada ustalık temiz atışlarla değil sadece zamana bağlıdır.","Bu, ciddi mühendislik gerektirdi. Her animasyon müzikle aynı ses saatine dayanır ve önceden planlanmıştır ki hiçbir şey tutulmaz. Paketlenmiş takımlar ölçülmüş tempo ve inme vuruşları içerir. Oluşturulan perküsyon, seçtiğiniz her tempo için doldurulur. Cihazınızdan gelen takımlar bir tıklama testiyle analiz edilip kontrol edilir. Sayılan pratikte akış videoyu kapatırız çünkü ritme tutamayız.","Sonuç olarak, ritim bir öğretmen haline gelir. Kaybolursanız onu duyarsınız. Tutuşursanız onu hissersiniz. Çeyreklerle saymak, yaptığımız en önemli tasarım kararlarından biri oldu."]},"staff-hit-me-in-the-head":{"title":"Çubuk başıma vurdu (ve diğer dersler)","summary":"Her çubuk döneri başta kafasına vurulur; yastık, düzlem ve sabır, vuruşları ilerleme haline getirir.","body":["İlk figür-8'im, çubuğun kafama sıçradığı ve köpeğin odadan çıktığı sona erdi. İkinci de aynı şekilde bitti, köpek olmadan. Eğer çubuk öğreniyorsanız vurulacaksınız. Sorun ne kadar şiddetli olacak ve bunlardan ne öğreneceksiniz.","Ders bir: yastık, korku değil. Yumuşak uçlu bir pratik çubuğu, vuruşları fısıltılardan gülümsemelere dönüştürdü. Gülümseme önemli çünkü korku sizi kıvırmaya zorlar ve kıvrılan bilek, çubuğu düzlemden çıkarır ki bu da sonraki vuruşa neden olur.","Ders 2: çoğu darbe eğik düzlemlerden gelir. Yanından çektiğimde, her dönüşün tepesinde çubuğun yüzüme doğru yanaştığını görüyordum. Kollarım içe dönüyorlardı. 3B görüntüleyicideki düzlem örtüsü, temiz versiyonu gösteriyordu: vücudun yanında düz bir planda olan çubuk, hiçbir zaman eğilmiyor ve darbeleri düzeltir.","Ders 3: yavaş ve sayılan ritim hızlı ve umut verici olur. Şeklin alt sınırına tempo düşürdüm ve müzikle “sağ taraf, sol taraf” diye saydım. Bu hızda elin değişmesini hissedebilir ve düzlemi koruyabilirim. Bir hafta sonra tekrar yukarı çıkabilirdim.","Ders 4: gülmeye çalış. Çubuk döndürmek, aptalca ve harika bir şeydir. Darbeler, sahnedeki herkesin paylaştığı hikayenin parçasıdır. Gerekirse şapka tak, tavan ışıklarını kaldır ve devam et."]},"hooping-for-people-who-cant-hoop":{"title":"Çember çevemeyenler için çember","summary":"‘Hoop yapamıyorum’ diyen çoğu yetişkin, çocuk oyuncak boyutunda bir halka verilmiştir; daha büyük bir halka ve ileri-geri pulsasyon, bu sorunu çoğunlukla çözer.","body":["'Hoop yapamıyorum' ifadesini, genellikle çocuk oyuncak halkasıyla son kez deneşen biri tarafından sürekli duyulan bir şeydir. Küçük ve hafif halkalar hızlıca döner ve düşerler. Hızlı ve panikli kalçalara ihtiyaç duyarlar. Yetişkin boyutunda bir halka kullanan yetişkinler genellikle bunu çok daha kolay bulurlar.","Büyük başla. Zeminde durduğunda belin ve göğüsleriniz arasında olacak şekilde bir halka, yavaşça döndüğünde ritmi hissedebilirsiniz. Daha ağır halkalar daha fazla momentum taşır. Sonradan hız ve vücut dışı hareketler için daha küçük boyutlarda geçebilirsiniz.","İmpuls ver, döngü yapma. En yaygın hata, belde büyük daireler çizerken hipleri kullanmaktır. Bel halkası genellikle küçük ileri-geri sallanma veya yan yana hareketdir ve halka ile aynı ritimde olur. Bir ayak hafifçe öne doğru olur. Halka önünüze ve arkasınıza dokunur; döndüğünde hafifçe itersiniz.","Say, ritmi hisset. Rahat bir tempo, her vuruşta bir tur, vücudunuza uyum sağlar. Uygulama bel halkasını yavaşça başlatır ve sonra yükselmeye izin verir. Halka düşerse, pulsunuzda hafifçe hız ekleyin, daha büyük hareket yapmayın.","Birkaç oturum boyunca çok fazla düşecektir, sonra ani olarak düşmeyecek. Halka, bir beceri türüdür ve zamanla anlamlı hale gelir. Bir kez anlamsal hale geldikten sonra, vücut içi ve dışı akışlarla dolu bir dünya açılır ve bu akışların çoğu bel kullanmadan da olur."]},"unlocking-is-not-a-race":{"title":"Kilidi açmak bir yarış değil","summary":"Ödüller ağacı, temellerinizi pekiştirdikçe daha zor hareketleri açar; ama hedef, temellerdir.","body":["SynthFlow'un ödülleri hareketlerdir. Kasırgayı ve ters kasırgayı ustalaşın; ön dönüşü ustalaşın ve sekiz şekli ortaya çıkar. Ağacın ışıklandığını görmek tatmin edicidir ve biz bunu böyle tasarladık. Ancak her kilitleme sisteminde bir tuzağa düşmek mümkündür ve bunu adlandırmak değerlidir.","Tuzağın ustalık, bir kutuyu işaretlemek olarak görülmesidir. İyi bir gün içinde bir hareketin temiz çalışmasını teknik olarak kaydedebilir, bir sonrakini kilitlemeyi açabilir ve sadece her şeyin doğru gittiği zaman işleyen bir temele sahip olarak ilerleyebilirsiniz. Daha zor hareketler, temelin yanlış gittiğinde çalıştığını varsaydığı için imkânsız gibi hissettirir.","Akış içinde ustalık, dikkat dağılması durumunda hareketin hayatta kalması demektir: biraz yorgunluk, farklı bir tempoda, birinin yanından geçmesi. Bu yüzden ustalık, tek bir oturumda değil, oturumlar boyunca temiz çalışmalara ihtiyaç duyar. Ve bu yüzden, ustalaşmış hareketlere düzenli olarak geri dönmeyi öneriyoruz. Kasırga, bitirdiğiniz bir seviye değil; tüm jugglingle ağacının üzerinde durduğu zemin.","Kilitleme altındaki hareketler hâlâ sayfalarına sahiptir. Bunlar hakkında okuyabilir, 3D'de izleyebilir ve neye ihtiyaç duyduklarını görebilirsiniz. İleriye bakmak motive edicidir. Ancak temeller olmadan ileriye doğru pratik yapmak çoğunlukla hayal kırıklığına neden olur.","Bu yüzden kilitlemelerin tadını çıkarın, ancak kendinizi en eski hareketlerinizin ne kadar kolay hissettirdiğine göre ölçün. Kasırga sıkıcı olduğunda, Mills Mess'e hazırsınız. Mills Mess sıkıcı olduğunda, ağacın daha fazlası sunuyor."]},"practice-in-ten-minutes":{"title":"On dakikada gerçek bir uygulama","summary":"Sıcaklaştırma, bir odak hareketi, bir bağlantı, kısa bir tempolu tırmanış ve soğuma: her gün on dakika.","body":["İnsanların pratik yapmamalarının en yaygın nedeni zaman. Gerçek şu ki, akış becerileri kısa ve sık oturumlara harika tepki verir. İşte kendimiz kullandığımız on dakikalık yapı.","Birinci ila ikinci dakika: Sıcaklaştırma. Bilek döndürmeleri, kol döndürmeleri, omuz yuvarlamaları, eğer halka kullanıyorsanız birkaç kalça döndürmesi. Rahat bir tempoda sayılır, böylece zamanlamanız eklemlerinizle birlikte uyanır.","Üçüncü ila beşinci dakika: Odak hareketiniz. Çalıştığınız bir hareket, temiz bir tempoda yapabileceğiniz bir hareket. Uzun bir adım yerine birkaç kısa sayım adımı, aralarında bir nefesle.","Altıncı ila yedinci dakika: bir bağlantı. Odak hareketini içine veya dışına akış yapan bir şeyle eşleştirin. Kasırga'dan ters kasırgaya. Ön dönüşten sekiz şekline. Belden göğse. Bağlantılar, pratikin drills yerine akış gibi hissettirmesini sağlar.","Sekizinci ila dokuzuncu dakika: küçük bir tempolu tırmanış. İki veya üç basamak, her biri birkaç BPM, form bozulmadan önce dur. Temiz bir basamakta bitirin.","Onuncu dakika: Soğuma. Yavaş, kolay bir hareket veya kısa bir dinlenme. Çabukluğunuzu kaydedin. Bitti.","Günde on dakika, koordinasyonun en çok sevdiği şekilde dağılmış, haftada bir saatten fazla odaklı pratik anlamına gelir. Pratik sihirbazı, zamanınızın az olduğunu söylediğinizde bu büyüklükte oturumlar oluşturur ve yerleşik kısa rutinler aynı şekli takip eder."]},"antispin-broke-my-brain":{"title":"Antispin beynimi bir hafta boyunca kırdı","summary":"Çubuğu elin çemberine karşı döndürmek, sayım her petale bir vuruş verene kadar imkânsız gibi gelir.","body":["Antispin, çubuk döndürmenin geometri ödevi gibi hissettirmeye başladığı yerdir. Eliniz bir yöne doğru bir çember çizerken, çubuk diğer yöne döner ve uçlar bir çiçek çizer. İlk denediğimde, solmuş bir papatya gibi bir şey elde etmiştim.","Yardımcı olan şey şekli sayılabilir hale getirmekti. Dört petallı bir antispin, bir uç çemberden doğrudan dışarı baktığı dört noktaya sahiptir. Her birine bir vuruş verdim: üst, yan, alt, yan. Sonra müziği normal döndürme hızımın çok altına düşürdüm ve sadece vuruşlarda pozisyonlara hedef aldım.","3D görüntüleyicideki hayalet, bir sonraki vuruşta çubuğun nerede olması gerektiğini gösterir, o hafta benim en iyi arkadaşım oldu. Aynı şekilde, iz, çiçeğimi çizdiği için petallerin eşit olup olmadığını görebildiğim iz de öyleydi. Genellikle alttaki petal ezilmişti çünkü çemberin altını acele ediyordum.","Yaklaşık bir hafta sonra, bir şey değişti. El ile çubuğu iki ayrı şey olarak düşünmeyi bıraktım ve çiçeği tek bir şekil olarak hissetmeye başladım. Tempo kendi kendine geri geldi.","Eğer antispin beyninizi kırıyorsa, bu olması gerekiyor. Her petale bir vuruş verin, müziği yavaşlatın ve vücudunuzun bunu çözmesine izin verin. Bu gerçekleştiğinde akış içindeki en iyi hislerden biridir."]},"siteswaps-for-the-maths-shy":{"title":"Matematikten korkanlar için Siteswaps","summary":"Siteswap kullanmak için matematikten hoşlanmanıza gerek yok; sadece büyük sayıların daha yükseğe gittiğini bilmek yeterli.","body":["Siteswap notasyonu insanların korkutmasıyla bilinir. Zıplayanlar, sanki bir şeyi açıklıyormuş gibi keyifle '531 deneyin' derler. Gerçekten de öyle, ama bunu anlamak için birkaç şeyi bilmeniz gerekir ve bu şeyler göründüğünden daha basittir.","İhtiyacınız olan neredeyse her şey burada. Her sayı bir atıştır. Büyük sayılar daha yükseğe gider. Tek sayılar diğer elin karşısına geçer; çift sayılar aynı elin geri gelir. 3 normal bir kaskad atışıdır. 1 hızlı bir geçişdir. 2 genellikle topu tutmaktır.","Bu 441'i okumak için yeterlidir: iki tane daha yüksek atış, kendi tarafında kalır, sonra bir geçiş. Artık başka bir kelime okumadan deneyebilirsiniz. At, at, geçiş, vuruşta.","Bir tane daha istiyorsan: sayıları topla ve kaç tane olduğunu böl, elde edeceğin sayı toplam top sayısı olur. 4 + 4 + 1 = 9, 3'e bölünce 3 top olur. Eğer sonuç tam sayı değilse, bu desen juggled edilemez. Bu ünlü ortalama teoreminin tamamıdır.","SynthFlow'da her jugglingle hareketin bir siteswap'i vardır ve 3D motor doğrudan ondan animasyon yapar. Bu, figürün her zaman sayıların tanımladığı yükseklikte ve tam olarak ritimde atışlar yapması anlamına gelir. Bir siteswap'in yavaşça animasyonunu izlemek, sayıların anlamlı gelmesini sağlamanın bildiğimiz en hızlı yoludur. Matematik lisansı gerekmez."]},"music-that-fights-you":{"title":"Müzik sana karşı olduğunda","summary":"Sayılarla karşı drifting bir parça her hareketi daha zor kılar; ölçülmüş tempolar ve oluşturulan vuruşlar bunu düzelir.","body":["Muhtemelen hissetmişsinizdir: sevdiğiniz bir şarkı, bildiğiniz bir hareket ve her şey yanlış hissettiriyor. Acele ediyorsunuz, düşürüyorsunuz, kendinizi suçluyorsunuz. Genellikle sorun sizde değil. Sorun, şarkının temposunun harekete uymamasıdır.","Her akış hareketinin rahat bir tempo aralığı vardır. Altında, dönen ekipmanlar durur; üstünde, atışlar düşük ve panikli olur. 128 BPM'lik bir parça, 90'da sevişen bir halka hareketinin altında, müzikle halka arasında seçim yapmanızı ister. İyi haber şu ki, yarım tempo ve çift tempo yardımcı olur: 128, her iki ritimde bir döngüyle 64'te bir hareketi taşıyabilir.","Drift daha ince bir sorundur. Eğer müzik 120 diyor ama sayım 116 diyor, ikisi bir dakika içinde birbirinden uzaklaşır ve vücudunuz her ikisini de takip edemez. Bu yüzden SynthFlow, paketlenmiş parçaları için ölçülmüş tempolar kullanır, herhangi bir tam tempoda perküsyon üretir ve cihazınızdan gelen parçaları bir dokunma testiyle kontrol eder.","Bir parça size karşı olduğunda, karşılık vermemelisiniz. Adım için oluşturulan vuruşa geçin veya yapımcının doğru aralıktaki bir parça önermesine izin verin. Sevdiğiniz parçaları, hiçbir şeyin eşleşmesi gerekmeyen serbest oyunlar için tutun.","Müzik bir ortak gibi hissetmeli. Eğer bir rakip gibi hissediyorsa, hareketinizi değil, müziği değiştirin."]},"learning-alongside-my-kid":{"title":"Çocuğumla birlikte jugglaj öğrenmek","summary":"İki yeni başlayan, bir çanta toplar ve bir kural: düşürmeleri yakalamalar kadar coşkuyla kutlarız.","body":["Kızım jugglingle öğrenmek istedi ve fark ettim ki ben de jugglingle yapamıyordum. Bu yüzden birlikte öğrendik, akşam yemeğinden on dakika sonra, her birimiz üç fasulye çantasıyla ve bir kural ile: düşürmeleri yakalamalar kadar coşkuyla alkışlıyoruz.","Kural saçma geliyor. Ama en önemli kısım olduğu ortaya çıktı. Çocuklar ve yetişkinler bir hatanın utanç verici olduğunu düşündüklerinde gerginleşirler. Gerginlik atışları daha kötü hale getirir. Her düşüşü alkışlamak, zemini oyunun bir parçası haline getirdi ve ikimizi de gevşek tuttu.","Bir top ile başladık, topu elden ele, ritimle, göz seviyesinde zirvelere fırlatarak. Yaklaşık üç seans boyunca çok kolay hissetti ve sonra birden önemli hale geldi, çünkü iki top değişimi tek atışların tutarlı olmasıyla işliyor. O benimkinden önce değişimi anladı ve bundan dolayı dayanılmaz oldu.","Sayılı müzik, birlikte pratik yapmamıza yardımcı oldu. Aynı tempoda, aynı vuruşta, iki kişi ritimle atış yapıyor. Birimiz deseni kaybedince, diğeri devam ediyor ve atmayı kaçıran bir sonraki \\"bir\\"de geri geliyor.","Dört hafta sonra, ikimiz de sallantılı bir kaskadımız var. Daha da önemlisi, ikimiz de sabit bir alışkanlık kazandık. Eğer öğrenmek isteyen bir çocuğun varsa, onunla birlikte öğren. Birlikte yeni başlayan olmak çok değerli."]},"why-your-throws-drift-forward":{"title":"Atışlarınızın ileriye doğru kaymasının nedeni","summary":"Her kaskadı başladığınız yerden üç adım ileride bitiriyorsanız, atışlarınız sizden uzaklaşıyor demektir. Bunları eve getirmenin yolu şu.","body":["Her bir jongör yürüyüşü bilir. Kaskadı odanın ortasında başlatır ve burnunuz duvara değene kadar bitirirsiniz, deseni adım adım kovalayarak. Toplar sizin size doğru çekildiğini hissettirir. Değil. Topları birkaç santimetre ileri atıyorsunuz ve sonra onları yakalamak için yürüyorsunuz.","Nedeni neredeyse her zaman dirseklerdir. Gerildiğinizde, ön kollar ileriye doğru eğilir ve eller topu vücudunuzun biraz önünde bırakır. Her atış biraz daha uzağa düşer, bu yüzden bir sonraki yakalama daha uzağa olur, bu yüzden bir sonraki atış daha uzağa başlar. Bu hızla birikir.","Önce öğrettiğim düzeltme, dirsekleri içeri çekmek. Dirsekleri kaburgaların yakınında tutun, ön kolları yaklaşık olarak yatay tutun ve topları önlerinizin önünde değil, gözlerinizin üzerinden düz bir şekilde yukarı atın. Bir gün boyunca sıkıntılı hissettirir. Sonra sakin hissettirir.","İkinci düzeltme bir duvardır. Duvara dönük, yaklaşık bir kolluk uzaklıkta durun ve jonglaj yapın. Eğer atışlar kaymaya başlarsa, duvar hemen ve gürültülü bir şekilde size haber verir. On dakikalık duvar pratiği, vücudunuzun dik bir desenin nasıl hissettirdiğini, söyleyebileceğim her şeyden daha hızlı öğretir.","SynthFlow'un kamera modu da kaymayı izler. Bir adım boyunca torsonuzun kameraya göre ne kadar büyük göründüğünü takip eder, bu da sizin ona doğru yürüdüğünüzü anlamına gelir ve kısa bir ipucuyla sizi uyarır. 3D koç, temiz atışın yanında ileriye doğru bir atışın hayaletini de gösterebilir, böylece farkı duymak yerine görebilirsiniz.","Kayma bir karakter kusuru değil. Bu bir gerginlik alışkanlığıdır ve alışkanlıklar tekrarla değişir. Dirsekleri içeri çekin, dışa değil yukarı atın ve duvarın size dürüst olmanızı sağlayacak şekilde tutun."]},"practising-to-a-click":{"title":"Bir tıkla pratik yapmak","summary":"Bir metronom, dünyadaki en az eğlenceli şey gibi geliyor. Ama o, akışımın dans etmeye benzediğini hissettiren şey oldu.","body":["Yıllarca tıklamaya direndim. Müzik benim için akış sanatlarının amacıydı ve bir metronom ev ödevi gibi geliyordu. Sonra bir davul çalan arkadaşım bana jugglaj yaparken heyecanlandıkça hızlandığımı, korktuğumda ise yavaşladığımı nazikçe söyledi. Haklıydı ve bunu hiç fark etmemiştim.","Bu yüzden sadece bir tıkla bir hafta boyunca pratik yaptım. İlk keşif, sabit bir pulsu duygunun nasıl hissettiğinden daha zor olduğu oldu. İki elde bir patternim acele etmek istiyordu. Çubuk figür-8'im zayıf tarafta sürüklenmek istiyordu. Tık, nasıl hissettiğimle ilgilenmiyordu; sadece zamanı tutuyordu.","İkinci keşif, tıkın müziği daha kolay hale getirdiğiydi. Bir hafta sonra gerçek parçaları tekrar açtığımda, ritmin sesin içinde nerede olduğunu hissedebiliyordum. Zayıf zamanlamayla şarkılarla savaşmayı bıraktım ve hangi groove kısmına odaklanacağımı seçmeye başladım.","SynthFlow'un oluşturduğu perküsyon, tıkın daha dostça bir versiyonudur. Bir set seçersiniz, basit bir tık'tan el davullarına kadar ve her tempo ile çalır, böylece bir pattern tam olarak tutabildiğiniz hızda yaşayabilir. Ayrıca bir müzik parçasının altında sessizce bir rehber olarak çalışabilir. Her seansın ilk birkaç dakikasında hâlâ yalnızca bunu kullanıyorum.","Bunu denemek istiyorsanız, biraz yavaş gelen bir pattern ve bir tempo seçin. Dört bar boyunca sesli sayın, sonra saymayı bırakın ve sadece dinleyin. Pattern ve tık bir ses gibi hissettiklerinde, dört BPM ekleyin. Bu tamamı yöntemdir."]},"staff-in-a-small-apartment":{"title":"Küçük bir apartman da çalışan","summary":"1,4 metrelik bir çubuk ve 2,4 metre tavan birlikte yaşayabilir. Sadece düzlemlerini seçmeniz yeterli.","body":["Dairemde tavanlar alçak, sevdiğim bir aydınlatma ve gece çalıştır bir aşağı kat komşum var. Bunların hiçbiri çubuk döndürme için ideal değil. Çubuk döndürme için bir yıl boyunca parklarda pratik yaptım, ancak en sonunda çoğu eğitimimin yine de içeride yapılabilmesi gerektiğini anladım.","Sır, düzlemler. Vites-düzlemi dönmeleri, vücudun yanında büyük olanlar, çubuğun başınızın üzerinde tam yüksekliğe ihtiyaç duyar. Vücut önündeki duvar-düzlemi çalışmaları genişliğe ama daha az yüksekliğe ihtiyaç duyar. Zemin-düzlemi dönmeleri, helikopter gibi, başınızın üzerinde boşluk gerektirir ama baldırınızın etrafında hiçbir şeye ihtiyaç duymaz. Her oda farklı hareketlere destek olur.","Oturma odamda kollarım düşük seviyede olacak şekilde izolasyonlar, ön dönüşler ve yavaş 8 şeklinde hareketler yapabilirim. Koridorda ise hiçbir şey yapamam, bu yüzden koridor bilek ısınmaları için. Yatak odasının tavanı en yüksek, bu yüzden tekerlek-ucu çalışması orada, yavaşça, ışık fiksi çıkarılıp bir çekmecede saklanarak yapılır.","Kısa çubuklar da yardımcı olur. Performans çubuğumdan bir el uzunluğu daha kısa olan bir pratik çubuğu kullanmam, birçok neredeyse kaçırılmış hareketi kolayca geçirmeye dönüştürdü. Zamanlama biraz değişir, bu yüzden tam uzunluktaki çubuğumu haftada bir kez dışarıda kontrol ederim.","Komşular için: pratik matlar ve yumuşak uçlu çubuklar. Bir yoga matına düşmek, kırılgan bir ses yerine sönük bir ses çıkarır. Ayrıca iç mekan oturumlarını on dakikalık sayılabilir rutinlere kısıtlarım, bu da gürültüyü kısa tutar ve pratikte odaklanmayı sağlar.","SynthFlow, evde yapamadığınız hareketleri beğenilmedi olarak işaretlemenize olanak tanır, böylece oluşturucu bunları iç mekan rutinlerinden çıkarır. Küçük alanlar ilerlemeyi durdurmaz. Sadece izolasyonlarda çok iyi olmanızı sağlar."]},"hooping-after-40":{"title":"40'tan Sonra Hooping","summary":"43 yaşında ilk kez bir halka tuttum. Sırtım, dizlerim ve gururumun hepsinin fikri vardı. İşte işe yarayanlar.","body":["Bir festivalden sonra bir anlık düşüncemle ilk yetişkin halkamı aldım, korkuyordum ki berbat olacağım. Berbattım. Ama bir ay içinde bütün şarkılar boyunca belimde halka çevirmeye başlamıştım ve altı ay içinde basit dış vücut hareketleri yapmaya başlamıştım. Yaşım beni durdurmadı. Sadece nasıl pratik yapmam gerektiğini değiştirdi.","Büyük ders, doğru ısınmaktı. Kalça dönmeleri, gövde bükülmeleri ve nazik diz zıplamaları üç dakika sürer ve oturumun ilk halkasının gıcırtılı değil, akıcı hissetmesini sağlar. SynthFlow, ısınmaları her rutinin başına koymasının bir nedeni vardır ve bir sert sabah sonrası onları atlamayı bıraktım.","İkinci ders, halka boyutuydu. Daha büyük, biraz daha ağır bir halka daha yavaş döner, bu da size daha fazla zaman tanır ve alt sırtınıza daha az çaba ister. Yere durduğumda belimle göğsüm arasında ulaşan bir halka ile başladım ve hâlâ uzun pratik oturumlarım için kullanıyorum.","Üçüncü: dönmek yerine pulslamak. Yeni başlayanlar genellikle kalçalarını bir daire içinde sallar, bu da omurgayı gerekenden daha fazla bükülmeye zorlar. Ön-arka bir puls, veya halka bu şekilde dönüyorsa yan-yan, daha az zorlanma ile halkayı yukarıda tutar. 3D koçu, halkaya değil kalçalara bakarsanız bunu açıkça gösterir.","Son olarak, uzun ve ara sıra değil, kısa ve sık. Haftada dört kez on dakika, Pazar günü bir saatten daha çok işe yaradı. Vücudum oturumlar arasında iyileşti ve hareketler kalıcı oldu.","40 yaşın üzerindeyseniz ve merak ediyorsanız, başlayın. Halat, yaşınızı bilmez."]},"fire-and-the-beginner":{"title":"Ateş ve yeni başlayan","summary":"Ateş döndürme, akış sanatlarının en görünür kısmıdır ve yeni başlayanların en çok sorduğu kısım budur. Dürüst cevap: henüz değil, ve yalnız değil.","body":["Her hafta biri bize SynthFlow'un ateş öğretme zamanının ne olduğunu sorar. Adil bir soru. Ateş güzel, ve bir çok döndürücü, gece bir ateş çemberi görünce sahneye girer. Ama hiçbir zaman kimseye bir aleti yakma konusunda rehberlik yapmayacağız, ve bu yazı nedenini açıklar.","Ateş, beceriyle hiçbir ilgisi olmayan riskler ekler: yakıt işleme, giysiler, rüzgar, seyirciler, yanıklar ve söndürme. Bunlar, deneyimli kişilerden, eğitimli bir güvenlik görevlisiyle birlikte ve uygun ekipmanlar hazırken, kişisel olarak öğrenilir. Bir uygulama yakıt deponuzu, pamuklu giysilerinizi veya güvenlik havlunuzu kontrol edemez.","Uygulamanın yapabileceği şey, ateşten önce ona ihtiyaç duyan becerileri geliştirmenize yardımcı olmaktır. Bu, bir şarkı boyunca, sabit bir tempoda, düşürmeden güvenilir bir şekilde yapabileceğiniz hareketler anlamına gelir. Eğer bir desen evde pratik aletiyle hâlâ sizi şaşırtıyorsa, ateş için hazır değildir.","Ateş topluluğundan bir faydalı test: gözlerinizin yarısı kapalı, karanlıkta, biri sizinle konuşurken rutini yapabilir misiniz? Ateş parlak, sıcak ve gürültülüdür ve dikkatinizi çeker. Vücudunuz hareketleri denetim olmadan bilmelidir.","LED aletler, arada harika bir adım. Risk olmadan gece görünümünü, izleri ve seyirci tepkisini sağlarlar. SynthFlow'un LED stil paketi, desenlerinizin nasıl görüneceğini gösterir, bu da düzensiz düzlemleri tespit etmek için iyi bir yoldur.","Hazır olduğunuzda, yerel bir ateş topluluğunu bulun, kendinizi tanıtın ve önce güvenlik konusunda öğrenmek isteyin. O zamana kadar pratik aletlerle döndürün. Ateş hâlâ orada olacak."]},"four-balls-taught-me-patience":{"title":"Dört top bana sabır öğretti","summary":"Üç topdan dört topa geçiş, üç topu ilk kez öğrenmekten daha uzun sürdü ve pratikle ilgili düşüncelerimi değiştirdi.","body":["Üç top bana beş hafta sürdü. Dört top bana beş ay sürdü. Bana bunu kimse uyarımadı, bu yüzden size uyarıyorum: dört top, üç top artı bir değil. Tamamen farklı bir desen ve vücudunuz bunu sıfırdan öğrenmek zorunda.","Dört toplu bir şelalede, her el kendi başına iki top döndürür ve toplar asla kesişmez. Eller genellikle dönüşümlüdür, ancak aralarında hiçbir alışveriş olmaz. Diğer elden bir top yakalamakla ilgili öğrendiklerim tamamen işe yaramaz hale geldi.","Bu yüzden bir elime geri döndüm. İki top sağ elde sütunlar halinde, sonra da daireler çizerek, düşünmeden elli atış yapabildiğime kadar. Sonra sol el, bu üç kat daha uzun sürdü. Sonra iki el birlikte, önce senkronize, sonra dönüşlü. SynthFlow'daki tempolu merdiven bana burada yardımcı oldu: Her haftayı şelalenin alt kısmından başlayarak, temiz bir çalışma yaptıktan sonra yukarıya geçtim.","Sabır dersi, düzlemlerden geldi. Bazı haftalarda hiçbir şey gelişmiyordu. Yine de düşmeleri ve temiz atışları kaydediyordum ve grafik, hiçbir şey olmamış gibi hissettikçe yavaş ilerleme gösteriyordu. Veriler, sıkıcı haftaları katlanılabilir hale getirdi.","Diğer ders ise dinlenmeyle ilgiliydi. Dört top, üç top kadar kollarımı yormuyordu. Her gün pratik yaptığım zaman daha kötüye gidiyordum. Her iki günde bir pratik yaptığım zaman ise daha iyiye gidiyordum. El kavrama kasları diğer kaslar gibi dinlenmeye ihtiyaç duyar.","Eğer üç ile dört arasında sıkışıp kalırsanız, sorunu bölün, yavaş haftalara güvenin ve kollarınıza bir gün izin verin. O gelir."]},"the-escalator-and-hand-traffic":{"title":"Eskalator ve el trafiğinin sanatı","summary":"Hoop el hareketleri, iki el arasındaki dikkatli trafik yönetimi olduğunu görünceye kadar sihir gibi görünür.","body":["İlk kez bir merdivenli yürüyüşü gördüğümde, halka, hooper'ın kollarına tırmanıyor ve tekrar aşağıya süzülüyor gibi görünüyor, hiçbir açık tutuş olmaksızın. Yıllarca pratik gerektirdiğini düşündüm. Ancak bir kez el değişimlerinin sadece bir dizi model olduğunu anladığım zaman yaklaşık üç hafta sürdü.","Neredeyse tüm dış vücut halka hareketleri, hangi elin halkayı tuttuğu, ne zaman bırakıldığı ve diğer elin nerede onu yakaladığıyla ilgilidir. Eller arasındaki zamanlama bulanık olduğunda, halka düzleminden sallanır ve hareket parçalanır. Eğer zamanlama temizse, halka kendi kendine hareket ediyormuş gibi görünür.","Bu yüzden el değişimlerini isimlendirmeye başladım. SynthFlow'un sayımında, sayıları değil, el adlarını seslendirdim: sağ, sol, sağ, sol, her vuruşta birer tane. Bunları müziğin eşliğinde söylemek, sol elimin erken tuttuğunu fark etmemi sağladı. Erken tutmalar, neredeyse tüm sallanmaların kaynağıydı.","İkinci anahtar, halkayı düzlemde tutmaktı. Halkayı tutarken elin bükülmesi, halkayı eğik tutar ve eğik bir halka yarım saniye sonra düşer. Düzlem örtüsü burada yardımcı olur ve ayrıca yavaş tempolarla aynanın önünde pratik yapmak da yardımcı olur.","Merdivenli yürüyüş güvenilir hissettiğinde, diğer el hareketleri daha hızlı geldi. İzolasyonlar, geçişler ve lasso'lar aynı fikri kullanır: net el değişimleri, düz düzlemler, sabit zamanlama. Sihir sadece trafik yönetimidir."]},"behind-the-back-without-fear":{"title":"Korkusuzca arkadan","summary":"Çoğu sallayanın durduğu yer, staff'ın arkasından geçişlerdir. Sorun genellikle beceri değil, bakma isteği olur.","body":["Aylarca arkamdan geçişim, umut dolu bir dönüşle birlikte ön geçiş gibiydi. Hareketi başlatırdım, staff'ın görüşümün dışına çıktığında panikler, onu önümde geri getirirdim. Staff asla arkamdan geçmedi. Beynim izin vermiyordu.","Bir patlama, hareketi göremeyeceğimi kabul etmemle geldi. Arkadan geçişi izleyemezsin. Staff'ın nerede olduğunu, bırakıp bekleyen elden gelen hissiyle hissetmelisin ve güvenmelisin.","Bu hissi yavaş hareketle eğittim. Hiç dönmeksizin, gözlerim ileri bakarken, staff'ı elden ele arkamdan geçirdim. Sonra yavaş bir yarım dönüşle. Sonra hareketin tempoyla alt kısmında, sayarak. Her adım aptalca hissettiriyordu. Her adım işe yarıyordu.","3D koç şaşırtıcı derecede faydalıydı çünkü görünüşü döndürüp hareketi arkadan izleyebiliyordum. Ellerin birleştiği yeri ve staff'ın dönerken duvar düzleminde kalmasını görmek, vücuduma ön taraftan alamayacağı bir harita verdi.","İkinci korku kendime vurmak oldu. Yumuşak uçlu bir pratik staff ve büyük bir boş alan bu sorunu çözdü. Bir hata sadece hafif bir çarpma ile sonuçlanacak olursa, ben de titremeyi bıraktım ve titreme kayıpları neden oluyordu.","Eğer arkadan geçiş hâlâ sizi korkutuyorsa, tamamen yavaşlatın, dönmeyi çıkarın ve gözlerinizi ileri tutun. Elleriniz düşündüğünüzden daha çok şey biliyor."]},"why-reverse-feels-wrong":{"title":"Neden ters kaskad yanlış hissettiriyor","summary":"Ters kaskad, kaskad ile aynı elleri, aynı topları ve aynı ritmi kullanır. Peki neden yeniden başlamış gibi hissediyor?","body":["Ters kaskadı öğrenirken, bir öğleden sonra süreceğini bekliyordum. Aynı üç top, aynı el değişimleri ve aynı tempoyla kaskad ile aynı. Üç hafta sürdü ve nedenini anlayamıyordum.","Cevap yön. Normal bir kaskadda, her top kalıbın içinden atılır ve dışından yakalanır. Ters kaskadda, top dışarıdan atılır, gelen topun üstünden geçer ve içeriden yakalanır. Elleriniz aynı ritmi yapar ancak tamamen farklı şekiller oluşturur.","Yeni şekil zamanlamayı bozar. Kaskadda, gelen top düşmeye başladığında atarsınız. Tersinde, topun diğerinin tepesinden geçmesi için biraz daha erken atmanız gerekir. Eski anda atarsanız toplar çarpışır.","İlk önce iki top ile düzelttim. İki top, ters yönde, ritimle sayarak, otomatik hissetene kadar. Sonra üç top ile yavaş bir tempoda sayarak seslendirdim. SynthFlow'un hayalet üstü kaplaması bana tipik bir hata gösterdi, çok düşük bir atış ve diğer topu kesen bir atış, ve tam da bunu yaptığımı görebiliyordum.","Bir kere kilitlendiğinde, birçok şey açıldı. Kaskad ve ters karışımı birçok numaranın temelidir ve ters şekil Mills Mess'te tekrar ortaya çıkar. Üç hafta boyunca kötü olmak buna değerdi."]},"making-a-prop-stand-still":{"title":"İzolasyonlar: bir ekipmanı hareketsiz tutmak","summary":"Bir izolasyon, ekipmanın bir yerde kalıyormuş gibi göründüğü bir harekettir, siz etrafında hareket ederken. Akış sanatlarındaki en tatmin edici yanılsamadır.","body":["Bir çubuk izolasyonunu ilk kez başardığımda arkadaşım çubuğun nasıl yüzdüğünü sordu. Tabii ki yüzmüyordu. Çubuğun havada sabit kalan bir noktasını korumak için ellerim dikkatli bir daire çiziyordu. Ama dışarıdan bakıldığında imkânsız gibi görünüyordu ve bu his, izolasyonları sevmemin nedeni.","Her izolasyon aynı şekilde çalışır. Ekipmanın bir noktasını seçin, genellikle merkezini veya bir ucunu, ve ekipmanın geri kalanı dönerken bu noktayı hareketsiz tutun. Ellerinizin ekipmanın hareket etmek istediği yöne tam tersi şekilde hareket etmesi gerekir. Bu karşı intuitif ve hafifçe hipnotik.","En zor kısmı vücudunuzun da hareket etmesidir. Kalçalar kayar, omuzlar döner ve her küçük hareket sabit noktada sallanma olarak ortaya çıkar. Sabit noktanın nerede olması gerektiğini gösteren bir şerit ile camın önünde ayna önünde pratik yaptım. Eğer ekipmanın merkezi şeritten çıkarsa, biliyordum.","Hoop izolasyonları aynı fikri takip eder. SynthFlow'da 3D görüntüleyicide izleri açıyorum ve koçu izliyorum: temiz bir izolasyonda, sabit nokta etrafındaki iz çok küçük kalır. Tempoyu çok yavaşlatıp kopyaladığımda, her dairenin tepesinde ellerimin kaydığını hissedebiliyordum.","İzolasyonlar aynı zamanda her şeyi daha iyi yapmaya yardımcı olan kontrol sağlar. Bir ekipmanı sabit tutabildiğinizde, onu istediğiniz her yere yerleştirebilirsiniz. Uçaklar daha düzgün olur, geçişler daha temiz olur ve akışınız şanslı değil de bilinçli görünmeye başlar.","Yavaş başlayın, sabit noktayı işaretleyin ve kartal gibi ona bakın. Sonra bir arkadaşınıza gösterin ve yüzünü görün."]}}`),i={"zero-to-cascade":{name:`4 Haftada Sıfırdan Kaskad`,description:`Bir top, sonra iki, sonra üçüncü katılır. Günde kısa bir oturum yeterli: her haftanın rutinini bitirerek hareketini ustalaşın ve bir sonrakini açın.`,weeks:[{label:`1. Hafta · Bir top`},{label:`2. Hafta · İki top`},{label:`3. Hafta · Üçüncü top`},{label:`4. Hafta · Kaskad`}]},"beyond-the-cascade":{name:`Kaskadın Ötesinde`,description:`Üç top ile dört haftalık çeşitlilik: tenis ve pençe, ardından vücut atışları, ardından iki top ile senkron desenler.`,weeks:[{label:`1. Hafta · Tenis ve pençe`},{label:`2. Hafta · Yarım duş`},{label:`3. Hafta · Vücut atışları`},{label:`4. Hafta · Sütunlar`}]},"first-clubs":{name:`İlk kulplar`,description:`Tek bir dönen kulüpten başlayarak, sabit üç kulüp döngüsüne, ardından yükseklik ve dönüş kontrolü için çiftler.`,weeks:[{label:`1. Hafta · Bir kulup`},{label:`2. Hafta · Değişim`},{label:`3. Hafta · Kaskad`},{label:`4. Hafta · Çiftler`}]},"passing-with-a-partner":{name:`Partnerle geçiş`,description:`İki juggler, birbirine karşı. Bir top geçiş, ardından her biri birlikte bir ritimde iki top, ardından altı sayım, dört sayım ve iki sayım ile her biri üç top.`,weeks:[{label:`1. Hafta · Bir top geçişi`},{label:`2. Hafta · Her biri iki top`},{label:`3. Hafta · Altı sayım ve dört sayım`},{label:`4. Hafta · İki sayım`}]},"staff-foundations":{name:`Çubuk temelleri`,description:`Çark ve ön dönüşler, sekiz figürü ve geçiş: neredeyse her çubuk akışı bu dört hareketten oluşur.`,weeks:[{label:`1. Hafta · Çark dönüşü`},{label:`2. Hafta · Ön dönüş`},{label:`3. Hafta · Sekiz figürü`},{label:`4. Hafta · Geçiş`}]},"staff-contact":{name:`Kulup teması`,description:`Hafta hafta tutuşu gevşet: direksiyon tekeri ve balık kuyruğu, ardından el yuvarlamaları, ardından çubuğun ön kolda dönmesi.`,weeks:[{label:`1. Hafta · Direksiyon`},{label:`2. Hafta · Balık kuyruğu`},{label:`3. Hafta · El yuvarlama`},{label:`4. Hafta · Kol üstü yuvarlama`},{label:`Week 5 · Angel / session`}]},"double-staff-start":{name:`İki çubuk başlangıcı`,description:`İki çubukla adım atarak, her iki tarafta zaman ve tekerlekleri ayırarak.`,weeks:[{label:`1. Hafta · Aynı anda`},{label:`2. Hafta · Zaman ayrımı`},{label:`3. Hafta · Tekerlekler`},{label:`4. Hafta · Zaman ayrımı tekerlekler`}]},"hoop-body-ladder":{name:`Hoop vücut merdiveni`,description:`Belde her iki yönde halka çevirerek, sonra kalçalara ve uyluklara inip göğüse kadar.`,weeks:[{label:`1. Hafta · Her iki yön`},{label:`2. Hafta · Kalça`},{label:`3. Hafta · Uyluk`},{label:`4. Hafta · Göğüs kaldırma`}]},"hoop-doubles-start":{name:`Hoop çiftleri başlangıcı`,description:`Her elde bir halka: aynalı dönüşler, kaydırılmış dönüşler, yan dönüşler, sonra biri belde biri elde.`,weeks:[{label:`1. Hafta · Aynalı dönüşler`},{label:`2. Hafta · Kaydırılmış dönüşler`},{label:`3. Hafta · Yan dönüşler`},{label:`4. Hafta · Bel ve el`}]},"off-body-hoop":{name:`Vücut dışı hoop`,description:`Halkayı bir elde döndürmekten başlayarak, lasso, geçişler, çekişler ve halkanın yüzen gibi görünen izolasyonuna kadar.`,weeks:[{label:`1. Hafta · El dönüşü`},{label:`2. Hafta · Lasso ve geçiş`},{label:`3. Hafta · Wedgie`},{label:`4. Hafta · İzolasyon`},{label:`Week 5 · Planes + on↔off`}]},"first-poi":{name:`İlk poi`,description:`Bir poi, sonra bir çift: her iki yönde duvar dönüşleri, yanlarda tekerlekler, sonra zamanı böl.`,weeks:[{label:`1. Hafta · Bir poi`},{label:`2. Hafta · Duvar dönüşleri`},{label:`3. Hafta · Tekerlekler`},{label:`4. Hafta · Zaman ayrımı`}]},"poi-weave-ladder":{name:`Poi dokuma merdiveni`,description:`Güneşin peşinde koşmaktan her iki yönde üç ritimli dokuma, sonra daha hızlı iki ritimli dokumaya.`,weeks:[{label:`1. Hafta · Güneşi takip et`},{label:`2. Hafta · Üç vuruşlu dokuma`},{label:`3. Hafta · Ters dokuma`},{label:`4. Hafta · İki vuruşlu dokuma`},{label:`Week 5 · Five-beat / degrees`}]},"poi-antispin-start":{name:`Antispin başlangıcı`,description:`Öncelikle uzantılar ve izolasyonlar, sonra bir poi ile antispin ve iki ile dört yapraklı çiçek.`,weeks:[{label:`1. Hafta · Uzantılar`},{label:`2. Hafta · İzolasyon`},{label:`3. Hafta · Bir-poi antispin`},{label:`4. Hafta · Antispin çiçeği`},{label:`Week 5 · Hybrids`}]},"staff-tech-map":{name:`Staff tech map`,description:`Timing cells and flowers: symmetry lab, then isolation and antispin flower work.`,weeks:[{label:`Week 1 · Symmetry cells`},{label:`Week 2 · Figure 8`},{label:`Week 3 · Isolation`},{label:`Week 4 · Antispin flower`}]},"hoop-isolation-ladder":{name:`Hoop isolation ladder`,description:`Float isolations and cateyes, then reconnect with weave and pass.`,weeks:[{label:`Week 1 · Isolation`},{label:`Week 2 · Cateye`},{label:`Week 3 · Weave`},{label:`Week 4 · Pass link`}]}},a={"sf-ambient-70":{name:`Yavaş Orbit`},"sf-world-75":{name:`Pazar Adımları`},"sf-ambient-80":{name:`Fener Sürüklenmesi`},"sf-world-85":{name:`Çöl Tekerleği`},"sf-handdrum-90":{name:`Çember Davulu`},"sf-funk-95":{name:`Gevşek bilekler`},"sf-handdrum-100":{name:`Ateş Işığı Elleri`},"sf-world-105":{name:`Nehir Çanları`},"sf-funk-110":{name:`Ceb Kaskadı`},"sf-handdrum-115":{name:`Avlu Groovu`},"sf-electronic-120":{name:`Neon Çubuk`},"sf-funk-125":{name:`Sallanma Deseni`},"sf-electronic-130":{name:`Pixel Çember`},"sf-handdrum-135":{name:`Güneş Batımı Djembe`},"sf-electronic-140":{name:`LED İzleri`},"sf-funk-145":{name:`Dönen Döngü`},"sf-electronic-150":{name:`Stroboskop Akışı`},"sf-handdrum-155":{name:`Hızlı Palmiye`},"sf-electronic-160":{name:`Gece Dönen`}},o={poses:e,routines:t,learn:n,blog:r,progressions:i,music:a};export{r as blog,o as default,n as learn,a as music,e as poses,i as progressions,t as routines};